-- Easy Professions (Forever): guide texts in deDE (translated from wow-professions.com/forever)
local _, ns = ...
ns.AddTranslation("deDE", {
  ["This WoW Forever Alchemy leveling guide will show you the fastest and cheapest way to level your Alchemy skill from 1 to 300. You will also find every trainer location and where to train Alchemy past 75, 150 and 225."] = "Dieser WoW-Forever-Leitfaden für Alchimie zeigt dir den schnellsten und günstigsten Weg, deine Alchimie-Fertigkeit von 1 auf 300 zu steigern. Außerdem findest du alle Lehrer und erfährst, wo du Alchimie über 75, 150 und 225 hinaus erlernen kannst.",
  ["Below you will find the full shopping list, the Alchemy trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Alchemy is best combined with Herbalism, with these two you can save a lot of gold because you don't have to buy the herbs from the Auction House."] = "Unten findest du die vollständige Einkaufsliste, die Alchimielehrer nach Startgebiet und Hauptstadt sowie die günstigsten Rezepte für jeden Fertigkeitsbereich vom Lehrling bis zum Fachmann. Alchimie lässt sich am besten mit Kräuterkunde kombinieren. Mit diesen beiden sparst du viel Gold, weil du die Kräuter nicht im Auktionshaus kaufen musst.",
  ["This is based on the Forever beta. Leveling takes a long time, so testing the higher levels on live will take a while. If you find something that's off, send me feedback."] = "Dieser Leitfaden basiert auf der Forever-Beta. Das Leveln dauert lange, daher wird es eine Weile dauern, die höheren Stufen auf dem Live-Server zu testen. Wenn dir etwas Falsches auffällt, schick mir Feedback.",
  ["Shopping List"] = "Einkaufsliste",
  ["These numbers are estimates. Once a recipe turns yellow you won't get a skill point from every craft, so you might need a few more or a few less."] = "Diese Zahlen sind Schätzungen. Sobald ein Rezept gelb wird, bekommst du nicht mehr bei jeder Herstellung einen Fertigkeitspunkt, daher brauchst du eventuell etwas mehr oder etwas weniger.",
  ["Alchemy Trainer Locations"] = "Standorte der Alchimielehrer",
  ["Apprentice Alchemy has no level requirement in Forever, so you can learn it on a fresh character."] = "Alchimie (Lehrling) hat in Forever keine Stufenvoraussetzung, du kannst es also schon mit einem neuen Charakter erlernen.",
  ["Every capital city has a trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Jede Hauptstadt hat einen Lehrer. Du kannst auch eine Wache fragen, dann wird er mit einer roten Fahne auf deiner Karte markiert.",
  ["Alliance"] = "Allianz",
  ["Capital Cities"] = "Hauptstädte",
  ["Undercity: {n:0:horde:Doctor Martin Felben}"] = "Unterstadt: {n:0:horde:Doctor Martin Felben}",
  ["Thunder Bluff: {n:0:horde:Kray}"] = "Donnerfels: {n:0:horde:Kray}",
  ["Starting Zones"] = "Startgebiete",
  ["Not every zone has a trainer, the table shows the closest one for each race."] = "Nicht jedes Gebiet hat einen Lehrer. Die Tabelle zeigt den nächstgelegenen für jedes Volk.",
  ["Race"] = "Volk",
  ["Zone"] = "Gebiet",
  ["Closest trainer"] = "Nächster Lehrer",
  ["{n:0:horde:Miao'zan} in Sen'jin Village"] = "{n:0:horde:Miao'zan} im Dorf Sen'jin",
  ["There is no Alchemy trainer in Mulgore, go to {n:0:horde:Kray} on the middle rise in Thunder Bluff"] = "In Mulgore gibt es keinen Alchimielehrer, geh zu {n:0:horde:Kray} auf der mittleren Anhöhe in Donnerfels",
  ["Undead"] = "Untoter",
  ["Tirisfal Glades"] = "Tirisfal",
  ["{n:0:horde:Carolai Anise} in the small house at the north-west end of Brill"] = "{n:0:horde:Carolai Anise} im kleinen Haus am nordwestlichen Ende von Brill",
  ["{n:0::Iaadaria Bitterwind} or {n:0::Valiena Swiftgale} in Valanaar, {n:0::Nyassa Swiftdraught} in Shen'dar Village"] = "{n:0::Iaadaria Bitterwind} oder {n:0::Valiena Swiftgale} in Valanaar, {n:0::Nyassa Swiftdraught} in Shen'dar Village",
  ["Stormwind City: {n:0:alliance:Tel'Athir}"] = "Sturmwind: {n:0:alliance:Tel'Athir}",
  ["Ironforge: {n:0:alliance:Vosur Brakthel}"] = "Eisenschmiede: {n:0:alliance:Vosur Brakthel}",
  ["Human"] = "Mensch",
  ["Elwynn Forest"] = "Wald von Elwynn",
  ["{n:0:alliance:Alchemist Mallory} in a cottage in the hills between Stormwind and Northshire"] = "{n:0:alliance:Alchemist Mallory} in einer Hütte in den Hügeln zwischen Sturmwind und Nordhain",
  ["Dwarf, Gnome"] = "Zwerg, Gnom",
  ["There is no Alchemy trainer in Dun Morogh, go to {n:0:alliance:Vosur Brakthel} in Tinker Town in Ironforge"] = "In Dun Morogh gibt es keinen Alchimielehrer, geh zu {n:0:alliance:Vosur Brakthel} in der Tüftlerstadt in Eisenschmiede",
  ["Night Elf"] = "Nachtelf",
  ["{n:0:alliance:Cyndra Kindwhisper} in a small house east of the inn in Dolanaar"] = "{n:0:alliance:Cyndra Kindwhisper} in einem kleinen Haus östlich des Gasthauses in Dolanaar",
  ["You can find every Alchemy trainer for Horde and Alliance on my WoW Forever Alchemy Trainers page."] = "Alle Alchimielehrer für Horde und Allianz findest du auf meiner Seite zu den WoW-Forever-Alchimielehrern.",
  ["Apprentice Alchemy (1-55)"] = "Alchimie (Lehrling) (1-55)",
  ["9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Silverleaf, 9 Empty Vial"] = "9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Silberblatt, 9 Leere Phiole",
  ["The vials are sold by Alchemy Supply and Trade Supply vendors, most trainers have one nearby. In Undercity the closest one is {n:0:horde:Algernon}, in Dolanaar it's {n:0:alliance:Narret Shadowgrove}."] = "Die Phiolen werden von Händlern für Alchimiebedarf und Handwerkswaren verkauft, die meisten Lehrer haben einen in der Nähe. In Unterstadt ist {n:0:horde:Algernon} der nächste, in Dolanaar ist es {n:0:alliance:Narret Shadowgrove}.",
  ["45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Silverleaf, 45 Peacebloom, 45 Empty Vial"] = "45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Silberblatt, 45 Friedensblume, 45 Leere Phiole",
  ["Journeyman Alchemy (55-150)"] = "Alchimie (Geselle) (55-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Alchemy. You need {b}Alchemy 50{/b} and {b}level 10{/b}:"] = "Um über 75 hinauszukommen, besuche einen dieser Lehrer und erlerne Alchimie (Geselle). Du brauchst {b}Alchimie 50{/b} und {b}Stufe 10{/b}:",
  ["{b}Horde trainers:{/b}"] = "{b}Lehrer der Horde:{/b}",
  ["Undercity: {n:0:horde:Doctor Marsh}"] = "Unterstadt: {n:0:horde:Doctor Marsh}",
  ["Thunder Bluff: {n:0:horde:Bena Winterhoof}"] = "Donnerfels: {n:0:horde:Bena Winterhoof}",
  ["{b}Alliance trainers:{/b}"] = "{b}Lehrer der Allianz:{/b}",
  ["Stormwind City: {n:0:alliance:Lilyssia Nightbreeze}"] = "Sturmwind: {n:0:alliance:Lilyssia Nightbreeze}",
  ["Ironforge: {n:0:alliance:Tally Berryfizz}"] = "Eisenschmiede: {n:0:alliance:Tally Berryfizz}",
  ["10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Mageroyal, 10 Peacebloom, 10 Empty Vial"] = "10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Maguskönigskraut, 10 Friedensblume, 10 Leere Phiole",
  ["28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Earthroot, 28 Peacebloom, 28 Empty Vial"] = "28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Erdwurzel, 28 Friedensblume, 28 Leere Phiole",
  ["30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Mageroyal, 60 Briarthorn, 30 Empty Vial"] = "30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Maguskönigskraut, 60 Wilddornrose, 30 Leere Phiole",
  ["Keep the elixirs if you also level Tailoring, you will need them for the Gloves of Meditation."] = "Behalte die Elixiere, wenn du auch Schneiderei levelst, du brauchst sie für die Handschuhe der Meditation.",
  ["10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Mageroyal, 10 Stranglekelp, 10 Empty Vial"] = "10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Maguskönigskraut, 10 Würgetang, 10 Leere Phiole",
  ["20x {s:7837:inv_potion_38:Fire Oil} - 40 Firefin Snapper, 20 Empty Vial"] = "20x {s:7837:inv_potion_38:Fire Oil} - 40 Feuerflossenschnapper, 20 Leere Phiole",
  ["You get 2 oils from every craft. Keep 30 of them, you will need them for the Elixir of Fire Power in the next part."] = "Du bekommst 2 Öle pro Herstellung. Behalte 30 davon, du brauchst sie im nächsten Abschnitt für das Elixier der Feuermacht.",
  ["Expert Alchemy (150-225)"] = "Alchimie (Experte) (150-225)",
  ["To train past 150, visit {n:0:horde:Doctor Herbert Halsey} in Undercity (Horde) or {n:0:alliance:Ainethil} in Darnassus (Alliance) and learn Expert Alchemy. You need {b}Alchemy 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Um über 150 hinauszukommen, besuche {n:0:horde:Doctor Herbert Halsey} in Unterstadt (Horde) oder {n:0:alliance:Ainethil} in Darnassus (Allianz) und erlerne Alchimie (Experte). Du brauchst {b}Alchimie 125{/b} und {b}Stufe 20{/b}, und es kostet 50 Silber.",
  ["15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Fire Oil, 15 Kingsblood, 15 Leaded Vial"] = "15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Feueröl, 15 Königsblut, 15 Bleiphiole",
  ["These are the Fire Oils you kept."] = "Das sind die Feueröle, die du behalten hast.",
  ["36x {s:3452:inv_potion_72:Mana Potion} - 36 Stranglekelp, 36 Kingsblood, 36 Leaded Vial"] = "36x {s:3452:inv_potion_72:Mana Potion} - 36 Würgetang, 36 Königsblut, 36 Bleiphiole",
  ["36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Liferoot, 36 Stranglekelp, 36 Leaded Vial"] = "36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Lebenswurz, 36 Würgetang, 36 Bleiphiole",
  ["{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} is sold by these vendors, it's bind on pickup, so buy it with the character that levels Alchemy:"] = "{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} wird von diesen Händlern verkauft. Es wird beim Aufheben gebunden, kauf es also mit dem Charakter, der Alchimie levelt:",
  ["{n:0::Glyx Brewright} in Stranglethorn Vale"] = "{n:0::Glyx Brewright} im Schlingendorntal",
  ["Artisan Alchemy (225-300)"] = "Alchimie (Fachmann) (225-300)",
  ["To train past 225, visit {n:0:horde:Rogvar} in Stonard, Swamp of Sorrows (Horde) or {n:0:alliance:Kylanna Windwhisper} in Feathermoon Stronghold, Feralas (Alliance) and learn Artisan Alchemy. You need {b}Alchemy 200{/b} and {b}level 35{/b}."] = "Um über 225 hinauszukommen, besuche {n:0:horde:Rogvar} in Steinard, Sümpfe des Elends (Horde) oder {n:0:alliance:Kylanna Windwhisper} in der Mondfederfeste, Feralas (Allianz) und erlerne Alchimie (Fachmann). Du brauchst {b}Alchimie 200{/b} und {b}Stufe 35{/b}.",
  ["26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Liferoot, 26 Stranglekelp, 26 Leaded Vial"] = "26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Lebenswurz, 26 Würgetang, 26 Bleiphiole",
  ["15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Blindweed, 15 Khadgar's Whisker, 15 Crystal Vial"] = "15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Blindkraut, 15 Khadgars Schnurrbart, 15 Kristallphiole",
  ["47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Stonescale Eel, 47 Leaded Vial"] = "47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Steinschuppenaal, 47 Bleiphiole",
  ["{b}Keep all of them{/b}, one craft makes 2 and the elixirs at 265 need all 94."] = "{b}Behalte sie alle{/b}, eine Herstellung ergibt 2 und die Elixiere bei 265 brauchen alle 94.",
  ["Alternative recipe"] = "Alternatives Rezept",
  ["If {i:13422:inv_misc_fish_11:Stonescale Eel} is expensive, skip this and keep making the Elixir of Greater Intellect until 265 (about 21), then make the Superior Mana Potions under 265-300."] = "Wenn {i:13422:inv_misc_fish_11:Stonescale Eel} teuer ist, überspring das und stell weiter das Elixier der großen Intelligenz her bis 265 (etwa 21), dann mach die erheblichen Manatränke unter 265-300.",
  ["10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Blindweed, 10 Khadgar's Whisker, 10 Crystal Vial"] = "10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Blindkraut, 10 Khadgars Schnurrbart, 10 Kristallphiole",
  ["47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Stonescale Oil, 47 Sungrass, 47 Crystal Vial"] = "47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Steinschuppenöl, 47 Sonnengras, 47 Kristallphiole",
  ["{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} is sold by {n:0:horde:Kor'geld} in Orgrimmar and {n:0:alliance:Soolie Berryfizz} in Ironforge."] = "{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} wird von {n:0:horde:Kor'geld} in Orgrimmar und {n:0:alliance:Soolie Berryfizz} in Eisenschmiede verkauft.",
  ["If you skipped the Stonescale Oil, make this:"] = "Wenn du das Steinschuppenöl übersprungen hast, stell das hier her:",
  ["55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Sungrass, 110 Blindweed, 55 Crystal Vial."] = "55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Sonnengras, 110 Blindkraut, 55 Kristallphiole.",
  ["{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} is sold by {n:0:horde:Algernon} in Undercity and {n:0:alliance:Ulthir} in Darnassus."] = "{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} wird von {n:0:horde:Algernon} in Unterstadt und {n:0:alliance:Ulthir} in Darnassus verkauft.",
  ["This WoW Forever Blacksmithing leveling guide will show you the fastest and cheapest way to level your Blacksmithing skill from 1 to 300. You will also find every trainer location and where to train Blacksmithing past 75, 150 and 225."] = "Dieser WoW-Forever-Leitfaden für Schmiedekunst zeigt dir den schnellsten und günstigsten Weg, deine Schmiedekunst-Fertigkeit von 1 auf 300 zu steigern. Außerdem findest du alle Lehrer und erfährst, wo du Schmiedekunst über 75, 150 und 225 hinaus erlernen kannst.",
  ["Below you will find the full shopping list, the Blacksmithing trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Blacksmithing uses a lot of ore, so I recommend leveling it together with Mining, you will need a lot of gold if you want to buy everything from the Auction House."] = "Unten findest du die vollständige Einkaufsliste, die Schmiedekunstlehrer nach Startgebiet und Hauptstadt sowie die günstigsten Rezepte für jeden Fertigkeitsbereich vom Lehrling bis zum Fachmann. Schmiedekunst verbraucht viel Erz, daher empfehle ich, es zusammen mit Bergbau zu leveln. Wenn du alles im Auktionshaus kaufen willst, brauchst du viel Gold.",
  ["The Thorium Bars include the 140 you need for the four quests."] = "Die Thoriumbarren beinhalten die 140, die du für die vier Quests brauchst.",
  ["Blacksmithing Trainer Locations"] = "Standorte der Schmiedekunstlehrer",
  ["Apprentice Blacksmithing has no level requirement in Forever, so you can learn it on a fresh character."] = "Schmiedekunst (Lehrling) hat in Forever keine Stufenvoraussetzung, du kannst es also schon mit einem neuen Charakter erlernen.",
  ["Every capital city has a trainer except Darnassus. You can also ask a guard, then it will be marked with a red flag on your map."] = "Jede Hauptstadt außer Darnassus hat einen Lehrer. Du kannst auch eine Wache fragen, dann wird er mit einer roten Fahne auf deiner Karte markiert.",
  ["Undercity: {n:0:horde:Basil Frye}"] = "Unterstadt: {n:0:horde:Basil Frye}",
  ["Thunder Bluff: {n:0:horde:Thrag Stonehoof}"] = "Donnerfels: {n:0:horde:Thrag Stonehoof}",
  ["{n:0:horde:Dwukk} at the forge in Razor Hill"] = "{n:0:horde:Dwukk} an der Schmiede in Klingenhügel",
  ["There is no Blacksmithing trainer in Mulgore, go to {n:0:horde:Thrag Stonehoof} on the lower rise in Thunder Bluff"] = "In Mulgore gibt es keinen Schmiedekunstlehrer, geh zu {n:0:horde:Thrag Stonehoof} auf der unteren Anhöhe in Donnerfels",
  ["{n:0:horde:Angus Hammerhand} at Bandarion Keep. Nobody near him sells a {i:5956:inv_hammer_20:Blacksmith Hammer}, {b}buy one before you go{/b} from {n:0:horde:Walter Mason} in Deathknell or {n:0:horde:Abigail Shiel} in Brill."] = "{n:0:horde:Angus Hammerhand} in Bandarion Keep. In seiner Nähe verkauft niemand einen {i:5956:inv_hammer_20:Blacksmith Hammer}, {b}kauf einen, bevor du hingehst{/b}, bei {n:0:horde:Walter Mason} in Todesend oder {n:0:horde:Abigail Shiel} in Brill.",
  ["Stormwind City: {n:0:alliance:Dane Lindgren}"] = "Sturmwind: {n:0:alliance:Dane Lindgren}",
  ["Ironforge: {n:0:alliance:Groum Stonebeard}"] = "Eisenschmiede: {n:0:alliance:Groum Stonebeard}",
  ["{n:0:alliance:Smith Argus} in Goldshire, across from the inn"] = "{n:0:alliance:Smith Argus} in Goldhain, gegenüber dem Gasthaus",
  ["{n:0:alliance:Tognus Flintfire} in Kharanos, across from the Thunderbrew Distillery"] = "{n:0:alliance:Tognus Flintfire} in Kharanos, gegenüber der Donnerbräu-Brauerei",
  ["There is no Blacksmithing trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Delfrum Flintbeard} in Auberdine, Darkshore"] = "In Teldrassil und Darnassus gibt es keinen Schmiedekunstlehrer, der nächste ist {n:0:alliance:Delfrum Flintbeard} in Auberdine, Dunkelküste",
  ["You can find every Blacksmithing trainer for Horde and Alliance on my WoW Forever Blacksmithing Trainers page."] = "Alle Schmiedekunstlehrer für Horde und Allianz findest du auf meiner Seite zu den WoW-Forever-Schmiedekunstlehrern.",
  ["Apprentice Blacksmithing (1-75)"] = "Schmiedekunst (Lehrling) (1-75)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer} when you learn Blacksmithing, most recipes need it, so you can craft gear for yourself while you level. It costs a few copper, open your faction below to see who sells it closest to your trainer."] = "Kauf einen {i:5956:inv_hammer_20:Blacksmith Hammer}, wenn du Schmiedekunst erlernst. Die meisten Rezepte brauchen ihn, so kannst du beim Leveln Ausrüstung für dich selbst herstellen. Er kostet ein paar Kupfer. Öffne unten deine Fraktion, um zu sehen, wer ihn am nächsten zu deinem Lehrer verkauft.",
  ["Horde vendors"] = "Händler der Horde",
  ["Vendor"] = "Händler",
  ["{n:0:horde:Sumi}, right next to the trainer"] = "{n:0:horde:Sumi}, direkt neben dem Lehrer",
  ["Undercity"] = "Unterstadt",
  ["{n:0:horde:Samuel Van Brunt}, right next to the trainer"] = "{n:0:horde:Samuel Van Brunt}, direkt neben dem Lehrer",
  ["Thunder Bluff"] = "Donnerfels",
  ["{n:0:horde:Taur Stonehoof}, right next to the trainer"] = "{n:0:horde:Taur Stonehoof}, direkt neben dem Lehrer",
  ["{n:0:horde:Flakk} in Razor Hill"] = "{n:0:horde:Flakk} in Klingenhügel",
  ["{n:0:horde:Walter Mason} in Deathknell {n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Walter Mason} in Todesend {n:0:horde:Abigail Shiel} in Brill",
  ["{n:0::Halavuul Cragwind}, the Mining trainer in Valanaar {n:0::Aedi Thriceforged} in Shen'dar Village"] = "{n:0::Halavuul Cragwind}, der Bergbaulehrer in Valanaar {n:0::Aedi Thriceforged} in Shen'dar Village",
  ["Alliance vendors"] = "Händler der Allianz",
  ["Stormwind City"] = "Sturmwind",
  ["{n:0:alliance:Kaita Deepforge}, right next to the trainer"] = "{n:0:alliance:Kaita Deepforge}, direkt neben dem Lehrer",
  ["Ironforge"] = "Eisenschmiede",
  ["{n:0:alliance:Thurgrum Deepforge}, right next to the trainer"] = "{n:0:alliance:Thurgrum Deepforge}, direkt neben dem Lehrer",
  ["{n:0:alliance:Tharynn Bouden} in Goldshire"] = "{n:0:alliance:Tharynn Bouden} in Goldhain",
  ["{n:0:alliance:Thrawn Boltar}, right next to the trainer"] = "{n:0:alliance:Thrawn Boltar}, direkt neben dem Lehrer",
  ["Darkshore"] = "Dunkelküste",
  ["{n:0:alliance:Elisa Steelhand} in Auberdine, right next to the trainer"] = "{n:0:alliance:Elisa Steelhand} in Auberdine, direkt neben dem Lehrer",
  ["30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Rough Stone"] = "30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Rauer Stein",
  ["30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Rough Stone"] = "30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Rauer Stein",
  ["Keep 10 of them, you need them for the Silver Rods at 75."] = "Behalte 10 davon, du brauchst sie für die Silberruten bei 75.",
  ["36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Coarse Stone"] = "36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Grober Stein",
  ["Make all 36, you will need them for the bracers at 95 and 112."] = "Stell alle 36 her, du brauchst sie für die Armschienen bei 95 und 112.",
  ["If you are not at 75 after these, make a few more."] = "Wenn du danach noch nicht bei 75 bist, stell noch ein paar mehr her.",
  ["Journeyman Blacksmithing (75-150)"] = "Schmiedekunst (Geselle) (75-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Blacksmithing. You need {b}Blacksmithing 50{/b} and {b}level 10{/b}:"] = "Um über 75 hinauszukommen, besuche einen dieser Lehrer und erlerne Schmiedekunst (Geselle). Du brauchst {b}Schmiedekunst 50{/b} und {b}Stufe 10{/b}:",
  ["Undercity: {n:0:horde:James Van Brunt}"] = "Unterstadt: {n:0:horde:James Van Brunt}",
  ["Thunder Bluff: {n:0:horde:Karn Stonehoof}"] = "Donnerfels: {n:0:horde:Karn Stonehoof}",
  ["Tirisfal Glades: {n:0:horde:Angus Hammerhand} at Bandarion Keep"] = "Tirisfal: {n:0:horde:Angus Hammerhand} in Bandarion Keep",
  ["Stormwind City: {n:0:alliance:Therum Deepforge}"] = "Sturmwind: {n:0:alliance:Therum Deepforge}",
  ["Ironforge: {n:0:alliance:Rotgath Stonebeard}"] = "Eisenschmiede: {n:0:alliance:Rotgath Stonebeard}",
  ["5x {s:7818:inv_staff_01:Silver Rod} - 5 Silver Bar, 10 Rough Grinding Stone"] = "5x {s:7818:inv_staff_01:Silver Rod} - 5 Silberbarren, 10 Rauer Schleifstein",
  ["You need the {i:5956:inv_hammer_20:Blacksmith Hammer} from here on."] = "Ab hier brauchst du den {i:5956:inv_hammer_20:Blacksmith Hammer}.",
  ["Make 5x {s:2666:inv_belt_03:Runed Copper Belt} instead (10 Copper Bar each) if one Silver Bar costs more than 10 Copper Bars."] = "Stell stattdessen 5x {s:2666:inv_belt_03:Runed Copper Belt} her (je 10 Kupferbarren), wenn ein Silberbarren mehr kostet als 10 Kupferbarren.",
  ["18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Copper Bar"] = "18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Kupferbarren",
  ["5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Bronze Bar, 10 Coarse Grinding Stone"] = "5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Bronzebarren, 10 Grober Schleifstein",
  ["Use 10 of the Coarse Grinding Stones you made at 50 and keep the other 26 for 112."] = "Verwende 10 der groben Schleifsteine, die du bei 50 hergestellt hast, und behalte die anderen 26 für 112.",
  ["20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Heavy Stone"] = "20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Schwerer Stein",
  ["Keep them, you need all 20 for the Golden Scale Bracers at 180."] = "Behalte sie, du brauchst alle 20 für die Goldschuppenarmschienen bei 180.",
  ["13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Bronze Bar, 26 Coarse Grinding Stone"] = "13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Bronzebarren, 26 Grober Schleifstein",
  ["24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Bronze Bar, 96 Weak Flux, 48 Medium Leather"] = "24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Bronzebarren, 96 Schwaches Flussmittel, 48 Mittleres Leder",
  ["I recommend these over the Patterned Bronze Bracers because they sell for more than twice as much to a vendor, so they end up cheaper."] = "Ich empfehle diese statt der gemusterten Bronzearmschienen, weil sie beim Händler mehr als doppelt so viel einbringen und am Ende günstiger sind.",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} and the {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} for the Bronze Warhammers (140-150) are sold by the Blacksmithing Supply vendor right next to the Blacksmithing trainer in every capital city."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} und das {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} für die Bronzekriegshämmer (140-150) werden vom Händler für Schmiedebedarf direkt neben dem Schmiedekunstlehrer in jeder Hauptstadt verkauft.",
  ["If you disenchant your greens:"] = "Wenn du deine grünen Gegenstände entzauberst:",
  ["24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Bronze Bar, 48 Coarse Grinding Stone."] = "24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Bronzebarren, 48 Grober Schleifstein.",
  ["10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Bronze Bar, 10 Strong Flux, 10 Medium Leather"] = "10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Bronzebarren, 10 Starkes Flussmittel, 10 Mittleres Leder",
  ["Expert Blacksmithing (150-215)"] = "Schmiedekunst (Experte) (150-215)",
  ["To train past 150, visit {n:0:horde:Saru Steelfury} in Orgrimmar (Horde) or {n:0:alliance:Bengus Deepforge} in Ironforge (Alliance) and learn Expert Blacksmithing. You need {b}Blacksmithing 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Um über 150 hinauszukommen, besuche {n:0:horde:Saru Steelfury} in Orgrimmar (Horde) oder {n:0:alliance:Bengus Deepforge} in Eisenschmiede (Allianz) und erlerne Schmiedekunst (Experte). Du brauchst {b}Schmiedekunst 125{/b} und {b}Stufe 20{/b}, und es kostet 50 Silber.",
  ["30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Iron Bar, 30 Green Dye"] = "30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Eisenbarren, 30 Grüner Farbstoff",
  ["Green Dye is sold by {n:0:horde:Tamar} in Orgrimmar and {n:0:alliance:Bombus Finespindle} in Ironforge."] = "Grüner Farbstoff wird von {n:0:horde:Tamar} in Orgrimmar und {n:0:alliance:Bombus Finespindle} in Eisenschmiede verkauft.",
  ["8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Solid Stone"] = "8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Robuster Stein",
  ["Keep them, you need 6 for the Heavy Mithril Axes at 210."] = "Behalte sie, du brauchst 6 für die schweren Mithrilsäxte bei 210.",
  ["20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Steel Bar, 40 Heavy Grinding Stone"] = "20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Stahlbarren, 40 Schwerer Schleifstein",
  ["Use the 20 Heavy Grinding Stones you made at 100 and make 20 more (60 {i:2838:inv_stone_12:Heavy Stone})."] = "Verwende die 20 schweren Schleifsteine, die du bei 100 hergestellt hast, und stell 20 weitere her (60 {i:2838:inv_stone_12:Heavy Stone}).",
  ["If you have Mining 165, you can smelt the {i:3859:inv_ingot_steel:Steel Bars} yourself from {i:3575:inv_ingot_iron:Iron Bar} and {i:3857:inv_ore_tin_01:Coal}. Coal is sold by the Blacksmithing Supply vendor next to the Blacksmithing trainer in every capital city."] = "Wenn du Bergbau 165 hast, kannst du die {i:3859:inv_ingot_steel:Steel Bars} selbst aus {i:3575:inv_ingot_iron:Iron Bar} und {i:3857:inv_ore_tin_01:Coal} verhütten. Kohle wird vom Händler für Schmiedebedarf neben dem Schmiedekunstlehrer in jeder Hauptstadt verkauft.",
  ["Alliance players should keep 6 of these. You might need them if you choose Armorsmithing."] = "Spieler der Allianz sollten 6 davon behalten. Du könntest sie brauchen, wenn du Rüstungsschmied wählst.",
  ["17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Mithril Bar"] = "17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Mithrilbarren",
  ["I recommend these over the Heavy Mithril Gauntlets because they sell for more than three times as much to a vendor, so they end up cheaper."] = "Ich empfehle diese statt der schweren Mithrilstulpen, weil sie beim Händler mehr als dreimal so viel einbringen und am Ende günstiger sind.",
  ["6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Mithril Bar, 12 Citrine, 6 Solid Grinding Stone, 24 Heavy Leather"] = "6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Mithrilbarren, 12 Citrin, 6 Robuster Schleifstein, 24 Schweres Leder",
  ["Keep 2 of these. You might need them if you choose Weaponsmithing."] = "Behalte 2 davon. Du könntest sie brauchen, wenn du Waffenschmied wählst.",
  ["Blacksmithing Specializations"] = "Spezialisierungen der Schmiedekunst",
  ["At {b}Blacksmithing 200{/b} and {b}level 40{/b}, you can specialize in Armorsmithing or Weaponsmithing to craft powerful armor or weapons. Choosing one is optional, you don't need it to level Blacksmithing, and you can choose later too."] = "Mit {b}Schmiedekunst 200{/b} und {b}Stufe 40{/b} kannst du dich auf Rüstungsschmied oder Waffenschmied spezialisieren, um mächtige Rüstungen oder Waffen herzustellen. Die Wahl ist optional, du brauchst sie nicht, um Schmiedekunst zu leveln, und du kannst dich auch später entscheiden.",
  ["For information on how to become an Armorsmith or a Weaponsmith, please see my separate guides:"] = "Informationen dazu, wie du Rüstungsschmied oder Waffenschmied wirst, findest du in meinen separaten Leitfäden:",
  ["Artisan Blacksmithing (215-300)"] = "Schmiedekunst (Fachmann) (215-300)",
  ["To train past 225, visit {n:0::Brikk Keencraft} in Booty Bay, Stranglethorn Vale and learn Artisan Blacksmithing. You need {b}Blacksmithing 200{/b} and {b}level 35{/b}, and both factions learn it there."] = "Um über 225 hinauszukommen, besuche {n:0::Brikk Keencraft} in Beutebucht, Schlingendorntal, und erlerne Schmiedekunst (Fachmann). Du brauchst {b}Schmiedekunst 200{/b} und {b}Stufe 35{/b}, und beide Fraktionen erlernen es dort.",
  ["{i:7989:inv_scroll_06:Plans: Mithril Spurs} is a world drop. If you already have it, you can use the {b}Mithril Spurs{/b} tab instead."] = "{i:7989:inv_scroll_06:Plans: Mithril Spurs} ist ein Weltdrop. Wenn du ihn schon hast, kannst du stattdessen den Reiter {b}Mithrilsporen{/b} verwenden.",
  ["Heavy Mithril"] = "Schweres Mithril",
  ["Mithril Spurs"] = "Mithrilsporen",
  ["10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Mithril Bar"] = "10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Mithrilbarren",
  ["Keep 2 of these. You might need them if you choose Armorsmithing."] = "Behalte 2 davon. Du könntest sie brauchen, wenn du Rüstungsschmied wählst.",
  ["5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Dense Stone"] = "5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Verdichteter Stein",
  ["16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Mithril Bar, 64 Thick Leather"] = "16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Mithrilbarren, 64 Dickes Leder",
  ["5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Thorium Bar, 30 Rugged Leather, 5 Aquamarine"] = "5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Thoriumbarren, 30 Unverwüstliches Leder, 5 Aquamarin",
  ["You can get the recipe from the {q:7653::Imperial Plate Belt} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it. Do his {q:7652::A Blue Light Bargain} quest first, it unlocks the Imperial Plate quests."] = "Das Rezept bekommst du über die Quest {q:7653::Imperial Plate Belt} (erfordert {b}Stufe 50{/b}) in Tanaris von {n:14567::Derotain Mudsipper}. Du brauchst 20 Thoriumbarren, um sie abzuschließen. Mach zuerst seine Quest {q:7652::A Blue Light Bargain}, sie schaltet die imperialen Plattenquests frei.",
  ["{b}The next three recipes are also from the same NPC{/b}, so make sure to bring at least 140 Thorium Bar with you to get all 4 recipes."] = "{b}Die nächsten drei Rezepte stammen ebenfalls vom selben NPC{/b}, bring also mindestens 140 Thoriumbarren mit, um alle 4 Rezepte zu bekommen.",
  ["If you have the plans for one of these world drops, you can make it from 240 instead:"] = "Wenn du die Pläne für einen dieser Weltdrops hast, kannst du ihn stattdessen ab 240 herstellen:",
  ["240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Mithril Bar, 27 Aquamarine, 54 Lesser Moonstone, 54 Moss Agate, 27 Solid Grinding Stone, 54 Mageweave Cloth"] = "240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Mithrilbarren, 27 Aquamarin, 54 Geringer Mondstein, 54 Moosachat, 27 Robuster Schleifstein, 54 Magiestoff",
  ["240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Mithril Bar, 40 Core of Earth, 20 Solid Grinding Stone, 80 Thick Leather"] = "240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Mithrilbarren, 40 Erdkern, 20 Robuster Schleifstein, 80 Dickes Leder",
  ["240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Thorium Bar, 68 Blue Power Crystal"] = "240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Thoriumbarren, 68 Blauer Machtkristall",
  ["10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Mithril Bar, 30 Solid Grinding Stone (120 Solid Stone)"] = "10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Mithrilbarren, 30 Robuster Schleifstein (120 Robuster Stein)",
  ["33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Mithril Bar, 99 Solid Grinding Stone (396 Solid Stone)"] = "33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Mithrilbarren, 99 Robuster Schleifstein (396 Robuster Stein)",
  ["{b}The next three recipes all come from one NPC in Tanaris{/b}, so make sure to bring at least 120 Thorium Bar with you to get all 3 recipes."] = "{b}Die nächsten drei Rezepte stammen alle von einem NPC in Tanaris{/b}, bring also mindestens 120 Thoriumbarren mit, um alle 3 Rezepte zu bekommen.",
  ["27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Thorium Bar, 27 Star Ruby"] = "27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Thoriumbarren, 27 Sternrubin",
  ["You get the recipe from the {q:7655::Imperial Plate Bracer} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it."] = "Das Rezept bekommst du über die Quest {q:7655::Imperial Plate Bracer} (erfordert {b}Stufe 50{/b}) in Tanaris von {n:14567::Derotain Mudsipper}. Du brauchst 20 Thoriumbarren, um sie abzuschließen.",
  ["20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Thorium Bar, 20 Star Ruby, 20 Aquamarine"] = "20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Thoriumbarren, 20 Sternrubin, 20 Aquamarin",
  ["You get the recipe from the {q:7654::Imperial Plate Boots} quest, it needs 40 Thorium Bar."] = "Das Rezept bekommst du über die Quest {q:7654::Imperial Plate Boots}, sie erfordert 40 Thoriumbarren.",
  ["{b}Note:{/b} It wasn't possible to level this far on the beta, so this part only relies on the data I found in the game files. There might be more recipes we haven't discovered yet, but if there is nothing else, these are the only recipes you can use to level until 300."] = "{b}Hinweis:{/b} Auf der Beta war es nicht möglich, so weit zu leveln, daher stützt sich dieser Teil nur auf die Daten, die ich in den Spieldateien gefunden habe. Vielleicht gibt es noch Rezepte, die wir noch nicht entdeckt haben, aber falls nicht, sind das die einzigen Rezepte, mit denen du bis 300 leveln kannst.",
  ["10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Thorium Bar, 20 Star Ruby"] = "10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Thoriumbarren, 20 Sternrubin",
  ["You get the recipe from the {q:7658::Imperial Plate Leggings} quest, it needs 60 Thorium Bar."] = "Das Rezept bekommst du über die Quest {q:7658::Imperial Plate Leggings}, sie erfordert 60 Thoriumbarren.",
  ["This WoW Forever Enchanting leveling guide will show you the fastest and cheapest way to level your Enchanting skill from 1 to 300. You will also find every trainer location and where to train Enchanting past 75, 150 and 225."] = "Dieser WoW-Forever-Leitfaden für Verzauberkunst zeigt dir den schnellsten und günstigsten Weg, deine Verzauberkunst-Fertigkeit von 1 auf 300 zu steigern. Außerdem findest du alle Lehrer und erfährst, wo du Verzauberkunst über 75, 150 und 225 hinaus erlernen kannst.",
  ["Enchanting goes well with Tailoring because you don't need a gathering profession for either of them, and you can disenchant the items you made with Tailoring. Below you will find the shopping list, the Enchanting trainers by starting zone and capital city, and the cheapest enchants for every skill range. Forever added a few new low level recipes, so the first 70 points are cheaper than in Classic."] = "Verzauberkunst passt gut zu Schneiderei, weil du für keinen der beiden einen Sammelberuf brauchst und die mit Schneiderei hergestellten Gegenstände entzaubern kannst. Unten findest du die Einkaufsliste, die Verzauberkunstlehrer nach Startgebiet und Hauptstadt sowie die günstigsten Verzauberungen für jeden Fertigkeitsbereich. Forever hat ein paar neue niedrigstufige Rezepte hinzugefügt, daher sind die ersten 70 Punkte günstiger als in Classic.",
  ["An alternative replaces the whole row, so buy the one that is cheaper."] = "Eine Alternative ersetzt die ganze Zeile, kauf also die günstigere.",
  ["Enchanting Trainer Locations"] = "Standorte der Verzauberkunstlehrer",
  ["Apprentice Enchanting has no level requirement in Forever, so you can learn it on a fresh character."] = "Verzauberkunst (Lehrling) hat in Forever keine Stufenvoraussetzung, du kannst es also schon mit einem neuen Charakter erlernen.",
  ["Undercity: {n:0:horde:Malcomb Wynn}"] = "Unterstadt: {n:0:horde:Malcomb Wynn}",
  ["Thunder Bluff: {n:0:horde:Mot Dawnstrider}"] = "Donnerfels: {n:0:horde:Mot Dawnstrider}",
  ["{n:0:horde:Pa'zula} in Sen'jin Village"] = "{n:0:horde:Pa'zula} im Dorf Sen'jin",
  ["There is no Enchanting trainer in Mulgore, go to {n:0:horde:Mot Dawnstrider} on the middle rise in Thunder Bluff"] = "In Mulgore gibt es keinen Verzauberkunstlehrer, geh zu {n:0:horde:Mot Dawnstrider} auf der mittleren Anhöhe in Donnerfels",
  ["{n:0:horde:Vance Undergloom} upstairs in the inn in Brill"] = "{n:0:horde:Vance Undergloom} im Obergeschoss des Gasthauses in Brill",
  ["Stormwind City: {n:0:alliance:Betty Quin}"] = "Sturmwind: {n:0:alliance:Betty Quin}",
  ["Ironforge: {n:0:alliance:Thonys Pillarstone}"] = "Eisenschmiede: {n:0:alliance:Thonys Pillarstone}",
  ["There is no Enchanting trainer in Elwynn Forest, go to {n:0:alliance:Betty Quin} in the Mage Quarter in Stormwind City"] = "Im Wald von Elwynn gibt es keinen Verzauberkunstlehrer, geh zu {n:0:alliance:Betty Quin} im Magierviertel in Sturmwind",
  ["There is no Enchanting trainer in Dun Morogh, go to {n:0:alliance:Thonys Pillarstone} at the Great Forge in Ironforge"] = "In Dun Morogh gibt es keinen Verzauberkunstlehrer, geh zu {n:0:alliance:Thonys Pillarstone} an der Großen Schmiede in Eisenschmiede",
  ["{n:0:alliance:Alanna Raveneye} at the Oracle Glade, in the north-west of Teldrassil"] = "{n:0:alliance:Alanna Raveneye} an der Lichtung des Orakels im Nordwesten von Teldrassil",
  ["You can find every Enchanting trainer for Horde and Alliance on my WoW Forever Enchanting Trainers page."] = "Alle Verzauberkunstlehrer für Horde und Allianz findest du auf meiner Seite zu den WoW-Forever-Verzauberkunstlehrern.",
  ["Enchanting Macro for Faster Leveling"] = "Verzauberkunst-Makro für schnelleres Leveln",
  ["I highly recommend using this macro to speed up the leveling process."] = "Ich empfehle dir dringend, dieses Makro zu verwenden, um das Leveln zu beschleunigen.",
  ["This macro presses the Create button for you and confirms the prompt that asks if you want to replace the enchant already on the item, without any extra clicks."] = "Dieses Makro drückt für dich den Herstellen-Button und bestätigt die Abfrage, ob du die bereits vorhandene Verzauberung auf dem Gegenstand ersetzen willst, ganz ohne zusätzliche Klicks.",
  ["Macro"] = "Makro",
  ["If you have never made a macro, type /m in the chat and press Enter, click New, give it a name and paste these two lines into it."] = "Wenn du noch nie ein Makro erstellt hast, gib /m in den Chat ein und drück Enter, klick auf Neu, gib ihm einen Namen und füg diese zwei Zeilen ein.",
  ["How to Use"] = "So funktioniert es",
  ["Place the macro on your action bar"] = "Leg das Makro auf deine Aktionsleiste",
  ["Open your Enchanting profession window"] = "Öffne dein Verzauberkunst-Fenster",
  ["Select the enchant you want to craft (make sure it's the right one)"] = "Wähl die Verzauberung aus, die du herstellen willst (achte darauf, dass es die richtige ist)",
  ["Put the item you want to enchant into the optional target slot"] = "Leg den Gegenstand, den du verzaubern willst, in den optionalen Zielplatz",
  ["Press the macro repeatedly"] = "Drück das Makro immer wieder",
  ["Disenchanting"] = "Entzaubern",
  ["You get {s:13262:inv_enchant_disenchant:Disenchant} together with Apprentice Enchanting. In WoW Forever {b}Disenchant is not in your spellbook{/b}, it's in the Enchanting box of the Professions window."] = "Du bekommst {s:13262:inv_enchant_disenchant:Disenchant} zusammen mit Verzauberkunst (Lehrling). In WoW Forever {b}ist Entzaubern nicht in deinem Zauberbuch{/b}, sondern im Verzauberkunst-Bereich des Berufefensters.",
  ["If you are looking for the disenchanting table, it's in my disenchanting guide, and if you can't find the Disenchant button, the guide shows it with pictures:"] = "Wenn du die Entzauberungstabelle suchst, findest du sie in meinem Entzauberungsleitfaden, und wenn du den Entzaubern-Button nicht findest, zeigt ihn der Leitfaden mit Bildern:",
  ["Apprentice Enchanting (1-70)"] = "Verzauberkunst (Lehrling) (1-70)",
  ["1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Copper Rod, 1 Mote of Magic"] = "1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Kupferrute, 1 Mote of Magic",
  ["The {i:6217:inv_misc_flute_01:Copper Rod} and the {i:247786:inv_elemental_mote_mana:Mote of Magic} are sold by the Enchanting Supply vendor near your trainer, don't buy them from the Auction House."] = "Die {i:6217:inv_misc_flute_01:Copper Rod} und das {i:247786:inv_elemental_mote_mana:Mote of Magic} werden vom Händler für Verzauberkunstbedarf in der Nähe deines Lehrers verkauft, kauf sie nicht im Auktionshaus.",
  ["{b}If you are leveling in a starting zone with a low level character{/b}, you can buy the Copper Rod from a trade vendor there, but the Mote of Magic is only sold by Enchanting vendors. In the starting zones only the trainers on {b}Zephras Isle{/b} and in {b}Tirisfal Glades{/b} (Brill) sell it, everyone else has to visit the trainer in the capital city, the vendor stands right next to them."] = "{b}Wenn du in einem Startgebiet mit einem niedrigstufigen Charakter levelst{/b}, kannst du die Kupferrute dort bei einem Handwerkswarenhändler kaufen, aber das Mote of Magic wird nur von Verzauberkunsthändlern verkauft. In den Startgebieten verkaufen es nur die Lehrer auf {b}Zephras Isle{/b} und in {b}Tirisfal{/b} (Brill), alle anderen müssen den Lehrer in der Hauptstadt besuchen, der Händler steht direkt daneben.",
  ["Make one of these:"] = "Stell eines davon her:",
  ["50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Strange Dust"] = "50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Seltsamer Staub",
  ["50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Lesser Magic Essence"] = "50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Geringe Magieessenz",
  ["A {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} turns into 3 Lesser Magic Essence when you right-click it in your bags, so you can buy those too."] = "Eine {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} wird zu 3 geringen Magieessenzen, wenn du sie in deinen Taschen rechtsklickst, du kannst also auch diese kaufen.",
  ["Journeyman Enchanting (70-150)"] = "Verzauberkunst (Geselle) (70-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Enchanting. You need {b}Enchanting 50{/b} and {b}level 10{/b}:"] = "Um über 75 hinauszukommen, besuche einen dieser Lehrer und erlerne Verzauberkunst (Geselle). Du brauchst {b}Verzauberkunst 50{/b} und {b}Stufe 10{/b}:",
  ["Undercity: {n:0:horde:Lavinia Crowe}"] = "Unterstadt: {n:0:horde:Lavinia Crowe}",
  ["Thunder Bluff: {n:0:horde:Teg Dawnstrider}"] = "Donnerfels: {n:0:horde:Teg Dawnstrider}",
  ["Stormwind City: {n:0:alliance:Lucan Cordell}"] = "Sturmwind: {n:0:alliance:Lucan Cordell}",
  ["Ironforge: {n:0:alliance:Gimble Thistlefuzz}"] = "Eisenschmiede: {n:0:alliance:Gimble Thistlefuzz}",
  ["If you bought Strange Dust pick the {b}Strange Dust{/b} tab, if you bought Lesser Magic Essence pick the {b}Lesser Magic Essence{/b} tab."] = "Wenn du Seltsamen Staub gekauft hast, wähl den Reiter {b}Seltsamer Staub{/b}, wenn du Geringe Magieessenz gekauft hast, wähl den Reiter {b}Geringe Magieessenz{/b}.",
  ["Strange Dust"] = "Seltsamer Staub",
  ["Lesser Magic Essence"] = "Geringe Magieessenz",
  ["49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Lesser Magic Essence"] = "49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Geringe Magieessenz",
  ["1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Silver Rod, 3 Strange Dust, 4 Lesser Magic Essence, 1 Shadowgem"] = "1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Silberrute, 3 Seltsamer Staub, 4 Geringe Magieessenz, 1 Schattenedelstein",
  ["{i:6338:inv_staff_01:Silver Rod} and every other rod in this guide (Golden, Truesilver, Arcanite) is made by Blacksmiths, you can buy them from the Auction House."] = "Die {i:6338:inv_staff_01:Silver Rod} und jede andere Rute in diesem Leitfaden (Gold, Echtsilber, Arkanit) wird von Schmieden hergestellt, du kannst sie im Auktionshaus kaufen.",
  ["23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Simple Wood, 46 Lesser Magic Essence"] = "23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Einfaches Holz, 46 Geringe Magieessenz",
  ["37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Lesser Magic Essence"] = "37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Geringe Magieessenz",
  ["{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} is sold by these vendors:"] = "{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} wird von diesen Händlern verkauft:",
  ["{n:0:horde:Nata Dawnstrider} in Thunder Bluff"] = "{n:0:horde:Nata Dawnstrider} in Donnerfels",
  ["{n:0:horde:Leo Sarn} in Silverpine Forest"] = "{n:0:horde:Leo Sarn} im Silberwald",
  ["{n:0:alliance:Tilli Thistlefuzz} in Ironforge"] = "{n:0:alliance:Tilli Thistlefuzz} in Eisenschmiede",
  ["Buy {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} and {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need them at 150 and 200."] = "Kauf dort auch {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} und {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}, du brauchst sie bei 150 und 200.",
  ["If you don't want to get the formula, make this:"] = "Wenn du die Formel nicht holen willst, stell das hier her:",
  ["25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Strange Dust"] = "25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Seltsamer Staub",
  ["23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Strange Dust"] = "23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Seltsamer Staub",
  ["15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Strange Dust"] = "15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Seltsamer Staub",
  ["9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Strange Dust"] = "9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Seltsamer Staub",
  ["32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Strange Dust"] = "32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Seltsamer Staub",
  ["20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Strange Dust"] = "20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Seltsamer Staub",
  ["If 20 Soul Dust cost less than 80 Strange Dust, make this:"] = "Wenn 20 Seelenstaub weniger kosten als 80 Seltsamer Staub, stell das hier her:",
  ["20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Soul Dust."] = "20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Seelenstaub.",
  ["Expert Enchanting (150-225)"] = "Verzauberkunst (Experte) (150-225)",
  ["To train past 150, visit one of these trainers and learn Expert Enchanting. You need {b}Enchanting 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Um über 150 hinauszukommen, besuche einen dieser Lehrer und erlerne Verzauberkunst (Experte). Du brauchst {b}Verzauberkunst 125{/b} und {b}Stufe 20{/b}, und es kostet 50 Silber.",
  ["There is only one Expert Enchanting trainer for each faction. {n:0:horde:Hgarth} in Stonetalon Mountains at Sun Rock Retreat is the Horde trainer, he is up on the hill above the village. {n:0:alliance:Kitta Firewind} in Elwynn Forest is the Alliance trainer, she is at the top of the Tower of Azora."] = "Es gibt nur einen Experten-Verzauberkunstlehrer pro Fraktion. {n:0:horde:Hgarth} im Steinkrallengebirge am Sonnenfels ist der Lehrer der Horde, er steht oben auf dem Hügel über dem Dorf. {n:0:alliance:Kitta Firewind} im Wald von Elwynn ist die Lehrerin der Allianz, sie ist ganz oben im Turm von Azora.",
  ["1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Golden Rod, 1 Iridescent Pearl, 1 Greater Astral Essence, 1 Soul Dust"] = "1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Goldrute, 1 Schillernde Perle, 1 Große Astralessenz, 1 Seelenstaub",
  ["16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Soul Dust, 32 Maple Seed, 16 Leaded Vial"] = "16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Seelenstaub, 32 Ahornsamen, 16 Bleiphiole",
  ["{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} is sold by these vendors:"] = "{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} wird von diesen Händlern verkauft:",
  ["{n:0:horde:Thaddeus Webb} in Undercity"] = "{n:0:horde:Thaddeus Webb} in Unterstadt",
  ["{n:0:alliance:Jessara Cordell} in Stormwind City"] = "{n:0:alliance:Jessara Cordell} in Sturmwind",
  ["Buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need it at 200."] = "Kauf dort auch {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}, du brauchst sie bei 200.",
  ["{i:17034:inv_misc_food_02:Maple Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17034:inv_misc_food_02:Maple Seed} wird von Reagenzienhändlern verkauft und {i:3372:inv_potion_85:Leaded Vial} von Händlern für Alchimiebedarf.",
  ["47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Soul Dust"] = "47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Seelenstaub",
  ["If 2 Vision Dust cost less than 3 Soul Dust, stop the boots at 185 and make this until 200:"] = "Wenn 2 Visionenstaub weniger kosten als 3 Seelenstaub, hör bei 185 mit den Stiefeln auf und stell bis 200 das hier her:",
  ["15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Vision Dust."] = "15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Visionenstaub.",
  ["1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Truesilver Rod, 1 Black Pearl, 1 Greater Mystic Essence, 1 Vision Dust"] = "1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Echtsilberrute, 1 Schwarze Perle, 1 Große Mystikessenz, 1 Visionenstaub",
  ["25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Vision Dust, 50 Stranglethorn Seed, 25 Leaded Vial"] = "25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Visionenstaub, 50 Schlingendornsamen, 25 Bleiphiole",
  ["If you didn't buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} yet, the vendors are listed at the 151-165 step above."] = "Wenn du {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} noch nicht gekauft hast, stehen die Händler oben beim Schritt 151-165.",
  ["{i:17035:inv_misc_food_02:Stranglethorn Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17035:inv_misc_food_02:Stranglethorn Seed} wird von Reagenzienhändlern verkauft und {i:3372:inv_potion_85:Leaded Vial} von Händlern für Alchimiebedarf.",
  ["5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Vision Dust"] = "5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Visionenstaub",
  ["Artisan Enchanting (225-300)"] = "Verzauberkunst (Fachmann) (225-300)",
  ["The Expert Enchanting trainers only teach you up to 225. To train Enchanting past 225 you need {b}level 35{/b} and {b}Enchanting 200{/b}, then learn Artisan Enchanting from Annora in Uldaman (I explain below how to find her). {b}She is the only trainer who teaches Artisan Enchanting.{/b}"] = "Die Experten-Verzauberkunstlehrer bringen dir nur bis 225 etwas bei. Um Verzauberkunst über 225 hinaus zu erlernen, brauchst du {b}Stufe 35{/b} und {b}Verzauberkunst 200{/b}, dann erlernst du Verzauberkunst (Fachmann) bei Annora in Uldaman (unten erkläre ich, wie du sie findest). {b}Sie ist die einzige Lehrerin, die Verzauberkunst (Fachmann) lehrt.{/b}",
  ["There are a few recipes only Annora teaches, {b}so bring enough gold to learn every recipe and enough materials to reach Enchanting 250{/b}, otherwise you have to go back to Uldaman for the higher recipes. Around 50 {i:11137:inv_enchant_dustvision:Vision Dust} gets you to 250."] = "Es gibt ein paar Rezepte, die nur Annora lehrt, {b}bring also genug Gold mit, um jedes Rezept zu erlernen, und genug Materialien, um Verzauberkunst 250 zu erreichen{/b}, sonst musst du für die höheren Rezepte zurück nach Uldaman. Etwa 50 {i:11137:inv_enchant_dustvision:Vision Dust} bringen dich auf 250.",
  ["How to enter Uldaman"] = "So kommst du nach Uldaman",
  ["Uldaman is in the Badlands and it has two entrances, use the back entrance. You can't solo it at level 35, so go with a party or ask a level 60 to help."] = "Uldaman liegt im Ödland und hat zwei Eingänge, nimm den hinteren Eingang. Auf Stufe 35 schaffst du es nicht allein, geh also mit einer Gruppe oder bitte einen Stufe-60-Spieler um Hilfe.",
  ["How to find Annora"] = "So findest du Annora",
  ["Annora only spawns once you {b}kill every mob in the area she is in!{/b}"] = "Annora erscheint erst, wenn du {b}jeden Gegner in ihrem Bereich getötet hast!{/b}",
  ["{b}Don't forget to learn everything from Annora before you leave Uldaman!{/b} The recipes from 230 up are taught nowhere else."] = "{b}Vergiss nicht, alles bei Annora zu lernen, bevor du Uldaman verlässt!{/b} Die Rezepte ab 230 werden nirgendwo sonst gelehrt.",
  ["Recipe"] = "Rezept",
  ["Skill"] = "Fertigkeit",
  ["Cost"] = "Kosten",
  ["{b}Artisan Enchanting{/b}"] = "{b}Verzauberkunst (Fachmann){/b}",
  ["37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Vision Dust"] = "37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Visionenstaub",
  ["20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Dream Dust, 20 Purple Lotus, 20 Crystal Vial"] = "20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Traumstaub, 20 Lila Lotus, 20 Kristallphiole",
  ["{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} is sold by {n:0::Kania} in Silithus, she is upstairs in the inn. {i:8925:inv_potion_86:Crystal Vial} is sold by {n:0::Mishta} in Silithus or any Alchemy Supply vendor."] = "{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} wird von {n:0::Kania} in Silithus verkauft, sie ist im Obergeschoss des Gasthauses. {i:8925:inv_potion_86:Crystal Vial} wird von {n:0::Mishta} in Silithus oder jedem Händler für Alchimiebedarf verkauft.",
  ["If you don't have Purple Lotus, make {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} instead (1 Dream Dust, 2 Lesser Nether Essence each), Annora teaches it."] = "Wenn du keinen Lila Lotus hast, stell stattdessen {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} her (je 1 Traumstaub, 2 Geringe Netheressenz), Annora lehrt es.",
  ["40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Dream Dust"] = "40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Traumstaub",
  ["{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} is sold by {n:0:horde:Daniel Bartlett} in Undercity and {n:0:alliance:Mythrin'dir} in Darnassus. It's bind on pickup, so don't buy it on an alt."] = "{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} wird von {n:0:horde:Daniel Bartlett} in Unterstadt und {n:0:alliance:Mythrin'dir} in Darnassus verkauft. Sie wird beim Aufheben gebunden, kauf sie also nicht mit einem Twink.",
  ["From 290 you can make the Runed Arcanite Rod, see the next step."] = "Ab 290 kannst du die runenverzierte Arkanitrute herstellen, siehe nächster Schritt.",
  ["1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Arcanite Rod, 1 Golden Pearl, 10 Illusion Dust, 4 Greater Eternal Essence, 4 Small Brilliant Shard, 2 Large Brilliant Shard"] = "1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Arkanitrute, 1 Goldene Perle, 10 Illusionsstaub, 4 Große ewige Essenz, 4 Kleiner glänzender Splitter, 2 Großer glänzender Splitter",
  ["{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} is sold by {n:0::Lorelae Wintersong} in Moonglade at Nighthaven."] = "{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} wird von {n:0::Lorelae Wintersong} in der Mondlichtung in Nachthafen verkauft.",
  ["{b}You need this rod for some recipes from 290 and for most recipes at 300{/b}, Crusader for example. You can make it from 290, but if you don't need it yet, you can make it later and make one more Shield for the last point instead."] = "{b}Du brauchst diese Rute für einige Rezepte ab 290 und für die meisten Rezepte bei 300{/b}, zum Beispiel Kreuzfahrer. Du kannst sie ab 290 herstellen, aber wenn du sie noch nicht brauchst, kannst du sie später machen und stattdessen für den letzten Punkt noch einen Schild verzaubern.",
  ["This WoW Forever Engineering leveling guide will show you the fastest and cheapest way to level your Engineering skill from 1 to 300. You will also find every trainer location and where to train Engineering past 75, 150 and 225."] = "Dieser WoW-Forever-Leitfaden für Ingenieurskunst zeigt dir den schnellsten und günstigsten Weg, deine Ingenieurskunst-Fertigkeit von 1 auf 300 zu steigern. Außerdem findest du alle Lehrer und erfährst, wo du Ingenieurskunst über 75, 150 und 225 hinaus erlernen kannst.",
  ["Engineering is best combined with Mining, because almost everything you make needs stone and bars, and you can mine both. If you don't have Mining, you have to buy everything from the Auction House. Below you will find the shopping list, the Engineering trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "Ingenieurskunst lässt sich am besten mit Bergbau kombinieren, weil fast alles, was du herstellst, Steine und Barren braucht, und du beides selbst abbauen kannst. Ohne Bergbau musst du alles im Auktionshaus kaufen. Unten findest du die Einkaufsliste, die Ingenieurskunstlehrer nach Startgebiet und Hauptstadt sowie die günstigsten Rezepte für jeden Fertigkeitsbereich.",
  ["Engineering Trainer Locations"] = "Standorte der Ingenieurskunstlehrer",
  ["Apprentice Engineering has no level requirement in Forever, so you can learn it on a fresh character."] = "Ingenieurskunst (Lehrling) hat in Forever keine Stufenvoraussetzung, du kannst es also schon mit einem neuen Charakter erlernen.",
  ["There is no Engineering trainer in Thunder Bluff and Darnassus, the other four capitals have one. You can also ask a guard, then it will be marked with a red flag on your map."] = "In Donnerfels und Darnassus gibt es keinen Ingenieurskunstlehrer, die anderen vier Hauptstädte haben einen. Du kannst auch eine Wache fragen, dann wird er mit einer roten Fahne auf deiner Karte markiert.",
  ["Undercity: {n:0:horde:Graham Van Talen}"] = "Unterstadt: {n:0:horde:Graham Van Talen}",
  ["{n:0:horde:Mukdrak} in Razor Hill, near the forge next to the road to Orgrimmar"] = "{n:0:horde:Mukdrak} in Klingenhügel, bei der Schmiede neben der Straße nach Orgrimmar",
  ["{n:0::Twizwick Sprocketgrind} on the plateau above the Venture Co. Mine, hard to reach at low level. There is no anvil near him and nobody there sells the Blacksmith Hammer, so it's probably best to go to {n:0:horde:Thund} in Orgrimmar instead."] = "{n:0::Twizwick Sprocketgrind} auf dem Plateau über der Mine der Venture Co., auf niedriger Stufe schwer zu erreichen. In seiner Nähe gibt es keinen Amboss und niemand dort verkauft den Schmiedehammer, also gehst du wahrscheinlich besser zu {n:0:horde:Thund} in Orgrimmar.",
  ["There is no Engineering trainer in Tirisfal Glades, go to {n:0:horde:Graham Van Talen} in the Rogues' Quarter in Undercity"] = "In Tirisfal gibt es keinen Ingenieurskunstlehrer, geh zu {n:0:horde:Graham Van Talen} im Schurkenviertel in Unterstadt",
  ["{n:0::Strange Hermit} in Shadowgale Forest"] = "{n:0::Strange Hermit} im Shadowgale Forest",
  ["Stormwind City: {n:0:alliance:Sprite Jumpsprocket}"] = "Sturmwind: {n:0:alliance:Sprite Jumpsprocket}",
  ["Ironforge: {n:0:alliance:Jemma Quikswitch}"] = "Eisenschmiede: {n:0:alliance:Jemma Quikswitch}",
  ["There is no Engineering trainer in Elwynn Forest, go to {n:0:alliance:Sprite Jumpsprocket} in the Dwarven District in Stormwind City"] = "Im Wald von Elwynn gibt es keinen Ingenieurskunstlehrer, geh zu {n:0:alliance:Sprite Jumpsprocket} im Zwergendistrikt in Sturmwind",
  ["{n:0:alliance:Bronk Guzzlegear} at Steelgrill's Depot"] = "{n:0:alliance:Bronk Guzzlegear} in Stahlrosts Depot",
  ["There is no Engineering trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Jenna Lemkenilli} in Auberdine in Darkshore"] = "In Teldrassil und Darnassus gibt es keinen Ingenieurskunstlehrer, der nächste ist {n:0:alliance:Jenna Lemkenilli} in Auberdine an der Dunkelküste",
  ["You can find every Engineering trainer for Horde and Alliance on my WoW Forever Engineering Trainers page."] = "Alle Ingenieurskunstlehrer für Horde und Allianz findest du auf meiner Seite zu den WoW-Forever-Ingenieurskunstlehrern.",
  ["Apprentice Engineering (1-50)"] = "Ingenieurskunst (Lehrling) (1-50)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer}, most recipes need it. {b}Most trainers{/b} have a Blacksmithing or Engineering Supply vendor nearby that sells it, {b}except{/b} the trainers in Dun Morogh and on Zephras Isle. In Dun Morogh buy it in Kharanos from {n:0:alliance:Thrawn Boltar}, on Zephras Isle in Shen'dar Village from {n:0::Aedi Thriceforged}."] = "Kauf einen {i:5956:inv_hammer_20:Blacksmith Hammer}, die meisten Rezepte brauchen ihn. {b}Die meisten Lehrer{/b} haben einen Händler für Schmiede- oder Ingenieursbedarf in der Nähe, der ihn verkauft, {b}außer{/b} den Lehrern in Dun Morogh und auf Zephras Isle. In Dun Morogh kaufst du ihn in Kharanos bei {n:0:alliance:Thrawn Boltar}, auf Zephras Isle in Shen'dar Village bei {n:0::Aedi Thriceforged}.",
  ["The {b}Gnome{/b} racial changed in Forever. Instead of +15 Engineering skill, Engineering Specialization now makes your devices fail or backfire 20% less often, so Gnomes level Engineering exactly like everyone else."] = "Das Volksmerkmal der {b}Gnome{/b} wurde in Forever geändert. Statt +15 auf Ingenieurskunst sorgt Ingenieursspezialisierung jetzt dafür, dass deine Geräte 20 % seltener versagen oder nach hinten losgehen. Gnome leveln Ingenieurskunst also genauso wie alle anderen.",
  ["66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Rough Stone"] = "66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Rauer Stein",
  ["Keep all of them, you need 66 for the bombs at 51."] = "Behalte alle, du brauchst 66 für die Bomben bei 51.",
  ["33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Copper Bar"] = "33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Kupferbarren",
  ["Keep these too, you will need all 33 for the bombs."] = "Behalte auch diese, du brauchst alle 33 für die Bomben.",
  ["1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Copper Bar"] = "1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Kupferbarren",
  ["You will use this to craft Engineering recipes, so keep it."] = "Damit stellst du Ingenieursrezepte her, also behalte ihn.",
  ["Journeyman Engineering (50-150)"] = "Ingenieurskunst (Geselle) (50-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Engineering. You need {b}Engineering 50{/b} and {b}level 10{/b}:"] = "Um über 75 hinauszukommen, besuche einen dieser Lehrer und erlerne Ingenieurskunst (Geselle). Du brauchst {b}Ingenieurskunst 50{/b} und {b}Stufe 10{/b}:",
  ["Undercity: {n:0:horde:Franklin Lloyd}"] = "Unterstadt: {n:0:horde:Franklin Lloyd}",
  ["Stormwind City: {n:0:alliance:Lilliam Sparkspindle}"] = "Sturmwind: {n:0:alliance:Lilliam Sparkspindle}",
  ["Ironforge: {n:0:alliance:Trixie Quikswitch}"] = "Eisenschmiede: {n:0:alliance:Trixie Quikswitch}",
  ["Duskwood: {n:0:alliance:Finbus Geargrind}"] = "Dämmerwald: {n:0:alliance:Finbus Geargrind}",
  ["33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Copper Bar, 33 Handful of Copper Bolts, 66 Rough Blasting Powder, 33 Linen Cloth"] = "33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Kupferbarren, 33 Handvoll Kupferbolzen, 66 Raues Sprengpulver, 33 Leinenstoff",
  ["{b}It's possible that you reach further than 75 with these{/b}, so it's best not to afk craft them unless you already learned Journeyman Engineering. Either make sure you learn it first, or just don't afk craft them. (Depends on luck, sometimes you don't even reach 75.)"] = "{b}Es ist möglich, dass du damit über 75 hinauskommst{/b}, also stell sie besser nicht afk her, solange du Ingenieurskunst (Geselle) noch nicht erlernt hast. Lern es entweder vorher oder stell sie einfach nicht afk her. (Hängt vom Glück ab, manchmal erreichst du nicht einmal 75.)",
  ["60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Coarse Stone"] = "60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Grober Stein",
  ["Keep them, you will need all 60 for the dynamite at 90."] = "Behalte sie, du brauchst alle 60 für das Dynamit bei 90.",
  ["20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Coarse Blasting Powder, 20 Linen Cloth"] = "20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Grobes Sprengpulver, 20 Leinenstoff",
  ["5x {s:3973:inv_ingot_04:Silver Contact} - 5 Silver Bar"] = "5x {s:3973:inv_ingot_04:Silver Contact} - 5 Silberbarren",
  ["If Silver Bar is expensive, make this instead:"] = "Wenn Silberbarren teuer sind, stell stattdessen das hier her:",
  ["5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Light Leather, 10 Tigerseye."] = "5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Leichtes Leder, 10 Tigerauge.",
  ["25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Bronze Bar, 25 Weak Flux"] = "25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Bronzebarren, 25 Schwaches Flussmittel",
  ["Keep 10 of them, you will need them at 125."] = "Behalte 10 davon, du brauchst sie bei 125.",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} is sold by Engineering Supply vendors near your trainer."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} wird von Händlern für Ingenieursbedarf in der Nähe deines Lehrers verkauft.",
  ["If you end up a few points short of 125, don't make more tubes, just start the scopes."] = "Wenn dir am Ende ein paar Punkte bis 125 fehlen, stell keine weiteren Röhren her, sondern fang einfach mit den Zielfernrohren an.",
  ["10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Bronze Tube, 10 Moss Agate"] = "10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Bronzeröhre, 10 Moosachat",
  ["Start making {s:3945:inv_misc_dust_06:Heavy Blasting Powder} instead if you don't have any Moss Agate, or it's really expensive."] = "Fang stattdessen mit {s:3945:inv_misc_dust_06:Heavy Blasting Powder} an, wenn du keinen Moosachat hast oder er sehr teuer ist.",
  ["Make both of these:"] = "Stell beides her:",
  ["30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Heavy Stone"] = "30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Schwerer Stein",
  ["15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Bronze Bar, 15 Wool Cloth"] = "15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Bronzebarren, 15 Wollstoff",
  ["{b}Make sure to make them in the same order.{/b} You need both for the sheep at 160, so make them now and you should reach 150 with them."] = "{b}Stell sie unbedingt in dieser Reihenfolge her.{/b} Du brauchst beides für die Schafe bei 160, also stell sie jetzt her, damit solltest du 150 erreichen.",
  ["Expert Engineering (150-200)"] = "Ingenieurskunst (Experte) (150-200)",
  ["To train past 150, visit {n:0:horde:Roxxik} in Orgrimmar (Horde) or {n:0:alliance:Springspindle Fizzlegear} in Ironforge (Alliance) and learn Expert Engineering. You need {b}Engineering 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Um über 150 hinauszukommen, besuche {n:0:horde:Roxxik} in Orgrimmar (Horde) oder {n:0:alliance:Springspindle Fizzlegear} in Eisenschmiede (Allianz) und erlerne Ingenieurskunst (Experte). Du brauchst {b}Ingenieurskunst 125{/b} und {b}Stufe 20{/b}, und es kostet 50 Silber.",
  ["15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Bronze Bar, 15 Medium Leather, 15 Wool Cloth"] = "15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Bronzebarren, 15 Mittleres Leder, 15 Wollstoff",
  ["Keep these too, you will need all 15 for the sheep."] = "Behalte auch diese, du brauchst alle 15 für die Schafe.",
  ["The 15 will probably take you past 160, that's fine."] = "Mit den 15 kommst du wahrscheinlich über 160, das ist in Ordnung.",
  ["15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Heavy Blasting Powder, 15 Whirring Bronze Gizmo, 15 Bronze Framework, 30 Wool Cloth"] = "15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Schweres Sprengpulver, 15 Surrendes Bronzedings, 15 Bronzegerüst, 30 Wollstoff",
  ["Keep 5 of them, you might need them if you choose Goblin Engineering at 200."] = "Behalte 5 davon, du könntest sie brauchen, wenn du bei 200 Gobliningenieurskunst wählst.",
  ["60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Solid Stone"] = "60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Robuster Stein",
  ["Save these, you will need them later."] = "Heb sie auf, du brauchst sie später.",
  ["1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Steel Bar"] = "1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Stahlbarren",
  ["Keep this, you will need it to craft some of the Engineering recipes."] = "Behalte ihn, du brauchst ihn für einige Ingenieursrezepte.",
  ["If you were unlucky with the skill points and didn't reach 195, craft a few {s:3962:inv_misc_bomb_08:Iron Grenade} or any other recipe that gives skill points."] = "Wenn du mit den Fertigkeitspunkten Pech hattest und 195 nicht erreicht hast, stell ein paar {s:3962:inv_misc_bomb_08:Iron Grenade} oder ein anderes Rezept her, das Fertigkeitspunkte gibt.",
  ["6x {s:12589:inv_musket_01:Mithril Tube} - 18 Mithril Bar"] = "6x {s:12589:inv_musket_01:Mithril Tube} - 18 Mithrilbarren",
  ["Keep all 6, you might need them if you choose Gnomish Engineering at 200."] = "Behalte alle 6, du könntest sie brauchen, wenn du bei 200 Gnomeningenieurskunst wählst.",
  ["Engineering Specializations"] = "Spezialisierungen der Ingenieurskunst",
  ["At {b}Engineering 200{/b} and {b}level 30{/b}, you can specialize in Gnomish or Goblin Engineering. Some items require a specific specialization to use, while other items are crafted by one specialization but are usable by any engineer. Fortunately, most recipes that are crafted by one specialization can be used by both."] = "Mit {b}Ingenieurskunst 200{/b} und {b}Stufe 30{/b} kannst du dich auf Gnomen- oder Gobliningenieurskunst spezialisieren. Manche Gegenstände erfordern zum Benutzen eine bestimmte Spezialisierung, andere werden von einer Spezialisierung hergestellt, sind aber für jeden Ingenieur benutzbar. Zum Glück können die meisten Rezepte, die von einer Spezialisierung hergestellt werden, von beiden benutzt werden.",
  ["For information on how to choose a specialization, please see my separate guide:"] = "Informationen zur Wahl einer Spezialisierung findest du in meinem separaten Leitfaden:",
  ["Artisan Engineering (200-300)"] = "Ingenieurskunst (Fachmann) (200-300)",
  ["To train Engineering past 225 you need {b}Engineering 200{/b} and {b}level 35{/b}, then learn Artisan Engineering from {n:0::Buzzek Bracketswing} in Tanaris at Gadgetzan, he is right outside the inn near the mailbox. He also teaches the recipes above 200, so go there as soon as you reach 200."] = "Um Ingenieurskunst über 225 hinaus zu erlernen, brauchst du {b}Ingenieurskunst 200{/b} und {b}Stufe 35{/b}, dann erlernst du Ingenieurskunst (Fachmann) bei {n:0::Buzzek Bracketswing} in Gadgetzan, Tanaris. Er steht direkt vor dem Gasthaus beim Briefkasten. Er lehrt auch die Rezepte über 200, geh also hin, sobald du 200 erreichst.",
  ["20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Mithril Bar, 20 Mageweave Cloth, 20 Solid Blasting Powder"] = "20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Mithrilbarren, 20 Magiestoff, 20 Robustes Sprengpulver",
  ["Keep them, you will need all 20 for the bombs at 238."] = "Behalte sie, du brauchst alle 20 für die Bomben bei 238.",
  ["40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Mithril Bar"] = "40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Mithrilbarren",
  ["Keep these too, you will need 40 for the bombs."] = "Behalte auch diese, du brauchst 40 für die Bomben.",
  ["20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 Mithril Casing, 20 Unstable Trigger, 40 Solid Blasting Powder"] = "20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 Mithrilgehäuse, 20 Instabiler Auslöser, 40 Robustes Sprengpulver",
  ["44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Dense Stone"] = "44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Verdichteter Stein",
  ["35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Thorium Bar, 35 Runecloth"] = "35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Thoriumbarren, 35 Runenstoff",
  ["{i:16042:inv_scroll_03:Schematic: Thorium Widget} is sold by {n:0:horde:Sovik} in Orgrimmar and {n:0:alliance:Gearcutter Cogspinner} in Ironforge."] = "{i:16042:inv_scroll_03:Schematic: Thorium Widget} wird von {n:0:horde:Sovik} in Orgrimmar und {n:0:alliance:Gearcutter Cogspinner} in Eisenschmiede verkauft.",
  ["20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Thorium Bar"] = "20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Thoriumbarren",
  ["{i:16047:inv_scroll_03:Schematic: Thorium Tube} is sold by {n:0::Xizzer Fizzbolt} in Winterspring at Everlook, in the first building on the right after the gate. It's bind on pickup in Forever, so buy it with the character that levels Engineering."] = "{i:16047:inv_scroll_03:Schematic: Thorium Tube} wird von {n:0::Xizzer Fizzbolt} in der Ewigen Warte in Winterquell verkauft, im ersten Gebäude rechts nach dem Tor. In Forever wird er beim Aufheben gebunden, kauf ihn also mit dem Charakter, der Ingenieurskunst levelt.",
  ["This WoW Forever Leatherworking leveling guide will show you the fastest and cheapest way to level your Leatherworking skill from 1 to 300. You will also find every trainer location and where to train Leatherworking past 75, 150 and 225."] = "Dieser WoW-Forever-Leitfaden für Lederverarbeitung zeigt dir den schnellsten und günstigsten Weg, deine Lederverarbeitungs-Fertigkeit von 1 auf 300 zu steigern. Außerdem findest du alle Lehrer und erfährst, wo du Lederverarbeitung über 75, 150 und 225 hinaus erlernen kannst.",
  ["Below you will find the full shopping list, the Leatherworking trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Leatherworking is best combined with Skinning because leather is most of the cost, but you can also buy everything in the guide from the Auction House."] = "Unten findest du die vollständige Einkaufsliste, die Lederverarbeitungslehrer nach Startgebiet und Hauptstadt sowie die günstigsten Rezepte für jeden Fertigkeitsbereich vom Lehrling bis zum Fachmann. Lederverarbeitung lässt sich am besten mit Kürschnerei kombinieren, weil Leder den Großteil der Kosten ausmacht, aber du kannst auch alles im Leitfaden im Auktionshaus kaufen.",
  ["When a recipe is yellow or green, a craft doesn't always give you a skill point, so nobody can tell exactly how many materials you will need. That's why the counts that depend a lot on luck are a range. {b}With the bigger number 9 out of 10 players have enough, with the smaller one it's 50/50.{/b} If you buy the smaller number, be ready to buy more later."] = "Wenn ein Rezept gelb oder grün ist, gibt dir nicht jede Herstellung einen Fertigkeitspunkt, daher kann niemand genau sagen, wie viele Materialien du brauchst. Deshalb sind die Mengen, die stark vom Glück abhängen, als Bereich angegeben. {b}Mit der größeren Zahl haben 9 von 10 Spielern genug, mit der kleineren ist es 50/50.{/b} Wenn du die kleinere Menge kaufst, sei bereit, später nachzukaufen.",
  ["Leatherworking Trainer Locations"] = "Standorte der Lederverarbeitungslehrer",
  ["Apprentice Leatherworking has no level requirement in Forever, so you can learn it on a fresh character."] = "Lederverarbeitung (Lehrling) hat in Forever keine Stufenvoraussetzung, du kannst es also schon mit einem neuen Charakter erlernen.",
  ["Undercity: {n:0:horde:Dan Golthas}"] = "Unterstadt: {n:0:horde:Dan Golthas}",
  ["Thunder Bluff: {n:0:horde:Mak}"] = "Donnerfels: {n:0:horde:Mak}",
  ["There is no Leatherworking trainer in Durotar, go to {n:0:horde:Kamari} in the Drag in Orgrimmar"] = "In Durotar gibt es keinen Lederverarbeitungslehrer, geh zu {n:0:horde:Kamari} in der Gasse in Orgrimmar",
  ["{n:0:horde:Chaw Stronghide} in Bloodhoof Village"] = "{n:0:horde:Chaw Stronghide} im Dorf der Bluthufe",
  ["{n:0:horde:Shelene Rhobart} at the road junction southeast of Brill"] = "{n:0:horde:Shelene Rhobart} an der Straßenkreuzung südöstlich von Brill",
  ["Stormwind City: {n:0:alliance:Randal Worth}"] = "Sturmwind: {n:0:alliance:Randal Worth}",
  ["Ironforge: {n:0:alliance:Gretta Finespindle}"] = "Eisenschmiede: {n:0:alliance:Gretta Finespindle}",
  ["{n:0:alliance:Adele Fielder} in the small house by Crystal Lake, northeast of Goldshire"] = "{n:0:alliance:Adele Fielder} im kleinen Haus am Kristallsee, nordöstlich von Goldhain",
  ["There is no Leatherworking trainer in Dun Morogh, go to {n:0:alliance:Gretta Finespindle} at the Great Forge in Ironforge"] = "In Dun Morogh gibt es keinen Lederverarbeitungslehrer, geh zu {n:0:alliance:Gretta Finespindle} an der Großen Schmiede in Eisenschmiede",
  ["{n:0:alliance:Nadyia Maneweaver} in the small house near the road to Darnassus"] = "{n:0:alliance:Nadyia Maneweaver} im kleinen Haus an der Straße nach Darnassus",
  ["You can find every Leatherworking trainer for Horde and Alliance on my WoW Forever Leatherworking Trainers page."] = "Alle Lederverarbeitungslehrer für Horde und Allianz findest du auf meiner Seite zu den WoW-Forever-Lederverarbeitungslehrern.",
  ["Apprentice Leatherworking (1-55)"] = "Lederverarbeitung (Lehrling) (1-55)",
  ["35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Ruined Leather Scraps"] = "35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Ruinierte Lederfetzen",
  ["27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Light Hide, 27 Salt"] = "27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Leichter Balg, 27 Salz",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Leatherworking Supply vendor nearby that sells the threads, dyes, and salt, {b}except{/b} the trainers in Elwynn Forest and Tirisfal Glades. For those, buy the Salt and Coarse Thread in Goldshire from {n:0:alliance:Tharynn Bouden} or in Brill from {n:0:horde:Abigail Shiel}."] = "{b}HINWEIS:{/b} {b}Die meisten Lehrer{/b} haben einen Händler für Lederverarbeitungsbedarf in der Nähe, der Garn, Farbstoffe und Salz verkauft, {b}außer{/b} den Lehrern im Wald von Elwynn und in Tirisfal. Kauf das Salz und das grobe Garn dort in Goldhain bei {n:0:alliance:Tharynn Bouden} oder in Brill bei {n:0:horde:Abigail Shiel}.",
  ["Keep 24 of the hides, you will need them for the Light Leather Pants at 100."] = "Behalte 24 der Bälge, du brauchst sie für die leichten Lederhosen bei 100.",
  ["Alternative recipes"] = "Alternative Rezepte",
  ["If you farm your own leather and don't have 27 Light Hides, make Light Armor Kits until 45, then Embossed Leather Gloves until 55:"] = "Wenn du dein Leder selbst farmst und keine 27 leichten Bälge hast, stell bis 45 leichte Rüstungssets her, dann bis 55 geprägte Lederhandschuhe:",
  ["24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Light Leather"] = "24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Leichtes Leder",
  ["10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Light Leather, 20 Coarse Thread"] = "10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Leichtes Leder, 20 Grobes Garn",
  ["You still need 24 Cured Light Hide for the Light Leather Pants at 100, so keep the Light Hides you skin until then."] = "Du brauchst trotzdem 24 behandelte leichte Bälge für die leichten Lederhosen bei 100, behalte also die leichten Bälge, die du bis dahin kürschnerst.",
  ["Journeyman Leatherworking (55-130)"] = "Lederverarbeitung (Geselle) (55-130)",
  ["To train past 75, visit one of these trainers and learn Journeyman Leatherworking. You need {b}Leatherworking 50{/b} and {b}level 10{/b}:"] = "Um über 75 hinauszukommen, besuche einen dieser Lehrer und erlerne Lederverarbeitung (Geselle). Du brauchst {b}Lederverarbeitung 50{/b} und {b}Stufe 10{/b}:",
  ["Undercity: {n:0:horde:Arthur Moore}"] = "Unterstadt: {n:0:horde:Arthur Moore}",
  ["Thunder Bluff: {n:0:horde:Tarn}"] = "Donnerfels: {n:0:horde:Tarn}",
  ["Stormwind City: {n:0:alliance:Simon Tanner}"] = "Sturmwind: {n:0:alliance:Simon Tanner}",
  ["Ironforge: {n:0:alliance:Fimble Finespindle}"] = "Eisenschmiede: {n:0:alliance:Fimble Finespindle}",
  ["21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Light Leather, 42 Coarse Thread"] = "21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Leichtes Leder, 42 Grobes Garn",
  ["8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Light Leather"] = "8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Leichtes Leder",
  ["10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Medium Hide, 10 Salt"] = "10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Mittlerer Balg, 10 Salz",
  ["Keep the Cured Medium Hides, you will need them for the Dark Leather Belts at 115."] = "Behalte die behandelten mittleren Bälge, du brauchst sie für die dunklen Ledergürtel bei 115.",
  ["19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Light Leather, 38 Coarse Thread"] = "19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Leichtes Leder, 38 Grobes Garn",
  ["Keep 10 of the belts for the Dark Leather Belts at 115."] = "Behalte 10 der Gürtel für die dunklen Ledergürtel bei 115.",
  ["24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Light Leather, 24 Cured Light Hide, 24 Fine Thread"] = "24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Leichtes Leder, 24 Behandelter leichter Balg, 24 Feines Garn",
  ["10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Fine Leather Belt, 10 Cured Medium Hide, 20 Fine Thread, 10 Gray Dye"] = "10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Feiner Ledergürtel, 10 Behandelter mittlerer Balg, 20 Feines Garn, 10 Grauer Farbstoff",
  ["7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Medium Leather"] = "7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Mittleres Leder",
  ["Expert Leatherworking (130-205)"] = "Lederverarbeitung (Experte) (130-205)",
  ["To train past 150, visit {n:0:horde:Una} in Thunder Bluff (Horde) or {n:0:alliance:Telonis} in Darnassus (Alliance) and learn Expert Leatherworking. You need {b}Leatherworking 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Um über 150 hinauszukommen, besuche {n:0:horde:Una} in Donnerfels (Horde) oder {n:0:alliance:Telonis} in Darnassus (Allianz) und erlerne Lederverarbeitung (Experte). Du brauchst {b}Lederverarbeitung 125{/b} und {b}Stufe 20{/b}, und es kostet 50 Silber.",
  ["30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Heavy Hide, 90 Salt"] = "30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Schwerer Balg, 90 Salz",
  ["Keep the Cured Heavy Hides, you will need 10 for the Barbaric Shoulders at 155 and 20 for the Guardian Gloves at 165."] = "Behalte die behandelten schweren Bälge, du brauchst 10 für die barbarischen Schultern bei 155 und 20 für die Wächterhandschuhe bei 165.",
  ["17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Medium Leather, 68 Fine Thread"] = "17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Mittleres Leder, 68 Feines Garn",
  ["10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Heavy Leather, 10 Cured Heavy Hide, 20 Fine Thread"] = "10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Schweres Leder, 10 Behandelter schwerer Balg, 20 Feines Garn",
  ["20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Heavy Leather, 20 Cured Heavy Hide, 20 Silken Thread"] = "20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Schweres Leder, 20 Behandelter schwerer Balg, 20 Seidengarn",
  ["22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Thick Leather, 44 Silken Thread"] = "22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Dickes Leder, 44 Seidengarn",
  ["Leatherworking Specializations"] = "Spezialisierungen der Lederverarbeitung",
  ["Once you reach {b}Leatherworking 225{/b} and {b}level 40{/b}, you can choose one of the three Leatherworking specializations: Dragonscale, Elemental, or Tribal. Each specialization gives access to a specific set of patterns."] = "Sobald du {b}Lederverarbeitung 225{/b} und {b}Stufe 40{/b} erreichst, kannst du eine der drei Spezialisierungen der Lederverarbeitung wählen: Drachenschuppen, Elementar oder Stammes. Jede Spezialisierung gibt dir Zugang zu bestimmten Mustern.",
  ["Dragonscale - Mail-type gear"] = "Drachenschuppen - Ausrüstung aus Schwere Rüstung",
  ["Elemental - elemental resistance and Leather-type agility gear"] = "Elementar - Ausrüstung mit Elementarwiderstand und Leder-Ausrüstung mit Beweglichkeit",
  ["Tribal - Leather-type intellect & agility gear and the Devilsaur Armor set"] = "Stammes - Leder-Ausrüstung mit Intelligenz und Beweglichkeit sowie das Teufelssaurier-Set",
  ["For information on how to become a Dragonscale, Elemental, or Tribal Leatherworker, please see my separate guides:"] = "Informationen dazu, wie du Drachenschuppen-, Elementar- oder Stammeslederer wirst, findest du in meinen separaten Leitfäden:",
  ["Artisan Leatherworking (205-300)"] = "Lederverarbeitung (Fachmann) (205-300)",
  ["To train past 225, visit {n:0:horde:Hahrana Ironhide} in Camp Mojache, Feralas (Horde) or {n:0:alliance:Drakk Stonehand} in Aerie Peak, The Hinterlands (Alliance) and learn Artisan Leatherworking. You need {b}Leatherworking 200{/b} and {b}level 35{/b}."] = "Um über 225 hinauszukommen, besuche {n:0:horde:Hahrana Ironhide} im Camp Mojache, Feralas (Horde) oder {n:0:alliance:Drakk Stonehand} im Nistgipfel, Hinterland (Allianz) und erlerne Lederverarbeitung (Fachmann). Du brauchst {b}Lederverarbeitung 200{/b} und {b}Stufe 35{/b}.",
  ["36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Thick Leather, 144 Silken Thread"] = "36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Dickes Leder, 144 Seidengarn",
  ["{b}The Expert trainers in Thunder Bluff and Darnassus don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}Die Expertenlehrer in Donnerfels und Darnassus lehren dieses Rezept nicht{/b}, du kannst es nur bei den beiden Lehrern oben lernen.",
  ["I recommend these over the Nightscape Boots because they sell for more to a vendor, so they end up cheaper."] = "Ich empfehle diese statt der Nachtschattenstiefel, weil sie beim Händler mehr einbringen und am Ende günstiger sind.",
  ["36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Rugged Leather, 36 Black Dye, 36 Rune Thread"] = "36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Unverwüstliches Leder, 36 Schwarzer Farbstoff, 36 Runenfaden",
  ["The pattern is sold by {n:0:horde:Werg Thickblade} in Tirisfal Glades (Horde) and {n:0:alliance:Leonard Porter} in Western Plaguelands (Alliance)."] = "Das Muster wird von {n:0:horde:Werg Thickblade} in Tirisfal (Horde) und {n:0:alliance:Leonard Porter} in den Westlichen Pestländern (Allianz) verkauft.",
  ["Blue Suede Shoes use the same leather but sell for more to a vendor, so they save you about 13 gold on this step. If the pattern costs less than that on the Auction House, make these instead:"] = "Blaue Wildlederschuhe verbrauchen dasselbe Leder, bringen beim Händler aber mehr ein, damit sparst du bei diesem Schritt etwa 13 Gold. Wenn das Muster im Auktionshaus weniger kostet, stell stattdessen diese her:",
  ["36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Rugged Leather, 36 Blue Dye, 36 Rune Thread."] = "36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Unverwüstliches Leder, 36 Blauer Farbstoff, 36 Runenfaden.",
  ["53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Rugged Leather, 530 Runecloth, 53 Rune Thread"] = "53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Unverwüstliches Leder, 530 Runenstoff, 53 Runenfaden",
  ["The pattern is sold by {n:0::Jase Farlane} at Light's Hope Chapel in Eastern Plaguelands."] = "Das Muster wird von {n:0::Jase Farlane} an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern verkauft.",
  ["If you have the pattern, make these from 275 instead:"] = "Wenn du das Muster hast, stell stattdessen ab 275 diese her:",
  ["27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Rugged Leather, 27 Blue Dye, 27 Rune Thread."] = "27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Unverwüstliches Leder, 27 Blauer Farbstoff, 27 Runenfaden.",
  ["Blue Suede Hat"] = "Blauer Wildlederhut",
  ["{b}Someone with Leatherworking 300 has to place the Sewing Machine for you.{/b} You can't place a Sewing Machine yourself before 300, even if you buy one. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}Jemand mit Lederverarbeitung 300 muss die Nähmaschine für dich aufstellen.{/b} Vor 300 kannst du selbst keine Nähmaschine aufstellen, auch wenn du eine kaufst. Ich bin nicht sicher, ob das ein Versehen von Blizzard ist, es könnte sich also noch ändern.",
  ["If you can use one and have the pattern, you can make these from 280:"] = "Wenn du eine benutzen kannst und das Muster hast, kannst du ab 280 diese herstellen:",
  ["20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Rugged Leather, 80 Blue Dye, 20 Rune Thread."] = "20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Unverwüstliches Leder, 80 Blauer Farbstoff, 20 Runenfaden.",
  ["This WoW Forever Tailoring leveling guide will show you the fastest and cheapest way to level your Tailoring skill from 1 to 300. You will also find every trainer location and where to train Tailoring past 75, 150 and 225."] = "Dieser WoW-Forever-Leitfaden für Schneiderei zeigt dir den schnellsten und günstigsten Weg, deine Schneiderei-Fertigkeit von 1 auf 300 zu steigern. Außerdem findest du alle Lehrer und erfährst, wo du Schneiderei über 75, 150 und 225 hinaus erlernen kannst.",
  ["Below you will find the full shopping list, the Tailoring trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Tailoring uses cloth as its main material, but cloth drops from humanoids, so you don't need a gathering profession and you can combine Tailoring with anything. Enchanting is a popular choice because you can disenchant the things you make while leveling and use the dust to level Enchanting."] = "Unten findest du die vollständige Einkaufsliste, die Schneidereilehrer nach Startgebiet und Hauptstadt sowie die günstigsten Rezepte für jeden Fertigkeitsbereich vom Lehrling bis zum Fachmann. Schneiderei verwendet Stoff als Hauptmaterial, aber Stoff wird von Humanoiden fallen gelassen, daher brauchst du keinen Sammelberuf und kannst Schneiderei mit allem kombinieren. Verzauberkunst ist eine beliebte Wahl, weil du die Dinge, die du beim Leveln herstellst, entzaubern und den Staub zum Leveln von Verzauberkunst verwenden kannst.",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Tailoring Supply vendor nearby that sells the threads and dyes, {b}except{/b} the trainer in Tirisfal Glades. For that one, buy the Coarse Thread in Brill from {n:0:horde:Abigail Shiel}."] = "{b}HINWEIS:{/b} {b}Die meisten Lehrer{/b} haben einen Händler für Schneidereibedarf in der Nähe, der Garn und Farbstoffe verkauft, {b}außer{/b} dem Lehrer in Tirisfal. Kauf dort das grobe Garn in Brill bei {n:0:horde:Abigail Shiel}.",
  ["Alternative (if cheaper)"] = "Alternative (falls günstiger)",
  ["This list is not final yet, but the skill ranges come from the game data, so it should be pretty close. The 280-300 part is not included here yet."] = "Diese Liste ist noch nicht endgültig, aber die Fertigkeitsbereiche stammen aus den Spieldaten, sie sollte also ziemlich genau sein. Der Teil 280-300 ist hier noch nicht enthalten.",
  ["Tailoring Trainer Locations"] = "Standorte der Schneidereilehrer",
  ["Apprentice Tailoring has no level requirement in Forever, so you can learn it on a fresh character."] = "Schneiderei (Lehrling) hat in Forever keine Stufenvoraussetzung, du kannst es also schon mit einem neuen Charakter erlernen.",
  ["Undercity: {n:0:horde:Victor Ward}"] = "Unterstadt: {n:0:horde:Victor Ward}",
  ["Thunder Bluff: {n:0:horde:Vhan}"] = "Donnerfels: {n:0:horde:Vhan}",
  ["There is no Tailoring trainer in Durotar, go to {n:0:horde:Snang} in the Drag in Orgrimmar"] = "In Durotar gibt es keinen Schneidereilehrer, geh zu {n:0:horde:Snang} in der Gasse in Orgrimmar",
  ["There is no Tailoring trainer in Mulgore, go to {n:0:horde:Vhan} on the middle rise in Thunder Bluff"] = "In Mulgore gibt es keinen Schneidereilehrer, geh zu {n:0:horde:Vhan} auf der mittleren Anhöhe in Donnerfels",
  ["{n:0:horde:Bowen Brisboise} in the small house at Cold Hearth Manor, southwest of Brill"] = "{n:0:horde:Bowen Brisboise} im kleinen Haus bei Cold Hearth Manor, südwestlich von Brill",
  ["Stormwind City: {n:0:alliance:Lawrence Schneider}"] = "Sturmwind: {n:0:alliance:Lawrence Schneider}",
  ["Ironforge: {n:0:alliance:Uthrar Threx}"] = "Eisenschmiede: {n:0:alliance:Uthrar Threx}",
  ["{n:0:alliance:Eldrin} in a house at the Eastvale Logging Camp"] = "{n:0:alliance:Eldrin} in einem Haus im Holzfällerlager Osttal",
  ["There is no Tailoring trainer in Dun Morogh, go to {n:0:alliance:Uthrar Threx} at the Great Forge in Ironforge"] = "In Dun Morogh gibt es keinen Schneidereilehrer, geh zu {n:0:alliance:Uthrar Threx} an der Großen Schmiede in Eisenschmiede",
  ["There is no Tailoring trainer in Teldrassil, go to {n:0:alliance:Trianna} at the Craftsmen's Terrace in Darnassus"] = "In Teldrassil gibt es keinen Schneidereilehrer, geh zu {n:0:alliance:Trianna} auf der Terrasse der Handwerker in Darnassus",
  ["You can find every Tailoring trainer for Horde and Alliance on my WoW Forever Tailoring Trainers page."] = "Alle Schneidereilehrer für Horde und Allianz findest du auf meiner Seite zu den WoW-Forever-Schneidereilehrern.",
  ["Apprentice Tailoring (1-55)"] = "Schneiderei (Lehrling) (1-55)",
  ["30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Linen Cloth"] = "30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Leinenstoff",
  ["Keep the bolts, you need all of them for the belts."] = "Behalte die Ballen, du brauchst alle für die Gürtel.",
  ["28x {s:8776:inv_belt_05:Linen Belt} - 28 Bolt of Linen Cloth, 28 Coarse Thread"] = "28x {s:8776:inv_belt_05:Linen Belt} - 28 Leinenstoffballen, 28 Grobes Garn",
  ["Journeyman Tailoring (55-140)"] = "Schneiderei (Geselle) (55-140)",
  ["To train past 75, visit one of these trainers and learn Journeyman Tailoring. You need {b}Tailoring 50{/b} and {b}level 10{/b}:"] = "Um über 75 hinauszukommen, besuche einen dieser Lehrer und erlerne Schneiderei (Geselle). Du brauchst {b}Schneiderei 50{/b} und {b}Stufe 10{/b}:",
  ["Undercity: {n:0:horde:Rhiannon Davis}"] = "Unterstadt: {n:0:horde:Rhiannon Davis}",
  ["Thunder Bluff: {n:0:horde:Tepa}"] = "Donnerfels: {n:0:horde:Tepa}",
  ["Stormwind City: {n:0:alliance:Sellandus}"] = "Sturmwind: {n:0:alliance:Sellandus}",
  ["Ironforge: {n:0:alliance:Jormund Stonebrow}"] = "Eisenschmiede: {n:0:alliance:Jormund Stonebrow}",
  ["{b}Learn Journeyman Tailoring before you make these.{/b} You can reach past 75 with them, but you won't get any skill points above 75 until you learn it, so don't go AFK while crafting before you have it."] = "{b}Erlerne Schneiderei (Geselle), bevor du diese herstellst.{/b} Du kannst damit über 75 hinauskommen, bekommst aber über 75 keine Fertigkeitspunkte, bis du es erlernt hast. Geh also nicht AFK beim Herstellen, bevor du es hast.",
  ["45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Wool Cloth"] = "45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Wollstoff",
  ["Keep the bolts, you will need them later. In total you will need 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}) until 140, so you can also make all of them now."] = "Behalte die Ballen, du brauchst sie später. Insgesamt brauchst du bis 140 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}), du kannst also auch alle jetzt herstellen.",
  ["22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Bolt of Woolen Cloth, 22 Fine Thread"] = "22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Wollstoffballen, 22 Feines Garn",
  ["If the bolts already took you past 80, just make capes until 95."] = "Wenn dich die Ballen schon über 80 gebracht haben, stell einfach Umhänge bis 95 her.",
  ["5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Bolt of Woolen Cloth, 10 Fine Thread"] = "5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Wollstoffballen, 10 Feines Garn",
  ["54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Silk Cloth"] = "54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Seidenstoff",
  ["Keep the bolts, you will need them later. In total you will need 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}) until 190, so you can also make all of them now."] = "Behalte die Ballen, du brauchst sie später. Insgesamt brauchst du bis 190 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}), du kannst also auch alle jetzt herstellen.",
  ["29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Bolt of Woolen Cloth, 87 Fine Thread, 29 Elixir of Wisdom"] = "29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Wollstoffballen, 87 Feines Garn, 29 Elixier der Weisheit",
  ["You can buy {i:3383:inv_potion_06:Elixir of Wisdom} from the Auction House or ask an Alchemist."] = "Du kannst {i:3383:inv_potion_06:Elixir of Wisdom} im Auktionshaus kaufen oder einen Alchimisten fragen.",
  ["Expert Tailoring (140-200)"] = "Schneiderei (Experte) (140-200)",
  ["To train past 150, visit {n:0:horde:Josef Gregorian} in Undercity (Horde) or {n:0:alliance:Georgio Bolero} in Stormwind City (Alliance) and learn Expert Tailoring. You need {b}Tailoring 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Um über 150 hinauszukommen, besuche {n:0:horde:Josef Gregorian} in Unterstadt (Horde) oder {n:0:alliance:Georgio Bolero} in Sturmwind (Allianz) und erlerne Schneiderei (Experte). Du brauchst {b}Schneiderei 125{/b} und {b}Stufe 20{/b}, und es kostet 50 Silber.",
  ["23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Mageweave Cloth"] = "23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Magiestoff",
  ["Keep the bolts, you will need them later. In total you will need 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}) until 225, so you can also make all of them now."] = "Behalte die Ballen, du brauchst sie später. Insgesamt brauchst du bis 225 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}), du kannst also auch alle jetzt herstellen.",
  ["20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Bolt of Silk Cloth, 40 Red Dye, 40 Fine Thread"] = "20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Seidenstoffballen, 40 Roter Farbstoff, 40 Feines Garn",
  ["26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Bolt of Silk Cloth, 52 Red Dye, 52 Silken Thread"] = "26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Seidenstoffballen, 52 Roter Farbstoff, 52 Seidengarn",
  ["19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Bolt of Mageweave, 57 Silken Thread"] = "19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Magiestoffballen, 57 Seidengarn",
  ["Artisan Tailoring (200-300)"] = "Schneiderei (Fachmann) (200-300)",
  ["To train past 225, visit {n:0:horde:Daryl Stack} in Tarren Mill, Hillsbrad Foothills (Horde) or {n:0:alliance:Timothy Worthington} in Theramore Isle, Dustwallow Marsh (Alliance) and learn Artisan Tailoring. You need {b}Tailoring 200{/b} and {b}level 35{/b}."] = "Um über 225 hinauszukommen, besuche {n:0:horde:Daryl Stack} in Tarrens Mühle, Vorgebirge des Hügellands (Horde) oder {n:0:alliance:Timothy Worthington} auf der Insel Theramore, Düstermarschen (Allianz) und erlerne Schneiderei (Fachmann). Du brauchst {b}Schneiderei 200{/b} und {b}Stufe 35{/b}.",
  ["5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Bolt of Mageweave, 10 Heavy Silken Thread"] = "5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Magiestoffballen, 10 Schweres Seidengarn",
  ["{b}The Expert trainers in Undercity and Stormwind don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}Die Expertenlehrer in Unterstadt und Sturmwind lehren dieses Rezept nicht{/b}, du kannst es nur bei den beiden Lehrern oben lernen.",
  ["23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Runecloth"] = "23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Runenstoff",
  ["Keep the bolts, you will need them later. In total you will need 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}) until 280, so you can also make all of them now."] = "Behalte die Ballen, du brauchst sie später. Insgesamt brauchst du bis 280 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}), du kannst also auch alle jetzt herstellen.",
  ["26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Bolt of Mageweave, 52 Silken Thread"] = "26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Magiestoffballen, 52 Seidengarn",
  ["I recommend the bags right now simply because they are more useful. You can use them yourself, sell some, give them to friends or use them in your bank."] = "Ich empfehle an dieser Stelle die Taschen, einfach weil sie nützlicher sind. Du kannst sie selbst benutzen, einige verkaufen, sie Freunden geben oder in deiner Bank verwenden.",
  ["If you don't need the bags and don't want to sell them, make these instead."] = "Wenn du die Taschen nicht brauchst und nicht verkaufen willst, stell stattdessen diese her.",
  ["10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Bolt of Runecloth, 10 Rune Thread."] = "10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Runenstoffballen, 10 Runenfaden.",
  ["24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Bolt of Runecloth, 24 Rune Thread"] = "24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Runenstoffballen, 24 Runenfaden",
  ["11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Bolt of Runecloth, 44 Rugged Leather, 11 Rune Thread"] = "11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Runenstoffballen, 44 Unverwüstliches Leder, 11 Runenfaden",
  ["The pattern is sold by {n:0::Qia} in Winterspring."] = "Das Muster wird von {n:0::Qia} in Winterquell verkauft.",
  ["39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Bolt of Runecloth, 39 Ironweb Spider Silk, 39 Rune Thread"] = "39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Runenstoffballen, 39 Ironweb Spider Silk, 39 Runenfaden",
  ["The pattern is sold by {n:0::Pexmit} in Mount Hyjal. It's bind on pickup, so buy it with the character that levels Tailoring."] = "Das Muster wird von {n:0::Pexmit} am Hyjal verkauft. Es wird beim Aufheben gebunden, kauf es also mit dem Charakter, der Schneiderei levelt.",
  ["Horde players can also get it as the reward for {q:95769::Threading a Solution}, a quest from {n:265788::Kal'tinzan} in Elderwild, Mount Hyjal. It needs level 54 and 6 Bolt of Runecloth. It's probably a Tailoring quest, but I don't know yet what skill it needs."] = "Spieler der Horde können es auch als Belohnung für {q:95769::Threading a Solution} bekommen, eine Quest von {n:265788::Kal'tinzan} in Elderwild am Hyjal. Sie erfordert Stufe 54 und 6 Runenstoffballen. Wahrscheinlich ist es eine Schneidereiquest, aber ich weiß noch nicht, welche Fertigkeit sie erfordert.",
  ["Make the {s:18449:inv_shoulder_21:Runecloth Shoulders} if you can get the pattern. These are all the recipes I found so far that still give points after 280. I left out the ones that aren't worth it for leveling, and there might be new ones that nobody has found yet."] = "Stell die {s:18449:inv_shoulder_21:Runecloth Shoulders} her, wenn du an das Muster kommst. Das sind alle Rezepte, die ich bisher gefunden habe und die nach 280 noch Punkte geben. Die, die sich zum Leveln nicht lohnen, habe ich weggelassen, und vielleicht gibt es neue, die noch niemand gefunden hat.",
  ["Range"] = "Bereich",
  ["Materials"] = "Materialien",
  ["Pattern"] = "Muster",
  ["World drop, on the Auction House"] = "Weltdrop, im Auktionshaus",
  ["Rare, grab it if you see it on the Auction House"] = "Selten, schnapp es dir, wenn du es im Auktionshaus siehst",
  ["You can get a few more points with these, but they stop giving skill points before 300, so you can't reach 300 with them:"] = "Mit diesen kannst du noch ein paar Punkte holen, aber sie geben vor 300 keine Fertigkeitspunkte mehr, du kannst damit also nicht 300 erreichen:",
  ["{n:0::Pexmit} in Mount Hyjal"] = "{n:0::Pexmit} am Hyjal",
  ["Recipes that need a Loom"] = "Rezepte, die einen Webstuhl brauchen",
  ["{b}These recipes need a Loom, and you can only make a Loom at Tailoring 300.{/b} They could be used for leveling, but for now you would need a camp where another tailor already placed a Loom. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}Diese Rezepte brauchen einen Webstuhl, und einen Webstuhl kannst du erst mit Schneiderei 300 herstellen.{/b} Sie könnten zum Leveln verwendet werden, aber vorerst bräuchtest du ein Lager, in dem ein anderer Schneider bereits einen Webstuhl aufgestellt hat. Ich bin nicht sicher, ob das ein Versehen von Blizzard ist, es könnte sich also noch ändern.",
  ["These are the Cenarion Circle patterns from {n:0::Mishta} in Silithus:"] = "Das sind die Muster des Zirkels des Cenarius von {n:0::Mishta} in Silithus:",
  ["Requires"] = "Voraussetzung",
  ["5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} or {s:1297120:inv_gauntlets_18:Venomspew Gloves}"] = "5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} oder {s:1297120:inv_gauntlets_18:Venomspew Gloves}",
  ["20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} oder {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Friendly"] = "Zirkel des Cenarius: Freundlich",
  ["5x {s:1297124:inv_belt_03:Swarmtender's Cord} or {s:1297121:inv_belt_25:Venomspew Cord}"] = "5x {s:1297124:inv_belt_03:Swarmtender's Cord} oder {s:1297121:inv_belt_25:Venomspew Cord}",
  ["30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} oder {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Honored"] = "Zirkel des Cenarius: Wohlwollend",
  ["18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} or {s:1297122:inv_boots_cloth_04:Venomspew Footpads}"] = "18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} oder {s:1297122:inv_boots_cloth_04:Venomspew Footpads}",
  ["90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} oder {i:7082:spell_nature_earthbind:Essence of Air}",
  ["This WoW Forever Mining leveling guide will show you the fastest way to level Mining from 1 to 300. You will also find every trainer location and where to train Mining past 75, 150 and 225."] = "Dieser WoW-Forever-Leitfaden für Bergbau zeigt dir den schnellsten Weg, Bergbau von 1 auf 300 zu leveln. Außerdem findest du alle Lehrer und erfährst, wo du Bergbau über 75, 150 und 225 hinaus erlernen kannst.",
  ["Below you will find the Mining trainers by starting zone and capital city, and the best zones to mine in for every skill range. Mining serves two professions, Blacksmithing and Engineering, so it's really good combined with these two. Check out my Forever Blacksmithing leveling guide or my Forever Engineering leveling guide if you want to level one of them."] = "Unten findest du die Bergbaulehrer nach Startgebiet und Hauptstadt sowie die besten Gebiete zum Abbauen für jeden Fertigkeitsbereich. Bergbau beliefert zwei Berufe, Schmiedekunst und Ingenieurskunst, daher passt es sehr gut zu diesen beiden. Schau dir meinen Forever-Leitfaden für Schmiedekunst oder Ingenieurskunst an, wenn du einen davon leveln willst.",
  ["WoW Forever added a couple of new ores, bars and recipes. You can check them out here:"] = "WoW Forever hat ein paar neue Erze, Barren und Rezepte hinzugefügt. Du kannst sie dir hier ansehen:",
  ["Mining Trainer Locations"] = "Standorte der Bergbaulehrer",
  ["Every capital city except Darnassus has a Mining trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Jede Hauptstadt außer Darnassus hat einen Bergbaulehrer. Du kannst auch eine Wache fragen, dann wird er mit einer roten Fahne auf deiner Karte markiert.",
  ["{b}Capital cities:{/b}"] = "{b}Hauptstädte:{/b}",
  ["Undercity: {n:0:horde:Brom Killian}"] = "Unterstadt: {n:0:horde:Brom Killian}",
  ["Thunder Bluff: {n:0:horde:Brek Stonehoof}"] = "Donnerfels: {n:0:horde:Brek Stonehoof}",
  ["{b}Starting zones:{/b}"] = "{b}Startgebiete:{/b}",
  ["{n:0:horde:Norzsh} in the Valley of Trials (only up to 75) {n:0:horde:Krunn} in Razor Hill"] = "{n:0:horde:Norzsh} im Tal der Prüfungen (nur bis 75) {n:0:horde:Krunn} in Klingenhügel",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache (only up to 75) {n:0:horde:Brek Stonehoof} in Thunder Bluff"] = "{n:0:horde:Vartha Rockmane} im Camp Narache (nur bis 75) {n:0:horde:Brek Stonehoof} in Donnerfels",
  ["{n:0:horde:Walter Mason} in Deathknell (only up to 75) {n:0:horde:Brom Killian} in Undercity"] = "{n:0:horde:Walter Mason} in Todesend (nur bis 75) {n:0:horde:Brom Killian} in Unterstadt",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining. The trainers on the island are {n:0::Halavuul Cragwind} in Valanaar and {n:0::Messana Crestwind} in Shen'dar Village."] = "In Thendal Village, wo du startest, gibt es keinen Lehrer, aber du brauchst auch keinen. {q:93552::Harvesting Windstones} ist eine der ersten Quests, die du in Thendal Village bekommst. Wähl {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} als Belohnung, es bringt dir Bergbau bei. Die Lehrer auf der Insel sind {n:0::Halavuul Cragwind} in Valanaar und {n:0::Messana Crestwind} in Shen'dar Village.",
  ["Stormwind City: {n:0:alliance:Gelman Stonehand}"] = "Sturmwind: {n:0:alliance:Gelman Stonehand}",
  ["Ironforge: {n:0:alliance:Geofram Bouldertoe}"] = "Eisenschmiede: {n:0:alliance:Geofram Bouldertoe}",
  ["Darnassus: no trainer, the closest one is {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "Darnassus: kein Lehrer, der nächste ist {n:0:alliance:Kurdram Stonehammer} in Auberdine, Dunkelküste",
  ["{n:0:alliance:Kelsey Fargo} (only up to 75) {n:0:alliance:Gelman Stonehand} in Stormwind City"] = "{n:0:alliance:Kelsey Fargo} (nur bis 75) {n:0:alliance:Gelman Stonehand} in Sturmwind",
  ["{n:0:alliance:Sally Swiftwrench} (only up to 75) {n:0:alliance:Yarr Hammerstone} at Steelgrill's Depot {n:0:alliance:Dank Drizzlecut} at Gol'Bolar Quarry"] = "{n:0:alliance:Sally Swiftwrench} (nur bis 75) {n:0:alliance:Yarr Hammerstone} in Stahlrosts Depot {n:0:alliance:Dank Drizzlecut} im Steinbruch von Gol'Bolar",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "{n:0:alliance:Fanorran Stilloak} bei Aldrassil im Schattenhain (nur bis 75) {n:0:alliance:Kurdram Stonehammer} in Auberdine, Dunkelküste",
  ["You can find every Mining trainer for Horde and Alliance on my WoW Forever Mining Trainers page."] = "Alle Bergbaulehrer für Horde und Allianz findest du auf meiner Seite zu den WoW-Forever-Bergbaulehrern.",
  ["Track Ore on Your Minimap"] = "Erz auf deiner Minikarte aufspüren",
  ["You can only track one thing at a time, so {b}you can't track minerals and herbs together{/b}."] = "Du kannst immer nur eine Sache gleichzeitig aufspüren, {b}Mineralien und Kräuter zusammen aufzuspüren geht also nicht{/b}.",
  ["You learn {s:2580:spell_nature_earthquake:Find Minerals} together with Mining, but it's not turned on by default:"] = "Du lernst {s:2580:spell_nature_earthquake:Find Minerals} zusammen mit Bergbau, aber es ist standardmäßig nicht aktiviert:",
  ["Open the Professions window with the hammer and pick button, the 2nd button in the menu at the bottom of your screen."] = "Öffne das Berufefenster mit dem Hammer-und-Spitzhacke-Button, dem 2. Button im Menü unten auf deinem Bildschirm.",
  ["Click Find Minerals in the Mining box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "Klick im Bergbau-Bereich auf Mineraliensuche. {b}Ich empfehle, es auf deine Aktionsleiste zu ziehen, in die Nähe der Buffs, die du nach dem Tod benutzt.{/b} So wird es dir zur Gewohnheit und du vergisst es seltener.",
  ["The Find Minerals buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "Der Buff Mineraliensuche erscheint neben deiner Minikarte. {b}Dein Aufspüren schaltet sich bei jedem Tod ab, vergiss also nicht, es wieder einzuschalten!{/b}",
  ["The Find Minerals button in the WoW Forever Professions window"] = "Der Button Mineraliensuche im WoW-Forever-Berufefenster",
  ["Mining Skill Bonuses"] = "Boni auf die Bergbaufertigkeit",
  ["You don't need these, but they help when you are stuck between two ores. With +5 you can mine Iron Deposits from 120 instead of 125, so you can skip the last few slow points of Tin."] = "Du brauchst sie nicht, aber sie helfen, wenn du zwischen zwei Erzen festhängst. Mit +5 kannst du Eisenvorkommen schon ab 120 statt 125 abbauen und die letzten langsamen Punkte bei Zinn überspringen.",
  ["Item"] = "Gegenstand",
  ["Mining"] = "Bergbau",
  ["How to get it"] = "So bekommst du es",
  ["An enchanter"] = "Ein Verzauberer",
  ["Made by Engineers, you need Engineering 205 to wear it"] = "Von Ingenieuren hergestellt, zum Tragen brauchst du Ingenieurskunst 205",
  ["Reward of A Miner Problem, an Alliance quest in the Riverglades"] = "Belohnung von A Miner Problem, einer Allianzquest in den Riverglades",
  ["Drops from Miner Johnson in The Deadmines"] = "Droppt von Minenarbeiter Johnson in den Todesminen",
  ["Smelting to 105"] = "Verhütten bis 105",
  ["You can skip the first 105 skill points by buying ores on the Auction House and smelting them. If you prefer leveling Mining the normal way, scroll down to the mining routes. But I would recommend smelting if you have the gold, as it saves a lot of time. Sometimes the bars even sell for more than the ores or they are very close in price, so it's not like you are losing much by doing this."] = "Du kannst die ersten 105 Fertigkeitspunkte überspringen, indem du Erze im Auktionshaus kaufst und verhüttest. Wenn du Bergbau lieber auf normale Weise levelst, scroll runter zu den Bergbaurouten. Ich empfehle aber das Verhütten, wenn du das Gold hast, weil es viel Zeit spart. Manchmal verkaufen sich die Barren sogar teurer als die Erze oder der Preis ist sehr ähnlich, du verlierst dabei also nicht viel.",
  ["Buy around 140 {i:2770:inv_ore_copper_01:Copper Ore} and 70 {i:2771:inv_ore_tin_01:Tin Ore}. Smelting is mostly yellow and green, so you might need a few more if you are unlucky."] = "Kauf etwa 140 {i:2770:inv_ore_copper_01:Copper Ore} und 70 {i:2771:inv_ore_tin_01:Tin Ore}. Verhütten ist meist gelb und grün, bei Pech brauchst du also vielleicht ein paar mehr.",
  ["Notes"] = "Hinweise",
  ["120-140x {s:2657:inv_ingot_02:Smelt Copper} until you reach 65. Keep 70 Copper Bars, you will need them for Bronze."] = "120-140x {s:2657:inv_ingot_02:Smelt Copper} bis du 65 erreichst. Behalte 70 Kupferbarren, du brauchst sie für Bronze.",
  ["Learn Journeyman Mining, Smelt Tin and Smelt Bronze from your trainer. Make 70x {s:3304:inv_ingot_05:Smelt Tin}. It turns grey at 75, but you need all 70 Tin Bars for Bronze anyway."] = "Erlerne bei deinem Lehrer Bergbau (Geselle), Zinn verhütten und Bronze verhütten. Mach 70x {s:3304:inv_ingot_05:Smelt Tin}. Es wird bei 75 grau, aber du brauchst ohnehin alle 70 Zinnbarren für Bronze.",
  ["Make 70x {s:2659:inv_ingot_bronze:Smelt Bronze} from the Copper Bars and Tin Bars you made. You will end up somewhere between 100 and 110, so you might need a few more."] = "Mach 70x {s:2659:inv_ingot_bronze:Smelt Bronze} aus den Kupfer- und Zinnbarren, die du hergestellt hast. Du landest irgendwo zwischen 100 und 110, brauchst also vielleicht ein paar mehr.",
  ["Learn Smelt Silver from your trainer. Check the price of Silver Ore and Silver Bar first, because this part can get expensive. If you don't mind the cost, make 35-45x {s:2658:inv_ingot_01:Smelt Silver} until you reach 120. The last 5 points to 125 could take around 50 more Silver Ore, so I recommend mining from 120. (or keep smelting if you have the gold) Iron Deposits need Mining 125, but with +5 from the Mining Skill Bonuses above you can mine them from 120, so you can skip Tin and go straight to Iron."] = "Erlerne bei deinem Lehrer Silber verhütten. Prüf zuerst den Preis von Silbererz und Silberbarren, denn dieser Teil kann teuer werden. Wenn dich die Kosten nicht stören, mach 35-45x {s:2658:inv_ingot_01:Smelt Silver}, bis du 120 erreichst. Die letzten 5 Punkte bis 125 könnten etwa 50 weitere Silbererze kosten, daher empfehle ich, ab 120 abzubauen. (oder weiter zu verhütten, wenn du das Gold hast) Eisenvorkommen erfordern Bergbau 125, aber mit +5 von den Boni auf die Bergbaufertigkeit oben kannst du sie ab 120 abbauen, so kannst du Zinn überspringen und direkt zu Eisen gehen.",
  ["{b}Don't forget to buy{/b} a {i:2901:inv_pick_02:Mining Pick} from the Mining Supplier near your trainer or from the trainer!"] = "{b}Vergiss nicht{/b}, eine {i:2901:inv_pick_02:Mining Pick} zu kaufen, beim Bergbaubedarfshändler in der Nähe deines Lehrers oder beim Lehrer selbst!",
  ["You can buy one from these vendors:"] = "Du kannst eine bei diesen Händlern kaufen:",
  ["{n:0:horde:Norzsh} in the Valley of Trials, {n:0:horde:Flakk} in Razor Hill"] = "{n:0:horde:Norzsh} im Tal der Prüfungen, {n:0:horde:Flakk} in Klingenhügel",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache, {n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "{n:0:horde:Vartha Rockmane} im Camp Narache, {n:0:horde:Wunna Darkmane} im Dorf der Bluthufe",
  ["{n:0:horde:Walter Mason} in Deathknell, {n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Walter Mason} in Todesend, {n:0:horde:Abigail Shiel} in Brill",
  ["{n:0:horde:Gorina} in the Valley of Honor"] = "{n:0:horde:Gorina} im Tal der Ehre",
  ["{n:0:horde:Elizabeth Van Talen} in the Rogues' Quarter"] = "{n:0:horde:Elizabeth Van Talen} im Schurkenviertel",
  ["{n:0:alliance:Brother Danil} in Northshire Valley, {n:0:alliance:Tharynn Bouden} in Goldshire"] = "{n:0:alliance:Brother Danil} im Nordhaintal, {n:0:alliance:Tharynn Bouden} in Goldhain",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen, {n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "{n:0:alliance:Fanorran Stilloak} bei Aldrassil im Schattenhain, {n:0:alliance:Narret Shadowgrove} in Dolanaar",
  ["{n:0:alliance:Brooke Stonebraid} in the Dwarven District"] = "{n:0:alliance:Brooke Stonebraid} im Zwergendistrikt",
  ["{n:0:alliance:Thurgrum Deepforge} in The Great Forge"] = "{n:0:alliance:Thurgrum Deepforge} in der Großen Schmiede",
  ["Like I said above, for most high level players I think it's best to skip this part and smelt your way up to at least 105. But if you prefer mining and you can choose your zone, I think {b}Durotar{/b} is the best for Horde and {b}Elwynn Forest{/b} for Alliance."] = "Wie oben gesagt, halte ich es für die meisten hochstufigen Spieler für am besten, diesen Teil zu überspringen und sich mindestens bis 105 hochzuverhütten. Wenn du aber lieber abbaust und dir das Gebiet aussuchen kannst, finde ich {b}Durotar{/b} für die Horde und den {b}Wald von Elwynn{/b} für die Allianz am besten.",
  ["One or two laps around the zone will get you enough Copper Ore to reach 65 with smelting."] = "Eine oder zwei Runden durch das Gebiet bringen dir genug Kupfererz, um mit Verhütten 65 zu erreichen.",
  ["After you do one lap, {b}stop at Razor Hill and smelt your Copper Ore{/b} into Copper Bars."] = "Nach einer Runde {b}halte in Klingenhügel an und verhütte dein Kupfererz{/b} zu Kupferbarren.",
  ["Mining route in Durotar"] = "Bergbauroute in Durotar",
  ["The cave marked with the red circle has 5 Copper Veins inside, {b}the respawn rate is so fast that you can basically stay inside the cave and level there{/b}. The cave layout is also very good because there is a drop down at the end, so you can quickly return to the start and continue mining. If the respawn rate is not enough for you or there is competition, just run outside, mine a couple of Copper Veins and go back to the cave."] = "In der rot eingekreisten Höhle gibt es 5 Kupferadern, {b}die Respawnrate ist so hoch, dass du praktisch in der Höhle bleiben und dort leveln kannst{/b}. Der Aufbau der Höhle ist auch sehr gut, weil es am Ende einen Absprung gibt, so kommst du schnell zum Anfang zurück und kannst weiter abbauen. Wenn dir die Respawnrate nicht reicht oder es Konkurrenz gibt, lauf einfach raus, bau ein paar Kupferadern ab und geh zurück in die Höhle.",
  ["You can also just do a full lap in Mulgore, the route is very easy to follow, it's basically a loop around the edge of the zone. But I found the cave to be better without a mount."] = "Du kannst auch einfach eine volle Runde in Mulgore drehen, die Route ist sehr leicht zu folgen, im Grunde eine Schleife am Rand des Gebiets entlang. Ohne Reittier fand ich die Höhle aber besser.",
  ["{b}You can smelt your ore at the Bael'dun Digsite{/b}, the dwarf camp just north of the cave has a forge and an anvil. (marked on the map) The dwarves there are hostile."] = "{b}Du kannst dein Erz an der Grabungsstätte von Bael'dun verhütten{/b}, das Zwergenlager direkt nördlich der Höhle hat eine Schmiede und einen Amboss. (auf der Karte markiert) Die Zwerge dort sind feindlich.",
  ["Mining route in Mulgore with the forge and anvil at the Bael'dun Digsite"] = "Bergbauroute in Mulgore mit Schmiede und Amboss an der Grabungsstätte von Bael'dun",
  ["Both routes are good. The route on the east side of the zone will probably have fewer people, because there are fewer quest hubs there."] = "Beide Routen sind gut. Auf der Route im Osten des Gebiets sind wahrscheinlich weniger Leute, weil es dort weniger Questgeber gibt.",
  ["{b}Stop at Brill after one lap{/b} to smelt your Copper Ore."] = "{b}Halte nach einer Runde in Brill an{/b}, um dein Kupfererz zu verhütten.",
  ["Mining route in Tirisfal Glades"] = "Bergbauroute in Tirisfal",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining."] = "{q:93552::Harvesting Windstones} ist eine der ersten Quests, die du in Thendal Village bekommst. Wähl {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} als Belohnung, es bringt dir Bergbau bei.",
  ["The respawn rate is very fast around this area, sometimes the veins spawned right on top of me. You can do a larger route, but without a mount and with the fast respawn rate I found it wasn't needed."] = "Die Respawnrate ist in dieser Gegend sehr hoch, manchmal sind die Adern direkt unter mir erschienen. Du kannst eine größere Route laufen, aber ohne Reittier und bei der hohen Respawnrate fand ich das nicht nötig.",
  ["{b}Stop at Shen'dar Village after one lap{/b} to smelt your Copper Ore."] = "{b}Halte nach einer Runde in Shen'dar Village an{/b}, um dein Kupfererz zu verhütten.",
  ["Mining route on Zephras Isle"] = "Bergbauroute auf Zephras Isle",
  ["Just move back and forth along the marked route, and clear the cave if you are high enough level. The respawn rate is quite fast inside the cave, so you might not even have to leave it, it depends on your level. You can also just skip the cave, the respawn rate seems to be fast enough on the route, but then do the small detour to the north too."] = "Lauf einfach auf der markierten Route hin und her und räum die Höhle aus, wenn deine Stufe hoch genug ist. In der Höhle ist die Respawnrate ziemlich hoch, je nach Stufe musst du sie vielleicht nicht einmal verlassen. Du kannst die Höhle auch auslassen, die Respawnrate auf der Route scheint hoch genug zu sein, dann mach aber auch den kleinen Abstecher nach Norden.",
  ["{b}Stop at Goldshire after one lap{/b} to smelt your Copper Ore."] = "{b}Halte nach einer Runde in Goldhain an{/b}, um dein Kupfererz zu verhütten.",
  ["Mining route in Elwynn Forest"] = "Bergbauroute im Wald von Elwynn",
  ["Not much to say about this one, just do loops around this area. You don't have to go inside the cave, it's optional and the respawn rate outside is quite fast."] = "Dazu gibt es nicht viel zu sagen, lauf einfach Runden in dieser Gegend. Du musst nicht in die Höhle, sie ist optional und die Respawnrate draußen ist ziemlich hoch.",
  ["{b}Stop at Kharanos after one lap{/b} to smelt your Copper Ore."] = "{b}Halte nach einer Runde in Kharanos an{/b}, um dein Kupfererz zu verhütten.",
  ["Mining route in Dun Morogh"] = "Bergbauroute in Dun Morogh",
  ["These two caves have an insanely fast respawn rate. I don't know if it stays like this, but right now you can just stay inside the caves and level there."] = "Diese beiden Höhlen haben eine wahnsinnig hohe Respawnrate. Ich weiß nicht, ob das so bleibt, aber im Moment kannst du einfach in den Höhlen bleiben und dort leveln.",
  ["There is no forge in Teldrassil, {b}the closest one is at the Warrior's Terrace in Darnassus{/b}."] = "In Teldrassil gibt es keine Schmiede, {b}die nächste ist an der Terrasse der Krieger in Darnassus{/b}.",
  ["Mining route in Teldrassil"] = "Bergbauroute in Teldrassil",
  ["Visit your trainer and learn Journeyman Mining, it requires Mining 50. The new Junior Mining Trainers in the starting areas won't teach you Journeyman Mining."] = "Besuche deinen Lehrer und erlerne Bergbau (Geselle), es erfordert Bergbau 50. Die neuen Junior-Bergbaulehrer in den Startgebieten bringen dir Bergbau (Geselle) nicht bei.",
  ["If you have any Copper Ore or Tin Ore at this point, smelt them and make Bronze Bars before you head out, because Bronze stops giving skill points around 105."] = "Wenn du jetzt noch Kupfer- oder Zinnerz hast, verhütte es und stell Bronzebarren her, bevor du losziehst, denn Bronze gibt ab etwa 105 keine Fertigkeitspunkte mehr.",
  ["For Alliance, the {b}Wetlands{/b} is the best one by far if you can manage the cave. For Horde it's the {b}Silverpine Forest{/b} cave or {b}Hillsbrad Foothills{/b}. The rest are pretty even, hard to judge."] = "Für die Allianz ist das {b}Sumpfland{/b} mit Abstand am besten, wenn du mit der Höhle klarkommst. Für die Horde ist es die Höhle im {b}Silberwald{/b} oder das {b}Vorgebirge des Hügellands{/b}. Die anderen sind ziemlich gleichwertig, schwer zu beurteilen.",
  ["Ores in these zones: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}"] = "Erze in diesen Gebieten: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}",
  ["Tin Veins need Mining 65 and Silver Veins 75."] = "Zinnadern erfordern Bergbau 65 und Silberadern 75.",
  ["Wetlands"] = "Sumpfland",
  ["Silverpine Forest"] = "Silberwald",
  ["Hillsbrad Foothills"] = "Vorgebirge des Hügellands",
  ["The Barrens"] = "Brachland",
  ["Ashenvale"] = "Eschental",
  ["Stonetalon Mountains"] = "Steinkrallengebirge",
  ["This cave in the Wetlands is the best place for Alliance players to level Mining. The cave is full of Tin Veins and Incendicite Mineral Veins with a very fast respawn time."] = "Diese Höhle im Sumpfland ist für Spieler der Allianz der beste Ort, um Bergbau zu leveln. Die Höhle ist voller Zinnadern und Pyrophormineraladern mit sehr schneller Respawnzeit.",
  ["The mobs are around level 20 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Die Gegner sind etwa Stufe 20 und {b}in Forever respawnen sie viel schneller, du solltest also ein paar Stufen über ihnen sein{/b}, sonst erscheinen sie ständig direkt neben dir.",
  ["Mining route in the Wetlands"] = "Bergbauroute im Sumpfland",
  ["This cave has 3 vein spawn points with a very fast respawn time, just mine the veins and wait for the respawn. (around 2 minutes)"] = "Diese Höhle hat 3 Spawnpunkte für Adern mit sehr schneller Respawnzeit, bau einfach die Adern ab und warte auf den Respawn. (etwa 2 Minuten)",
  ["The mobs are around level 21-22 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Die Gegner sind etwa Stufe 21-22 und {b}in Forever respawnen sie viel schneller, du solltest also ein paar Stufen über ihnen sein{/b}, sonst erscheinen sie ständig direkt neben dir.",
  ["Mining route in Silverpine Forest"] = "Bergbauroute im Silberwald",
  ["This cave has several Tin Veins that respawn very fast. There are also veins outside, so if you clear it too fast you can just run outside and mine a few there too."] = "Diese Höhle hat mehrere Zinnadern, die sehr schnell respawnen. Draußen gibt es auch Adern, wenn du also zu schnell durch bist, lauf einfach raus und bau dort auch ein paar ab.",
  ["The mobs are around level 13-15 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Die Gegner sind etwa Stufe 13-15 und {b}in Forever respawnen sie viel schneller, du solltest also ein paar Stufen über ihnen sein{/b}, sonst erscheinen sie ständig direkt neben dir.",
  ["Mining route in Westfall"] = "Bergbauroute in Westfall",
  ["This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area. The route goes around a Horde town, so I'm not sure how it works for Alliance. I think you can probably avoid the guards, but I only tested this one with a Horde character."] = "Das ist das Beste, wenn du lieber auf normale Weise abbaust, aber hier hast du vielleicht mehr Konkurrenz durch andere Spieler, weil die Gegend beliebt ist. Die Route führt um eine Stadt der Horde herum, ich bin also nicht sicher, wie das für die Allianz funktioniert. Wahrscheinlich kannst du den Wachen ausweichen, aber ich habe sie nur mit einem Hordecharakter getestet.",
  ["Mining route in Hillsbrad Foothills"] = "Bergbauroute im Vorgebirge des Hügellands",
  ["The mobs are around level 22-26 here, so it's best to farm here if you are above those levels. But the respawn rate is fast."] = "Die Gegner hier sind etwa Stufe 22-26, farm hier also am besten, wenn du über diesen Stufen bist. Die Respawnrate ist aber hoch.",
  ["Mining route in The Barrens"] = "Bergbauroute im Brachland",
  ["A very straightforward route that is easy to follow. This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area."] = "Eine sehr einfache Route, der man leicht folgen kann. Das ist das Beste, wenn du lieber auf normale Weise abbaust, aber hier hast du vielleicht mehr Konkurrenz durch andere Spieler, weil die Gegend beliebt ist.",
  ["Mining route in Ashenvale"] = "Bergbauroute im Eschental",
  ["This route might not work if more than one player is leveling Mining there, because when I tested it there were very few people around. But this place usually has fewer people, so I think it's a good alternative if you don't want to level in caves. The only downside is that sometimes an Iron Deposit spawns instead of a Tin Vein, and you can't mine it yet."] = "Diese Route funktioniert vielleicht nicht, wenn mehr als ein Spieler dort Bergbau levelt, denn als ich sie getestet habe, waren nur sehr wenige Leute da. Hier sind aber normalerweise weniger Leute, daher finde ich es eine gute Alternative, wenn du nicht in Höhlen leveln willst. Der einzige Nachteil ist, dass manchmal ein Eisenvorkommen statt einer Zinnader erscheint, das du noch nicht abbauen kannst.",
  ["Mining route in Stonetalon Mountains"] = "Bergbauroute im Steinkrallengebirge",
  ["From this point the guide follows the standard Classic Mining routes. The beta cap was 30, so I couldn't properly test Arathi and Desolace. I'll revise this section once I level my character higher on live, but the main change is the ore respawn rate, so most routes should work and you can probably take shorter routes in most zones."] = "Ab hier folgt der Leitfaden den normalen Classic-Bergbaurouten. Die Stufengrenze in der Beta lag bei 30, daher konnte ich Arathi und Desolace nicht richtig testen. Ich überarbeite diesen Abschnitt, sobald ich meinen Charakter auf dem Live-Server höher gelevelt habe, aber die wichtigste Änderung ist die Respawnrate der Erze, die meisten Routen sollten also funktionieren und in den meisten Gebieten kannst du wahrscheinlich kürzere Routen nehmen.",
  ["{b}Visit your trainer and learn Expert Mining{/b}, it requires Mining 125."] = "{b}Besuche deinen Lehrer und erlerne Bergbau (Experte){/b}, es erfordert Bergbau 125.",
  ["Smelting Iron and Gold (optional)"] = "Eisen und Gold verhütten (optional)",
  ["If you want to save some time and have the gold, buy around 20 {i:2772:inv_ore_iron_01:Iron Ore} and make {s:3307:inv_ingot_iron:Smelt Iron} until 135 before you head out mining. After 135 it rarely gives a point, so don't count on reaching 140."] = "Wenn du etwas Zeit sparen willst und das Gold hast, kauf etwa 20 {i:2772:inv_ore_iron_01:Iron Ore} und mach {s:3307:inv_ingot_iron:Smelt Iron} bis 135, bevor du zum Abbauen losziehst. Nach 135 gibt es selten einen Punkt, rechne also nicht damit, 140 zu erreichen.",
  ["At 155 you can learn {s:3308:inv_ingot_03:Smelt Gold} from your trainer. It gives a point every time until 170, so around 22 Gold Ore takes you from 155 to 175 and you can start on Mithril right away. I recommend checking the price of Gold Ore and Gold Bar first."] = "Bei 155 kannst du {s:3308:inv_ingot_03:Smelt Gold} bei deinem Lehrer erlernen. Bis 170 gibt es jedes Mal einen Punkt, etwa 22 Golderze bringen dich also von 155 auf 175 und du kannst sofort mit Mithril anfangen. Ich empfehle, zuerst den Preis von Golderz und Goldbarren zu prüfen.",
  ["If you have a {b}lower level character{/b} around level 30, stick to the {b}Thousand Needles{/b} route, that's the safest. If you have a {b}higher level character or a mount{/b} already, I recommend {b}Arathi Highlands{/b}."] = "Wenn du einen {b}niedrigstufigen Charakter{/b} um Stufe 30 hast, bleib bei der Route in {b}Tausend Nadeln{/b}, das ist die sicherste. Wenn du schon einen {b}höherstufigen Charakter oder ein Reittier{/b} hast, empfehle ich das {b}Arathihochland{/b}.",
  ["Ores in these zones: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}"] = "Erze in diesen Gebieten: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}",
  ["Iron Deposits need Mining 125 and Gold Veins 155."] = "Eisenvorkommen erfordern Bergbau 125 und Goldadern 155.",
  ["Arathi Highlands"] = "Arathihochland",
  ["Thousand Needles"] = "Tausend Nadeln",
  ["There are 4 caves marked with red circles on the map. Make sure to go all the way to the end of each cave because you won't see all the mining veins from the entrance."] = "Auf der Karte sind 4 Höhlen rot eingekreist. Geh in jeder Höhle ganz bis zum Ende, denn vom Eingang aus siehst du nicht alle Adern.",
  ["Low level players should skip all 4 caves, and low level Alliance players should take a detour and go south of Hammerfall!"] = "Niedrigstufige Spieler sollten alle 4 Höhlen auslassen, und niedrigstufige Spieler der Allianz sollten einen Umweg südlich an Hammerfall vorbei machen!",
  ["Mining route in Arathi Highlands"] = "Bergbauroute im Arathihochland",
  ["Mining route in Thousand Needles"] = "Bergbauroute in Tausend Nadeln",
  ["Mining route in Desolace"] = "Bergbauroute in Desolace",
  ["To train past 225, visit your trainer and learn Artisan Mining, it requires Mining 200."] = "Um über 225 hinauszukommen, besuche deinen Lehrer und erlerne Bergbau (Fachmann), es erfordert Bergbau 200.",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}"] = "Erze in diesen Gebieten: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}",
  ["Mithril Deposits need Mining 175 and Truesilver Deposits 230."] = "Mithrilablagerungen erfordern Bergbau 175 und Echtsilberablagerungen 230.",
  ["The Hinterlands"] = "Hinterland",
  ["The red route should be skipped by lower level players because the area is filled with level 62 elites. Lower level players might also want to consider skipping the cave marked with a red circle on the map. (depends on your gear/class)"] = "Niedrigstufige Spieler sollten die rote Route auslassen, weil die Gegend voller Elitegegner der Stufe 62 ist. Niedrigstufige Spieler sollten eventuell auch die rot eingekreiste Höhle auf der Karte auslassen. (hängt von deiner Ausrüstung/Klasse ab)",
  ["Mining route in The Hinterlands"] = "Bergbauroute im Hinterland",
  ["Players below level 60 should skip the 4 caves marked with red circles."] = "Spieler unter Stufe 60 sollten die 4 rot eingekreisten Höhlen auslassen.",
  ["Mining route in Tanaris"] = "Bergbauroute in Tanaris",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}"] = "Erze in diesen Gebieten: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}",
  ["Small Thorium Veins need Mining 245."] = "Kleine Thoriumadern erfordern Bergbau 245.",
  ["Un'Goro Crater"] = "Krater von Un'Goro",
  ["Blasted Lands"] = "Verwüstete Lande",
  ["Felwood"] = "Teufelswald",
  ["You will find 2-3 veins in the two caves marked with red circles on the map."] = "In den beiden rot eingekreisten Höhlen auf der Karte findest du 2-3 Adern.",
  ["Lower level players should probably skip the cave to the south. It really depends on your level, gear and class."] = "Niedrigstufige Spieler sollten die Höhle im Süden wahrscheinlich auslassen. Es hängt wirklich von deiner Stufe, Ausrüstung und Klasse ab.",
  ["Mining route in Un'Goro Crater"] = "Bergbauroute im Krater von Un'Goro",
  ["Both caves marked with red circles have a lot of mobs inside, so I only recommend this zone to level 60 players with good gear, or to Druids and Rogues with stealth."] = "In beiden rot eingekreisten Höhlen sind viele Gegner, daher empfehle ich dieses Gebiet nur Spielern der Stufe 60 mit guter Ausrüstung oder Druiden und Schurken mit Verstohlenheit.",
  ["It's really hard to navigate inside the Garrison Armory mine, so I included a small map. {b}Alliance{/b} players can't mine inside the Garrison Armory!"] = "In der Mine der Garnisonswaffenkammer findet man sich nur schwer zurecht, daher habe ich eine kleine Karte beigefügt. Spieler der {b}Allianz{/b} können in der Garnisonswaffenkammer nicht abbauen!",
  ["Mining route in the Blasted Lands"] = "Bergbauroute in den Verwüsteten Landen",
  ["There are usually 2 veins inside the cave marked with a red circle. It's worth going in because the cave is small and there aren't many mobs inside, and if you are high level, you can pass some of them without aggro."] = "In der rot eingekreisten Höhle gibt es meist 2 Adern. Es lohnt sich hineinzugehen, weil die Höhle klein ist und nicht viele Gegner drin sind, und wenn du hochstufig bist, kannst du an einigen vorbei, ohne Aggro zu ziehen.",
  ["I recommend skipping the other two caves at Jaedenar, especially Shadow Hold. (if you have stealth, they might be worth going into)"] = "Ich empfehle, die anderen beiden Höhlen bei Jaedenar auszulassen, vor allem die Schattenfeste. (mit Verstohlenheit könnten sie sich lohnen)",
  ["Mining route in Felwood"] = "Bergbauroute im Teufelswald",
  ["Ores in these zones: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}"] = "Erze in diesen Gebieten: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}",
  ["At 275 you can mine Rich Thorium Veins too."] = "Ab 275 kannst du auch reiche Thoriumadern abbauen.",
  ["Eastern Plaguelands"] = "Östliche Pestländer",
  ["Winterspring"] = "Winterquell",
  ["Burning Steppes"] = "Brennende Steppe",
  ["Almost the same as the previous Un'Goro route, but now it includes Rich Thorium Veins."] = "Fast dieselbe wie die vorherige Route in Un'Goro, aber jetzt mit reichen Thoriumadern.",
  ["Mining route with Rich Thorium Veins in Un'Goro Crater"] = "Bergbauroute mit reichen Thoriumadern im Krater von Un'Goro",
  ["The red line is full of level 57-58 elites, so if your gear is bad, you should probably skip that part unless you have stealth. With some practice you can usually get through and only pull a few of them."] = "Die rote Linie ist voller Elitegegner der Stufe 57-58. Wenn deine Ausrüstung schlecht ist, lässt du diesen Teil also besser aus, außer du hast Verstohlenheit. Mit etwas Übung kommst du meist durch und ziehst nur ein paar davon.",
  ["Mining route in the Eastern Plaguelands"] = "Bergbauroute in den Östlichen Pestländern",
  ["The mobs in this cave are not that hard, so most classes can clear it. (depends on your gear)"] = "Die Gegner in dieser Höhle sind nicht so stark, die meisten Klassen können sie räumen. (hängt von deiner Ausrüstung ab)",
  ["Most classes can get into at least the first part of the cave without pulling aggro. You can try going deeper depending on your gear."] = "Die meisten Klassen kommen zumindest in den ersten Teil der Höhle, ohne Aggro zu ziehen. Je nach Ausrüstung kannst du versuchen, tiefer hineinzugehen.",
  ["A lot of elites patrol this gorge, but you can usually pass most of them without pulling aggro. Sometimes you have to kill 1 or 2."] = "In dieser Schlucht patrouillieren viele Elitegegner, aber an den meisten kommst du normalerweise vorbei, ohne Aggro zu ziehen. Manchmal musst du 1 oder 2 töten.",
  ["I don't recommend this area for most players because it's hard to farm here without dying. It really depends on your class and how good you are at avoiding mobs."] = "Ich empfehle diese Gegend den meisten Spielern nicht, weil man hier kaum farmen kann, ohne zu sterben. Es hängt wirklich von deiner Klasse ab und davon, wie gut du Gegnern ausweichen kannst.",
  ["Mining route in Winterspring"] = "Bergbauroute in Winterquell",
  ["The two caves marked with red circles are full of level 50 mobs, so lower level players might want to skip them. (depends on your gear and level)"] = "Die beiden rot eingekreisten Höhlen sind voller Gegner der Stufe 50, niedrigstufige Spieler sollten sie also eventuell auslassen. (hängt von deiner Ausrüstung und Stufe ab)",
  ["Mining route in the Burning Steppes"] = "Bergbauroute in der Brennenden Steppe",
  ["This WoW Forever Herbalism leveling guide will show you the fastest way to level Herbalism from 1 to 300. You will also find a route map for every zone, every trainer location and where to train Herbalism past 75, 150 and 225."] = "Dieser WoW-Forever-Leitfaden für Kräuterkunde zeigt dir den schnellsten Weg, Kräuterkunde von 1 auf 300 zu leveln. Außerdem findest du eine Routenkarte für jedes Gebiet, alle Lehrer und erfährst, wo du Kräuterkunde über 75, 150 und 225 hinaus erlernen kannst.",
  ["Below you will find the Herbalism trainers by starting zone and capital city, and the best zones to pick herbs in for every skill range. Herbalism goes well with Alchemy because you can use the herbs you pick to make potions and elixirs, so check out my Forever Alchemy leveling guide if you want to level Alchemy. But keep in mind, this guide is made to level Herbalism as fast as possible, so sometimes the herbs you pick are not the best ones for Alchemy."] = "Unten findest du die Kräuterkundelehrer nach Startgebiet und Hauptstadt sowie die besten Gebiete zum Kräutersammeln für jeden Fertigkeitsbereich. Kräuterkunde passt gut zu Alchimie, weil du die gesammelten Kräuter für Tränke und Elixiere verwenden kannst. Schau dir also meinen Forever-Leitfaden für Alchimie an, wenn du Alchimie leveln willst. Denk aber daran, dass dieser Leitfaden darauf ausgelegt ist, Kräuterkunde so schnell wie möglich zu leveln, die gesammelten Kräuter sind also nicht immer die besten für Alchimie.",
  ["WoW Forever added a couple of new herbs, seeds and recipes. You can check them out here:"] = "WoW Forever hat ein paar neue Kräuter, Samen und Rezepte hinzugefügt. Du kannst sie dir hier ansehen:",
  ["Herbalism Trainer Locations"] = "Standorte der Kräuterkundelehrer",
  ["Every capital city has a Herbalism trainer. You can also ask a guard where the herbalist is, then it will be marked with a red flag on your map."] = "Jede Hauptstadt hat einen Kräuterkundelehrer. Du kannst auch eine Wache fragen, wo der Kräuterkundige ist, dann wird er mit einer roten Fahne auf deiner Karte markiert.",
  ["Undercity: {n:0:horde:Martha Alliestar}"] = "Unterstadt: {n:0:horde:Martha Alliestar}",
  ["Thunder Bluff: {n:0:horde:Komin Winterhoof}"] = "Donnerfels: {n:0:horde:Komin Winterhoof}",
  ["{n:0:horde:Zor'la} in the Valley of Trials (only up to 75) {n:0:horde:Mishiki} in Sen'jin Village"] = "{n:0:horde:Zor'la} im Tal der Prüfungen (nur bis 75) {n:0:horde:Mishiki} im Dorf Sen'jin",
  ["{n:0:horde:Garan Sunstrider} in Camp Narache (only up to 75) {n:0:horde:Komin Winterhoof} in Thunder Bluff"] = "{n:0:horde:Garan Sunstrider} im Camp Narache (nur bis 75) {n:0:horde:Komin Winterhoof} in Donnerfels",
  ["{n:0:horde:Florence Nightshade} in Deathknell (only up to 75) {n:0:horde:Faruza} in Brill"] = "{n:0:horde:Florence Nightshade} in Todesend (nur bis 75) {n:0:horde:Faruza} in Brill",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism. The trainers on the island are {n:0::Syriel Nightrain} in Valanaar and {n:0::Halassa Fernbreeze} in Shen'dar Village."] = "In Thendal Village, wo du startest, gibt es keinen Lehrer, aber du brauchst auch keinen. {q:93552::Harvesting Windstones} ist eine der ersten Quests, die du in Thendal Village bekommst. Wähl {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} als Belohnung, es bringt dir Kräuterkunde bei. Die Lehrer auf der Insel sind {n:0::Syriel Nightrain} in Valanaar und {n:0::Halassa Fernbreeze} in Shen'dar Village.",
  ["Stormwind City: {n:0:alliance:Tannysa}"] = "Sturmwind: {n:0:alliance:Tannysa}",
  ["Ironforge: {n:0:alliance:Reyna Stonebranch}"] = "Eisenschmiede: {n:0:alliance:Reyna Stonebranch}",
  ["{n:0:alliance:Nancy Songflower} (only up to 75) {n:0:alliance:Herbalist Pomeroy}"] = "{n:0:alliance:Nancy Songflower} (nur bis 75) {n:0:alliance:Herbalist Pomeroy}",
  ["{n:0:alliance:Emrys Flintbeard} (only up to 75) {n:0:alliance:Reyna Stonebranch} in Ironforge"] = "{n:0:alliance:Emrys Flintbeard} (nur bis 75) {n:0:alliance:Reyna Stonebranch} in Eisenschmiede",
  ["{n:0:alliance:Eleyna Duskbreeze} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Malorne Bladeleaf} in Dolanaar"] = "{n:0:alliance:Eleyna Duskbreeze} bei Aldrassil im Schattenhain (nur bis 75) {n:0:alliance:Malorne Bladeleaf} in Dolanaar",
  ["You can find every Herbalism trainer for Horde and Alliance on my WoW Forever Herbalism Trainers page."] = "Alle Kräuterkundelehrer für Horde und Allianz findest du auf meiner Seite zu den WoW-Forever-Kräuterkundelehrern.",
  ["Track Herbs on Your Minimap"] = "Kräuter auf deiner Minikarte aufspüren",
  ["You can only track one thing at a time, so {b}you can't track herbs and minerals together{/b}."] = "Du kannst immer nur eine Sache gleichzeitig aufspüren, {b}Kräuter und Mineralien zusammen aufzuspüren geht also nicht{/b}.",
  ["You learn {s:2383:inv_misc_flower_02:Find Herbs} together with Herbalism, but it's not turned on by default:"] = "Du lernst {s:2383:inv_misc_flower_02:Find Herbs} zusammen mit Kräuterkunde, aber es ist standardmäßig nicht aktiviert:",
  ["Click Find Herbs in the Herbalism box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "Klick im Kräuterkunde-Bereich auf Kräutersuche. {b}Ich empfehle, es auf deine Aktionsleiste zu ziehen, in die Nähe der Buffs, die du nach dem Tod benutzt.{/b} So wird es dir zur Gewohnheit und du vergisst es seltener.",
  ["The Find Herbs buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "Der Buff Kräutersuche erscheint neben deiner Minikarte. {b}Dein Aufspüren schaltet sich bei jedem Tod ab, vergiss also nicht, es wieder einzuschalten!{/b}",
  ["Herbalism Skill Bonuses"] = "Boni auf die Kräuterkundefertigkeit",
  ["You don't need these, but they help when you are stuck between two herbs. With +5 you can pick Kingsblood from 120 instead of 125, so you can move on earlier."] = "Du brauchst sie nicht, aber sie helfen, wenn du zwischen zwei Kräutern festhängst. Mit +5 kannst du Königsblut schon ab 120 statt 125 pflücken und früher weiterziehen.",
  ["Herbalism"] = "Kräuterkunde",
  ["A world drop, check the Auction House"] = "Ein Weltdrop, schau im Auktionshaus nach",
  ["Henry Stern in Razorfen Downs teaches the recipe, it {b}requires Cooking 175{/b}. Take the left path at the start of the instance and go all the way to the end, to the stables, knock down the walls and talk to him."] = "Henry Stern in den Hügeln der Klingenhauer lehrt das Rezept, es {b}erfordert Kochkunst 175{/b}. Nimm am Anfang der Instanz den linken Weg und geh ganz bis zum Ende zu den Ställen, reiß die Wände ein und sprich mit ihm.",
  ["can be very handy when you find a herb you can't pick yet and you are only a few points short. It will probably be pretty expensive early on because of the Goldthorn prices, but it's worth keeping a few with you while you level Herbalism."] = "kann sehr praktisch sein, wenn du ein Kraut findest, das du noch nicht pflücken kannst, und dir nur ein paar Punkte fehlen. Am Anfang ist es wegen der Golddornpreise wahrscheinlich ziemlich teuer, aber es lohnt sich, beim Leveln von Kräuterkunde ein paar dabeizuhaben.",
  ["Every starting zone is full of herbs, so it doesn't really matter which one you choose. The respawn rate is so fast that without a mount you often can't even finish a full lap, you just run around in circles and pick the herbs as you see them."] = "Jedes Startgebiet ist voller Kräuter, es spielt also keine große Rolle, welches du wählst. Die Respawnrate ist so hoch, dass du ohne Reittier oft nicht einmal eine volle Runde schaffst, du läufst einfach im Kreis und pflückst die Kräuter, wie du sie siehst.",
  ["Herbs in these zones: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}"] = "Kräuter in diesen Gebieten: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}",
  ["Earthroot requires Herbalism 15."] = "Erdwurzel erfordert Kräuterkunde 15.",
  ["Herbalism route in Durotar"] = "Kräuterkunderoute in Durotar",
  ["Herbalism route in Mulgore"] = "Kräuterkunderoute in Mulgore",
  ["Herbalism route in Tirisfal Glades"] = "Kräuterkunderoute in Tirisfal",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism."] = "{q:93552::Harvesting Windstones} ist eine der ersten Quests, die du in Thendal Village bekommst. Wähl {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} als Belohnung, es bringt dir Kräuterkunde bei.",
  ["Herbalism route on Zephras Isle"] = "Kräuterkunderoute auf Zephras Isle",
  ["Herbalism route in Elwynn Forest"] = "Kräuterkunderoute im Wald von Elwynn",
  ["Herbalism route in Dun Morogh"] = "Kräuterkunderoute in Dun Morogh",
  ["Herbalism route in Teldrassil"] = "Kräuterkunderoute in Teldrassil",
  ["Visit your trainer and learn Journeyman Herbalism, it requires Herbalism 50. The new Junior Herbalism Trainers in the starting areas won't teach you Journeyman Herbalism."] = "Besuche deinen Lehrer und erlerne Kräuterkunde (Geselle), es erfordert Kräuterkunde 50. Die neuen Junior-Kräuterkundelehrer in den Startgebieten bringen dir Kräuterkunde (Geselle) nicht bei.",
  ["Herbs in these zones: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}"] = "Kräuter in diesen Gebieten: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}",
  ["Stranglekelp requires Herbalism 85, so you can't pick it right away."] = "Würgetang erfordert Kräuterkunde 85, du kannst ihn also nicht sofort pflücken.",
  ["The respawn rate in the lower part of Silverpine Forest is fast enough that you can basically run in small circles in the marked area. I tested this without a mount, so with a mount it might be different, but then running up and down the main road to the loop should work fine as well."] = "Die Respawnrate im unteren Teil des Silberwalds ist so hoch, dass du im markierten Bereich praktisch in kleinen Kreisen laufen kannst. Ich habe das ohne Reittier getestet, mit Reittier ist es vielleicht anders, aber dann sollte es auch gut funktionieren, die Hauptstraße zur Schleife hoch und runter zu laufen.",
  ["Herbalism route in Silverpine Forest"] = "Kräuterkunderoute im Silberwald",
  ["A very easy route to follow, but there might be a bit fewer herbs than in Darkshore."] = "Eine sehr leicht zu folgende Route, aber vielleicht gibt es etwas weniger Kräuter als an der Dunkelküste.",
  ["Herbalism route in Loch Modan"] = "Kräuterkunderoute in Loch Modan",
  ["Darkshore has herbs everywhere. I used this loop, but you can also expand it to the upper part of the map. The respawn rate is fast, so you can do smaller circles in different areas. I just found this route pretty easy and chill to follow."] = "An der Dunkelküste gibt es überall Kräuter. Ich habe diese Schleife benutzt, du kannst sie aber auch auf den oberen Teil der Karte ausweiten. Die Respawnrate ist hoch, du kannst also kleinere Kreise in verschiedenen Bereichen laufen. Ich fand diese Route einfach ziemlich leicht und entspannt.",
  ["Herbalism route in Darkshore"] = "Kräuterkunderoute an der Dunkelküste",
  ["To train past 150, visit your trainer and learn Expert Herbalism, it requires Herbalism 125."] = "Um über 150 hinauszukommen, besuche deinen Lehrer und erlerne Kräuterkunde (Experte), es erfordert Kräuterkunde 125.",
  ["Herbs in these zones: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}"] = "Kräuter in diesen Gebieten: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}",
  ["Kingsblood requires Herbalism 125 and Liferoot 150, so you can't pick them right away."] = "Königsblut erfordert Kräuterkunde 125 und Lebenswurz 150, du kannst sie also nicht sofort pflücken.",
  ["Running this loop in Hillsbrad Foothills gives the herbs enough time to respawn, but I tested it without a mount, so with a mount it might be different."] = "Wenn du diese Schleife im Vorgebirge des Hügellands läufst, haben die Kräuter genug Zeit zum Respawnen, aber ich habe sie ohne Reittier getestet, mit Reittier ist es vielleicht anders.",
  ["Herbalism route in Hillsbrad Foothills"] = "Kräuterkunderoute im Vorgebirge des Hügellands",
  ["All three areas are good here:"] = "Alle drei Bereiche sind hier gut:",
  ["The mobs here are only around level 14-15, so this is the lowest level area where you can safely farm these herbs."] = "Die Gegner hier sind nur etwa Stufe 14-15, das ist also der niedrigstufigste Bereich, in dem du diese Kräuter sicher farmen kannst.",
  ["A good alternative if someone is already farming the first area. The mobs are higher level here, around 25."] = "Eine gute Alternative, wenn schon jemand den ersten Bereich farmt. Die Gegner sind hier höherstufig, etwa 25.",
  ["This area is usually pretty crowded and full of mobs. {b}I only recommend it if you are over 125 already{/b}, because there is more Kingsblood here."] = "Dieser Bereich ist meist ziemlich voll und voller Gegner. {b}Ich empfehle ihn nur, wenn du schon über 125 bist{/b}, weil es hier mehr Königsblut gibt.",
  ["Herbalism route in Stonetalon Mountains"] = "Kräuterkunderoute im Steinkrallengebirge",
  ["From this point the guide follows the standard Classic Herbalism routes. The beta cap was 30, so I couldn't test the higher level routes. I'll revise this section once I level my character higher on live, but the main change is the herb respawn rate, so most routes should work."] = "Ab hier folgt der Leitfaden den normalen Classic-Kräuterkunderouten. Die Stufengrenze in der Beta lag bei 30, daher konnte ich die höherstufigen Routen nicht testen. Ich überarbeite diesen Abschnitt, sobald ich meinen Charakter auf dem Live-Server höher gelevelt habe, aber die wichtigste Änderung ist die Respawnrate der Kräuter, die meisten Routen sollten also funktionieren.",
  ["Herbs in these zones: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}"] = "Kräuter in diesen Gebieten: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}",
  ["Khadgar's Whisker requires Herbalism 185, so you can't pick it right away."] = "Khadgars Schnurrbart erfordert Kräuterkunde 185, du kannst ihn also nicht sofort pflücken.",
  ["Stranglethorn Vale"] = "Schlingendorntal",
  ["Herbalism route in Stranglethorn Vale"] = "Kräuterkunderoute im Schlingendorntal",
  ["Herbalism route in Arathi Highlands"] = "Kräuterkunderoute im Arathihochland",
  ["{b}Learn Artisan Herbalism before you leave for these zones{/b}, it requires Herbalism 200. There is no trainer in Tanaris or Searing Gorge, so if you skip it, you have to fly back at 225."] = "{b}Erlerne Kräuterkunde (Fachmann), bevor du in diese Gebiete aufbrichst{/b}, es erfordert Kräuterkunde 200. In Tanaris und der Sengenden Schlucht gibt es keinen Lehrer, wenn du es also auslässt, musst du bei 225 zurückfliegen.",
  ["Herbs in these zones: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}"] = "Kräuter in diesen Gebieten: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}",
  ["Searing Gorge"] = "Sengende Schlucht",
  ["Herbalism route in Tanaris"] = "Kräuterkunderoute in Tanaris",
  ["Herbalism route in Searing Gorge"] = "Kräuterkunderoute in der Sengenden Schlucht",
  ["Herbs in The Hinterlands: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}"] = "Kräuter im Hinterland: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}",
  ["I marked a cave with a red X, there are a lot of Ghost Mushrooms in the cave, but you can only pick them with Herbalism 245."] = "Ich habe eine Höhle mit einem roten X markiert. In der Höhle gibt es viele Geisterpilze, aber die kannst du erst mit Kräuterkunde 245 pflücken.",
  ["Herbalism route in The Hinterlands"] = "Kräuterkunderoute im Hinterland",
  ["Herbs in Felwood: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}"] = "Kräuter im Teufelswald: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}",
  ["Herbalism route in Felwood"] = "Kräuterkunderoute im Teufelswald",
  ["This WoW Forever Skinning leveling guide will show you the fastest way to level Skinning from 1 to 300. You will also find every trainer location and the best places to skin for each skill range."] = "Dieser WoW-Forever-Leitfaden für Kürschnerei zeigt dir den schnellsten Weg, Kürschnerei von 1 auf 300 zu leveln. Außerdem findest du alle Lehrer und die besten Orte zum Kürschnern für jeden Fertigkeitsbereich.",
  ["This guide is aimed at higher level players who want to switch their profession, but it's good for lower level players too. Leveling Skinning is easy but really boring, you will have to run around and skin hundreds of mobs. Skinning goes well with Leatherworking because you can use the leather you skin, so check out my Forever Leatherworking leveling guide if you want to level Leatherworking."] = "Dieser Leitfaden richtet sich an höherstufige Spieler, die ihren Beruf wechseln wollen, ist aber auch für niedrigstufige Spieler gut. Kürschnerei zu leveln ist einfach, aber wirklich langweilig, du musst herumlaufen und Hunderte von Gegnern häuten. Kürschnerei passt gut zu Lederverarbeitung, weil du das gekürschnerte Leder verwenden kannst. Schau dir also meinen Forever-Leitfaden für Lederverarbeitung an, wenn du Lederverarbeitung leveln willst.",
  ["Skinning Trainer Locations"] = "Standorte der Kürschnereilehrer",
  ["Every capital city has a Skinning trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Jede Hauptstadt hat einen Kürschnereilehrer. Du kannst auch eine Wache fragen, dann wird er mit einer roten Fahne auf deiner Karte markiert.",
  ["Undercity: {n:0:horde:Killian Hagey}"] = "Unterstadt: {n:0:horde:Killian Hagey}",
  ["Thunder Bluff: {n:0:horde:Mooranta}"] = "Donnerfels: {n:0:horde:Mooranta}",
  ["{n:0:horde:Kagil} in the Valley of Trials (only up to 75) {n:0:horde:Thuwd} in Orgrimmar"] = "{n:0:horde:Kagil} im Tal der Prüfungen (nur bis 75) {n:0:horde:Thuwd} in Orgrimmar",
  ["{n:0:horde:Nawka Wildsong} in Camp Narache (only up to 75) {n:0:horde:Yonn Deepcut} in Bloodhoof Village"] = "{n:0:horde:Nawka Wildsong} im Camp Narache (nur bis 75) {n:0:horde:Yonn Deepcut} im Dorf der Bluthufe",
  ["{n:0:horde:Margaret Weaver} in Deathknell (only up to 75) {n:0:horde:Rand Rhobart} in Tirisfal Glades"] = "{n:0:horde:Margaret Weaver} in Todesend (nur bis 75) {n:0:horde:Rand Rhobart} in Tirisfal",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} as your reward, it teaches you Skinning. The trainers on the island are {n:0::Ishlee Breezewhisper} in Valanaar and {n:0::Mendalass Tattermend} in Shen'dar Village."] = "In Thendal Village, wo du startest, gibt es keinen Lehrer, aber du brauchst auch keinen. {q:93552::Harvesting Windstones} ist eine der ersten Quests, die du in Thendal Village bekommst. Wähl {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} als Belohnung, es bringt dir Kürschnerei bei. Die Lehrer auf der Insel sind {n:0::Ishlee Breezewhisper} in Valanaar und {n:0::Mendalass Tattermend} in Shen'dar Village.",
  ["Stormwind City: {n:0:alliance:Maris Granger}"] = "Sturmwind: {n:0:alliance:Maris Granger}",
  ["Ironforge: {n:0:alliance:Balthus Stoneflayer}"] = "Eisenschmiede: {n:0:alliance:Balthus Stoneflayer}",
  ["{n:0:alliance:Riley Peltskinner} in Northshire Valley (only up to 75) {n:0:alliance:Helene Peltskinner} in Goldshire"] = "{n:0:alliance:Riley Peltskinner} im Nordhaintal (nur bis 75) {n:0:alliance:Helene Peltskinner} in Goldhain",
  ["{n:0:alliance:Brighid Stormflayer} (only up to 75) {n:0:alliance:Balthus Stoneflayer} in Ironforge"] = "{n:0:alliance:Brighid Stormflayer} (nur bis 75) {n:0:alliance:Balthus Stoneflayer} in Eisenschmiede",
  ["{n:0:alliance:Terunne Bearshaper} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Radnaal Maneweaver} in Teldrassil"] = "{n:0:alliance:Terunne Bearshaper} bei Aldrassil im Schattenhain (nur bis 75) {n:0:alliance:Radnaal Maneweaver} in Teldrassil",
  ["You can find every Skinning trainer for Horde and Alliance on my WoW Forever Skinning Trainers page."] = "Alle Kürschnereilehrer für Horde und Allianz findest du auf meiner Seite zu den WoW-Forever-Kürschnereilehrern.",
  ["Skinning Skill Requirements"] = "Fertigkeitsanforderungen beim Kürschnern",
  ["You need 5 times the mob's level in Skinning to skin it, so a level 30 mob needs Skinning 150. Below level 20 it's less, if you follow the guide you don't have to worry about this."] = "Um einen Gegner zu häuten, brauchst du in Kürschnerei das 5-Fache seiner Stufe, ein Gegner der Stufe 30 erfordert also Kürschnerei 150. Unter Stufe 20 ist es weniger, wenn du dem Leitfaden folgst, musst du dir darüber keine Gedanken machen.",
  ["Mob level"] = "Stufe des Gegners",
  ["Skinning needed"] = "Benötigte Kürschnerei",
  ["10 for a level 11 mob, 10 more for every level (level 15 needs 50, level 19 needs 90)"] = "10 für einen Gegner der Stufe 11, 10 mehr pro Stufe (Stufe 15 erfordert 50, Stufe 19 erfordert 90)",
  ["20 and up"] = "20 und höher",
  ["5 times the level"] = "Das 5-Fache der Stufe",
  ["If you enchant your gloves with {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}, you can skin mobs 1 level higher than normal."] = "Wenn du deine Handschuhe mit {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning} verzauberst, kannst du Gegner häuten, die 1 Stufe höher sind als normal.",
  ["Horde players can also pick the {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 Skinning) as a reward from Unwelcome Guests in The Barrens."] = "Spieler der Horde können auch das {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 Kürschnerei) als Belohnung von Unwelcome Guests im Brachland wählen.",
  ["In WoW Forever you can skin the mobs in the starting areas, and they give skill points all the way up to 75."] = "In WoW Forever kannst du die Gegner in den Startgebieten häuten, und sie geben bis 75 Fertigkeitspunkte.",
  ["{b}Any starting zone is good{/b} for this. If you are leveling a new character, you can skin any mob in your starting zone, so you don't need a recommendation until around level 10, when you leave the zone. The two places below are for players who already have a higher level character and want to catch up on Skinning. A lot of players will be leveling new characters there, so there is always something to skin."] = "{b}Jedes Startgebiet ist dafür gut{/b}. Wenn du einen neuen Charakter levelst, kannst du jeden Gegner in deinem Startgebiet häuten, du brauchst also erst um Stufe 10 eine Empfehlung, wenn du das Gebiet verlässt. Die beiden Orte unten sind für Spieler, die schon einen höherstufigen Charakter haben und Kürschnerei nachholen wollen. Dort leveln viele Spieler neue Charaktere, es gibt also immer etwas zu häuten.",
  ["{b}Don't forget to buy a {i:7005:inv_weapon_shortblade_01:Skinning Knife}!{/b} The Leatherworking Supply vendors near your trainer and most General Goods vendors sell it. You don't have to equip it, but you can't skin without one in your bags."] = "{b}Vergiss nicht, ein {i:7005:inv_weapon_shortblade_01:Skinning Knife} zu kaufen!{/b} Die Händler für Lederverarbeitungsbedarf in der Nähe deines Lehrers und die meisten Gemischtwarenhändler verkaufen es. Du musst es nicht anlegen, aber ohne eins in deinen Taschen kannst du nicht kürschnern.",
  ["Skin the {n:3098::Mottled Boars} in the Valley of Trials in Durotar."] = "Häute die {n:3098::Mottled Boars} im Tal der Prüfungen in Durotar.",
  ["{b}Mob level:{/b} 1-2"] = "{b}Stufe der Gegner:{/b} 1-2",
  ["The Mottled Boars in the Valley of Trials in Durotar"] = "Die gesprenkelten Eber im Tal der Prüfungen in Durotar",
  ["Skin the {n:299::Young Wolves} and {n:69::Timber Wolves} in Northshire Valley in Elwynn Forest."] = "Häute die {n:299::Young Wolves} und {n:69::Timber Wolves} im Nordhaintal im Wald von Elwynn.",
  ["The wolves in Northshire Valley in Elwynn Forest"] = "Die Wölfe im Nordhaintal im Wald von Elwynn",
  ["Visit your trainer and learn Journeyman Skinning if you haven't yet, it requires Skinning 50. The new Junior Skinning Trainers in the starting areas won't teach you Journeyman Skinning."] = "Besuche deinen Lehrer und erlerne Kürschnerei (Geselle), falls noch nicht geschehen, es erfordert Kürschnerei 50. Die neuen Junior-Kürschnereilehrer in den Startgebieten bringen dir Kürschnerei (Geselle) nicht bei.",
  ["To train past 150, visit your trainer again and learn Expert Skinning when you reach 125."] = "Um über 150 hinauszukommen, besuche deinen Lehrer erneut und erlerne Kürschnerei (Experte), wenn du 125 erreichst.",
  ["Kill and skin {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}."] = "Töte und häute {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}.",
  ["Go to the small raptor camp just west of Northwatch Hold. Skin the level 16-17 ones until 80, from 80 you can skin the level 18 ones too. Stay here until 150, the last 10 points are green but the respawn is fast."] = "Geh zum kleinen Raptorenlager direkt westlich der Feste Nordwacht. Häute bis 80 die der Stufe 16-17, ab 80 kannst du auch die der Stufe 18 häuten. Bleib hier bis 150, die letzten 10 Punkte sind grün, aber der Respawn ist schnell.",
  ["{b}Mob level:{/b} 16-18"] = "{b}Stufe der Gegner:{/b} 16-18",
  ["The Sunscale Scytheclaws west of Northwatch Hold in the Barrens"] = "Die Sonnenschuppen-Sichelklauen westlich der Feste Nordwacht im Brachland",
  ["Kill and skin {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}."] = "Töte und häute {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}.",
  ["{n:1693::Loch Crocolisk} are also skinnable, make sure to pull them when you get to the shore."] = "{n:1693::Loch Crocolisk} lassen sich ebenfalls häuten, zieh sie unbedingt mit, wenn du ans Ufer kommst.",
  ["Stay here until around 125, then head north to the Wetlands, it is on the way to Hillsbrad."] = "Bleib hier bis etwa 125, dann geh nach Norden ins Sumpfland, es liegt auf dem Weg zum Hügelland.",
  ["{b}Mob level:{/b} 16-17"] = "{b}Stufe der Gegner:{/b} 16-17",
  ["Skinning spot in Loch Modan"] = "Kürschnereiort in Loch Modan",
  ["125-150 Wetlands"] = "125-150 Sumpfland",
  ["Kill and skin {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}."] = "Töte und häute {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}.",
  ["There are always a few of them at Whelgar's Excavation Site, so you never run out of mobs to kill."] = "An Whelgars Ausgrabungsstätte sind immer ein paar davon, dir gehen also nie die Gegner aus.",
  ["{b}Mob level:{/b} 25-27"] = "{b}Stufe der Gegner:{/b} 25-27",
  ["Whelgar's Excavation Site in the Wetlands"] = "Whelgars Ausgrabungsstätte im Sumpfland",
  ["From 150, go to the Foothill Caverns in Hillsbrad Foothills, the yeti cave on the border of Alterac Mountains, or to the Rotting Orchard in Duskwood."] = "Ab 150 geh zu den Foothill Caverns im Vorgebirge des Hügellands, der Yetihöhle an der Grenze zum Alteracgebirge, oder zum Rotting Orchard im Dämmerwald.",
  ["Duskwood"] = "Dämmerwald",
  ["Both factions can get there, Horde from Tarren Mill and Alliance from Southshore."] = "Beide Fraktionen kommen dorthin, die Horde von Tarrens Mühle und die Allianz von Süderstade.",
  ["Kill and skin {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}."] = "Töte und häute {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}.",
  ["The yetis respawn so fast that you can stay inside the cave the whole time."] = "Die Yetis respawnen so schnell, dass du die ganze Zeit in der Höhle bleiben kannst.",
  ["{b}Mob level:{/b} 30-32"] = "{b}Stufe der Gegner:{/b} 30-32",
  ["The Foothill Caverns in Hillsbrad Foothills"] = "Die Foothill Caverns im Vorgebirge des Hügellands",
  ["Duskwood is an Alliance zone, but Grom'gol is close, so Horde players can get there too."] = "Der Dämmerwald ist ein Allianzgebiet, aber Grom'gol ist nah, Spieler der Horde kommen also auch hin.",
  ["Kill and skin {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}."] = "Töte und häute {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}.",
  ["Start at the area marked with 1, clear the mobs outside and inside Roland's Doom cave, then go to the Rotting Orchard until the mobs respawn."] = "Fang im mit 1 markierten Bereich an, räum die Gegner draußen und in der Höhle Roland's Doom, dann geh zum Rotting Orchard, bis die Gegner respawnen.",
  ["{b}Mob level:{/b} 26-29"] = "{b}Stufe der Gegner:{/b} 26-29",
  ["Roland's Doom and the Rotting Orchard in Duskwood"] = "Roland's Doom und der Rotting Orchard im Dämmerwald",
  ["Visit your trainer and learn Artisan Skinning, it requires Skinning 200."] = "Besuche deinen Lehrer und erlerne Kürschnerei (Fachmann), es erfordert Kürschnerei 200.",
  ["Mount up and go to the yeti cave at Feral Scar Vale in the south of Feralas. Both factions can get there, Horde from Camp Mojache and Alliance from Feathermoon Stronghold."] = "Steig auf dein Reittier und reite zur Yetihöhle im Feral Scar Vale im Süden von Feralas. Beide Fraktionen kommen dorthin, die Horde vom Camp Mojache und die Allianz von der Mondfederfeste.",
  ["Kill and skin {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}."] = "Töte und häute {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}.",
  ["{b}Mob level:{/b} 43-46"] = "{b}Stufe der Gegner:{/b} 43-46",
  ["The yeti cave at Feral Scar Vale in Feralas"] = "Die Yetihöhle im Feral Scar Vale in Feralas",
  ["From 280, fly to Marshal's Refuge and skin the dinosaurs in the western part of Un'Goro Crater."] = "Ab 280 flieg nach Marschalls Zuflucht und häute die Dinosaurier im westlichen Teil des Kraters von Un'Goro.",
  ["Kill and skin {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}."] = "Töte und häute {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}.",
  ["{b}Mob level:{/b} 50-55"] = "{b}Stufe der Gegner:{/b} 50-55",
  ["The dinosaur area in the west of Un'Goro Crater"] = "Das Dinosauriergebiet im Westen des Kraters von Un'Goro",
  ["This WoW Forever Fishing and Cooking leveling guide will show you the fastest way to level Fishing and Cooking together from 1 to 300."] = "Dieser WoW-Forever-Leitfaden für Angeln und Kochkunst zeigt dir den schnellsten Weg, Angeln und Kochkunst gemeinsam von 1 auf 300 zu leveln.",
  ["Leveling Fishing takes a long time, so it's best to level these two together, because every fish you catch is also a Cooking recipe and your Cooking goes up for free while you fish. You will still need a lot of patience because you have to catch a lot of fish to get from start to finish. If you only want one of them, use my Fishing guide or my Cooking guide instead."] = "Angeln zu leveln dauert lange, daher levelst du die beiden am besten zusammen, denn jeder gefangene Fisch ist auch ein Kochrezept und deine Kochkunst steigt beim Angeln gratis mit. Du brauchst trotzdem viel Geduld, weil du von Anfang bis Ende viele Fische fangen musst. Wenn du nur einen der beiden willst, nimm stattdessen meinen Angel- oder meinen Kochkunstleitfaden.",
  ["Level Fishing to 75"] = "Angeln auf 75 leveln",
  ["If you can choose, {b}level Fishing in Mulgore{/b}, because everything is close together there. {n:0::Harn Longcast} in Bloodhoof Village sells both recipes and the pole, and the Fishing trainer stands at Stonebull Lake. Thunder Bluff, where you fish after 75, is right next to it."] = "Wenn du die Wahl hast, {b}level Angeln in Mulgore{/b}, weil dort alles nah beieinander liegt. {n:0::Harn Longcast} im Dorf der Bluthufe verkauft beide Rezepte und die Angel, und der Angellehrer steht am Steinbullensee. Donnerfels, wo du nach 75 angelst, liegt direkt daneben.",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lau'Tiki} on the coast south of Sen'jin Village."] = "Wenn du Angeln noch nicht erlernt hast, lern es bei {n:0::Lau'Tiki} an der Küste südlich des Dorfs Sen'jin.",
  ["Buy {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} from {n:0::Zansoa} in Sen'jin Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Kauf {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} bei {n:0::Zansoa} im Dorf Sen'jin. Kauf dort auch eine {i:6256:inv_fishingpole_02:Fishing Pole} und einen {i:6529:inv_misc_orb_03:Shiny Bauble}. (Kauf jeden {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, den du siehst, und heb ihn für später auf.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish on the coast next to {n:0::Lau'Tiki}, south of Sen'jin Village, until your Fishing skill reaches 75. Almost everything you catch there is {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, about 70 of them."] = "Leg deine Angel an, bring einen {i:6529:inv_misc_orb_03:Shiny Bauble} an und angle an der Küste neben {n:0::Lau'Tiki} südlich des Dorfs Sen'jin, bis deine Angelfertigkeit 75 erreicht. Fast alles, was du dort fängst, ist {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, etwa 70 Stück.",
  ["Learn Journeyman Fishing from {n:0::Lau'Tiki}, it requires level 10."] = "Erlerne Angeln (Geselle) bei {n:0::Lau'Tiki}, es erfordert Stufe 10.",
  ["The coast south of Sen'jin Village in Durotar, where to fish from 1 to 75"] = "Die Küste südlich des Dorfs Sen'jin in Durotar, wo du von 1 bis 75 angelst",
  ["If you haven't learned Fishing yet, learn it from {n:0::Uthan Stillwater} at Stonebull Lake."] = "Wenn du Angeln noch nicht erlernt hast, lern es bei {n:0::Uthan Stillwater} am Steinbullensee.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Harn Longcast} in Bloodhoof Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Kauf {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} und {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} bei {n:0::Harn Longcast} im Dorf der Bluthufe. Kauf dort auch eine {i:6256:inv_fishingpole_02:Fishing Pole} und einen {i:6529:inv_misc_orb_03:Shiny Bauble}. (Kauf jeden {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, den du siehst, und heb ihn für später auf.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Stonebull Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Leg deine Angel an, bring einen {i:6529:inv_misc_orb_03:Shiny Bauble} an und angle im Steinbullensee, bis deine Angelfertigkeit 75 erreicht. Du fängst etwa 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} und 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Uthan Stillwater}, it requires level 10."] = "Erlerne Angeln (Geselle) bei {n:0::Uthan Stillwater}, es erfordert Stufe 10.",
  ["Stonebull Lake around Bloodhoof Village in Mulgore, where to fish from 1 to 75"] = "Der Steinbullensee rund um das Dorf der Bluthufe in Mulgore, wo du von 1 bis 75 angelst",
  ["If you haven't learned Fishing yet, learn it from {n:0::Clyde Kellen} at Brightwater Lake."] = "Wenn du Angeln noch nicht erlernt hast, lern es bei {n:0::Clyde Kellen} am Brightwater Lake.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Martine Tramblay} at the Death's Watch Waystation, south-east of Brill. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Kauf {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} bei {n:0::Martine Tramblay} an der Death's Watch Waystation südöstlich von Brill. Kauf dort auch eine {i:6256:inv_fishingpole_02:Fishing Pole} und einen {i:6529:inv_misc_orb_03:Shiny Bauble}. (Kauf jeden {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, den du siehst, und heb ihn für später auf.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Brightwater Lake until your Fishing skill reaches 75. You will catch about 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, plus some {i:6299:inv_misc_fish_28:Sickly Looking Fish} and junk."] = "Leg deine Angel an, bring einen {i:6529:inv_misc_orb_03:Shiny Bauble} an und angle im Brightwater Lake, bis deine Angelfertigkeit 75 erreicht. Du fängst etwa 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} und 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, dazu ein paar {i:6299:inv_misc_fish_28:Sickly Looking Fish} und Kram.",
  ["Learn Journeyman Fishing from {n:0::Clyde Kellen}, it requires level 10."] = "Erlerne Angeln (Geselle) bei {n:0::Clyde Kellen}, es erfordert Stufe 10.",
  ["Brightwater Lake east of Brill in Tirisfal Glades, where to fish from 1 to 75"] = "Der Brightwater Lake östlich von Brill in Tirisfal, wo du von 1 bis 75 angelst",
  ["If you haven't learned Fishing yet, learn it from {n:0::Fenn Fairweather} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar."] = "Wenn du Angeln noch nicht erlernt hast, lern es bei {n:0::Fenn Fairweather} in Shen'dar Village oder {n:0::Baelann Swiftcurrent} in Valanaar.",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Belandiel Farflight} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Kauf eine {i:6256:inv_fishingpole_02:Fishing Pole} und einen {i:6529:inv_misc_orb_03:Shiny Bauble} bei {n:0::Belandiel Farflight} in Shen'dar Village oder {n:0::Baelann Swiftcurrent} in Valanaar. (Kauf jeden {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, den du siehst, und heb ihn für später auf.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in any lake or river on Zephras Isle until your Fishing skill reaches 75, for example next to the Fishing trainers in Shen'dar Village and Valanaar. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Keep all the fish you catch."] = "Leg deine Angel an, bring einen {i:6529:inv_misc_orb_03:Shiny Bauble} an und angle in einem beliebigen See oder Fluss auf Zephras Isle, bis deine Angelfertigkeit 75 erreicht, zum Beispiel neben den Angellehrern in Shen'dar Village und Valanaar. Du fängst etwa 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} und 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Behalte alle Fische, die du fängst.",
  ["Learn Journeyman Fishing from {n:0::Fenn Fairweather} or {n:0::Baelann Swiftcurrent}, it requires level 10."] = "Erlerne Angeln (Geselle) bei {n:0::Fenn Fairweather} oder {n:0::Baelann Swiftcurrent}, es erfordert Stufe 10.",
  ["When you get to Thunder Bluff, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Sewa Mistrunner} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Naal Mistrunner}. They stand next to each other."] = "Wenn du in Donnerfels ankommst, kauf {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} bei {n:0::Sewa Mistrunner} und {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} bei {n:0::Naal Mistrunner}. Sie stehen nebeneinander.",
  ["The water at Shen'dar Village and Valanaar on Zephras Isle, where to fish from 1 to 75"] = "Das Wasser bei Shen'dar Village und Valanaar auf Zephras Isle, wo du von 1 bis 75 angelst",
  ["If you can choose, {b}level Fishing in Elwynn Forest{/b}, because everything is close together there. {n:0::Tharynn Bouden} in Goldshire sells both recipes and the pole, and the Fishing trainer stands at Crystal Lake. Stormwind City, where you fish after 75, is right next to it."] = "Wenn du die Wahl hast, {b}level Angeln im Wald von Elwynn{/b}, weil dort alles nah beieinander liegt. {n:0::Tharynn Bouden} in Goldhain verkauft beide Rezepte und die Angel, und der Angellehrer steht am Kristallsee. Sturmwind, wo du nach 75 angelst, liegt direkt daneben.",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lee Brown} at Crystal Lake."] = "Wenn du Angeln noch nicht erlernt hast, lern es bei {n:0::Lee Brown} am Kristallsee.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Kauf {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} und {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} bei {n:0::Tharynn Bouden} in Goldhain. Kauf dort auch eine {i:6256:inv_fishingpole_02:Fishing Pole} und einen {i:6529:inv_misc_orb_03:Shiny Bauble}. (Kauf jeden {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, den du siehst, und heb ihn für später auf.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Crystal Lake, east of Goldshire, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Leg deine Angel an, bring einen {i:6529:inv_misc_orb_03:Shiny Bauble} an und angle im Kristallsee östlich von Goldhain, bis deine Angelfertigkeit 75 erreicht. Du fängst etwa 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} und 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Lee Brown}, it requires level 10."] = "Erlerne Angeln (Geselle) bei {n:0::Lee Brown}, es erfordert Stufe 10.",
  ["Crystal Lake east of Goldshire in Elwynn Forest, where to fish from 1 to 75"] = "Der Kristallsee östlich von Goldhain im Wald von Elwynn, wo du von 1 bis 75 angelst",
  ["If you haven't learned Fishing yet, learn it from {n:0::Paxton Ganter} at Iceflow Lake."] = "Wenn du Angeln noch nicht erlernt hast, lern es bei {n:0::Paxton Ganter} am Iceflow Lake.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Gretta Ganter} at Iceflow Lake. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Kauf {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} bei {n:0::Gretta Ganter} am Iceflow Lake. Kauf dort auch eine {i:6256:inv_fishingpole_02:Fishing Pole} und einen {i:6529:inv_misc_orb_03:Shiny Bauble}. (Kauf jeden {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, den du siehst, und heb ihn für später auf.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Iceflow Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Leg deine Angel an, bring einen {i:6529:inv_misc_orb_03:Shiny Bauble} an und angle im Iceflow Lake, bis deine Angelfertigkeit 75 erreicht. Du fängst etwa 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} und 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Paxton Ganter}, it requires level 10."] = "Erlerne Angeln (Geselle) bei {n:0::Paxton Ganter}, es erfordert Stufe 10.",
  ["Iceflow Lake in Dun Morogh, where to fish from 1 to 75"] = "Der Iceflow Lake in Dun Morogh, wo du von 1 bis 75 angelst",
  ["Learn Fishing from {n:0::Astaia} in Darnassus. There is no Fishing trainer in Dolanaar."] = "Erlerne Angeln bei {n:0::Astaia} in Darnassus. In Dolanaar gibt es keinen Angellehrer.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Nyoma} in Dolanaar."] = "Kauf {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} und {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} bei {n:0::Nyoma} in Dolanaar.",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Narret Shadowgrove} in Dolanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Kauf eine {i:6256:inv_fishingpole_02:Fishing Pole} und einen {i:6529:inv_misc_orb_03:Shiny Bauble} bei {n:0::Narret Shadowgrove} in Dolanaar. (Kauf jeden {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, den du siehst, und heb ihn für später auf.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Lake Al'Ameth, south of Dolanaar, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Leg deine Angel an, bring einen {i:6529:inv_misc_orb_03:Shiny Bauble} an und angle im See Al'Ameth südlich von Dolanaar, bis deine Angelfertigkeit 75 erreicht. Du fängst etwa 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} und 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Astaia} in Darnassus, it requires level 10."] = "Erlerne Angeln (Geselle) bei {n:0::Astaia} in Darnassus, es erfordert Stufe 10.",
  ["Lake Al'Ameth south of Dolanaar in Teldrassil, where to fish from 1 to 75"] = "Der See Al'Ameth südlich von Dolanaar in Teldrassil, wo du von 1 bis 75 angelst",
  ["When you get to Stormwind City, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire, right outside the city."] = "Wenn du in Sturmwind ankommst, kauf {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} und {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} bei {n:0::Tharynn Bouden} in Goldhain, direkt vor der Stadt.",
  ["Fishing (75-130) and Cooking (1-100)"] = "Angeln (75-130) und Kochkunst (1-100)",
  ["Fishing"] = "Angeln",
  ["Fish in the capital city closest to you until your Fishing skill reaches 130. From 75 no fish gets away in any of them. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Angle in der Hauptstadt, die dir am nächsten ist, bis deine Angelfertigkeit 130 erreicht. Ab 75 entkommt dir in keiner davon ein Fisch. Du solltest etwa 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} und 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} fangen.",
  ["{b}Thunder Bluff:{/b} the pond near the Auction House."] = "{b}Donnerfels:{/b} der Teich in der Nähe des Auktionshauses.",
  ["{b}Undercity:{/b} the canals. About a third of what you catch here is junk, so you get fewer fish."] = "{b}Unterstadt:{/b} die Kanäle. Etwa ein Drittel deines Fangs ist hier Kram, du bekommst also weniger Fische.",
  ["{b}Orgrimmar:{/b} the pond in the Valley of Honor, where the Fishing trainer stands."] = "{b}Orgrimmar:{/b} der Teich im Tal der Ehre, wo der Angellehrer steht.",
  ["Recipes to buy"] = "Rezepte zum Kaufen",
  ["Buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Ronald Burch} in Undercity, you need it in the next part."] = "Kauf {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} bei {n:0::Naal Mistrunner} in Donnerfels oder {n:0::Ronald Burch} in Unterstadt, du brauchst es im nächsten Teil.",
  ["If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Lizbeth Cromwell} in Undercity."] = "Wenn du {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} noch nicht hast, kauf es bei {n:0::Naal Mistrunner} in Donnerfels oder {n:0::Lizbeth Cromwell} in Unterstadt.",
  ["Nobody sells them in Orgrimmar, so buy them on the Auction House or in Thunder Bluff."] = "In Orgrimmar verkauft sie niemand, kauf sie also im Auktionshaus oder in Donnerfels.",
  ["Cooking"] = "Kochkunst",
  ["If you haven't learned Cooking yet, learn it from {n:0::Aska Mistrunner} in Thunder Bluff, {n:0::Eunice Burch} in Undercity or {n:0::Zamja} in Orgrimmar. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. If you caught {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel} in your starting zone, learn {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} and cook them into {s:7752:inv_misc_fish_24:Slitherskin Mackerel} instead. This should take your Cooking skill to 50."] = "Wenn du Kochkunst noch nicht erlernt hast, lern es bei {n:0::Aska Mistrunner} in Donnerfels, {n:0::Eunice Burch} in Unterstadt oder {n:0::Zamja} in Orgrimmar. Lern dann {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} und koch alle deine {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} zu {s:7751:inv_misc_fish_07:Brilliant Smallfish}. Wenn du in deinem Startgebiet {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel} gefangen hast, lern stattdessen {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} und koch sie zu {s:7752:inv_misc_fish_24:Slitherskin Mackerel}. Damit sollte deine Kochkunst 50 erreichen.",
  ["If you are a few points short of 50, catch and cook a few more."] = "Wenn dir ein paar Punkte bis 50 fehlen, fang und koch noch ein paar mehr.",
  ["Learn Journeyman Cooking from the same trainer. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "Erlerne Kochkunst (Geselle) beim selben Lehrer. Lern dann {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} und koch alle deine {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} zu {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Deine Kochkunst sollte über 100 steigen.",
  ["Don't worry if you don't reach 100 Cooking with Longjaw Mud Snapper, you will catch more Raw Longjaw Mud Snapper later."] = "Keine Sorge, wenn du mit dem Langkiefer-Schlammschnapper nicht 100 Kochkunst erreichst, du fängst später noch mehr rohe Langkiefer-Schlammschnapper.",
  ["Fish in the canals of Stormwind City until your skill reaches 130. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Angle in den Kanälen von Sturmwind, bis deine Fertigkeit 130 erreicht. Du solltest etwa 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} und 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} fangen.",
  ["Find {n:0::Catherine Leland} in Stormwind City and buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Tharynn Bouden} in Goldshire."] = "Such {n:0::Catherine Leland} in Sturmwind und kauf {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. Wenn du {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} noch nicht hast, kauf es bei {n:0::Tharynn Bouden} in Goldhain.",
  ["You should also find {n:0::Ben Trias} and buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from him. You will need these later for the Artisan Cooking quest."] = "Such außerdem {n:0::Ben Trias} und kauf 20 {i:8932:inv_misc_food_37:Alterac Swiss} bei ihm. Du brauchst sie später für die Quest für Kochkunst (Fachmann).",
  ["Learn Cooking from {n:0::Stephen Ryback} if you haven't yet. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. This should take your Cooking skill to 50."] = "Erlerne Kochkunst bei {n:0::Stephen Ryback}, falls noch nicht geschehen. Lern dann {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} und koch alle deine {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} zu {s:7751:inv_misc_fish_07:Brilliant Smallfish}. Damit sollte deine Kochkunst 50 erreichen.",
  ["Learn Journeyman Cooking from {n:0::Stephen Ryback} in Stormwind City. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "Erlerne Kochkunst (Geselle) bei {n:0::Stephen Ryback} in Sturmwind. Lern dann {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} und koch alle deine {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} zu {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Deine Kochkunst sollte über 100 steigen.",
  ["Fishing (130-205) and Cooking (100-175)"] = "Angeln (130-205) und Kochkunst (100-175)",
  ["Expert Fishing needs {b}level 20{/b} and {b}Fishing 125{/b}, Expert Cooking needs {b}Cooking 125{/b}."] = "Angeln (Experte) erfordert {b}Stufe 20{/b} und {b}Angeln 125{/b}, Kochkunst (Experte) erfordert {b}Kochkunst 125{/b}.",
  ["Booty Bay"] = "Beutebucht",
  ["Go to Ratchet in The Barrens and take the boat to Booty Bay in Stranglethorn Vale."] = "Geh nach Ratschet im Brachland und nimm das Schiff nach Beutebucht im Schlingendorntal.",
  ["Find {n:0::Old Man Heming} in Booty Bay, buy {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} from him and read it."] = "Such {n:0::Old Man Heming} in Beutebucht, kauf {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} bei ihm und lies es.",
  ["Find {n:0::Kelsey Yance} and buy these two recipes: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}."] = "Such {n:0::Kelsey Yance} und kauf diese zwei Rezepte: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}.",
  ["Go back to The Barrens, then fly from Ratchet to Sun Rock Retreat in Stonetalon Mountains and buy 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Kulwia}. You need 2 until 150, keep the other 5 for later."] = "Geh zurück ins Brachland, flieg dann von Ratschet zum Sonnenfels im Steinkrallengebirge und kauf 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} bei {n:0::Kulwia}. Bis 150 brauchst du 2, heb die anderen 5 für später auf.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Bring einen {i:6530:inv_misc_monstertail_03:Nightcrawler} an und angle im offenen Wasser, bis deine Angelfertigkeit 205 erreicht. Du fängst etwa 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} und 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Fly to Shadowprey Village in Desolace."] = "Flieg nach Schattenflucht in Desolace.",
  ["Find {n:0::Wulan} and buy the {i:16072:inv_misc_book_08:Expert Cookbook}. He is on the top floor of the eastern-most building in the village."] = "Such {n:0::Wulan} und kauf das {i:16072:inv_misc_book_08:Expert Cookbook}. Er ist im obersten Stockwerk des östlichsten Gebäudes im Dorf.",
  ["Buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from {n:0::Innkeeper Sikewa}. You will need them for the Artisan Cooking quest."] = "Kauf 20 {i:8932:inv_misc_food_37:Alterac Swiss} bei {n:0::Innkeeper Sikewa}. Du brauchst sie für die Quest für Kochkunst (Fachmann).",
  ["Leveling Cooking to 175"] = "Kochkunst auf 175 leveln",
  ["Cook your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper} if your Cooking skill is still below 100."] = "Koch deine {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} zu {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}, wenn deine Kochkunst noch unter 100 ist.",
  ["{b}Read the {i:16072:inv_misc_book_08:Expert Cookbook} as soon as you reach 125{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 150 and keep cooking for nothing."] = "{b}Lies das {i:16072:inv_misc_book_08:Expert Cookbook}, sobald du 125 erreichst{/b}, vor allem wenn du beim Kochen AFK gehst. Ohne es bekommst du ab 150 keine Fertigkeitspunkte mehr und kochst umsonst weiter.",
  ["Learn {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} and cook all your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Your Cooking skill will hopefully get close to 175."] = "Lern {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} und koch alle deine {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} zu {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Deine Kochkunst kommt damit hoffentlich nah an 175.",
  ["Don't worry if you don't reach 175 Cooking with Bristle Whisker Catfish, you will catch more Raw Bristle Whisker Catfish later."] = "Keine Sorge, wenn du mit dem Borstenbartwels nicht 175 Kochkunst erreichst, du fängst später noch mehr rohe Borstenbartwelse.",
  ["Go to Booty Bay in Stranglethorn Vale."] = "Geh nach Beutebucht im Schlingendorntal.",
  ["Go to The Barrens, then fly from Ratchet to Astranaar in Ashenvale. Ride south-east to Mystral Lake and buy the {i:16072:inv_misc_book_08:Expert Cookbook} and 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Shandrina}. You need 2 until 150, keep the other 5 for later."] = "Geh ins Brachland und flieg dann von Ratschet nach Astranaar im Eschental. Reite nach Südosten zum Mystralsee und kauf das {i:16072:inv_misc_book_08:Expert Cookbook} und 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} bei {n:0::Shandrina}. Bis 150 brauchst du 2, heb die anderen 5 für später auf.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water of Mystral Lake until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Bring einen {i:6530:inv_misc_monstertail_03:Nightcrawler} an und angle im offenen Wasser des Mystralsees, bis deine Angelfertigkeit 205 erreicht. Du fängst etwa 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} und 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Artisan Fishing Quest"] = "Quest für Angeln (Fachmann)",
  ["If you have no {i:6530:inv_misc_monstertail_03:Nightcrawlers} left, buy 5 from {n:0::Kilxx} in The Barrens or {n:0:alliance:Helenia Olden} in Dustwallow Marsh."] = "Wenn du keine {i:6530:inv_misc_monstertail_03:Nightcrawlers} mehr hast, kauf 5 bei {n:0::Kilxx} im Brachland oder {n:0:alliance:Helenia Olden} in den Düstermarschen.",
  ["Go to Dustwallow Marsh and {b}fish anywhere in the swamp until your skill reaches 225{/b}. {b}Don't fish in the ocean.{/b} Keep a {i:6530:inv_misc_monstertail_03:Nightcrawler} on your pole until 225, otherwise a few fish get away."] = "Geh in die Düstermarschen und {b}angle irgendwo im Sumpf, bis deine Fertigkeit 225 erreicht{/b}. {b}Angle nicht im Meer.{/b} Behalte bis 225 einen {i:6530:inv_misc_monstertail_03:Nightcrawler} an deiner Angel, sonst entkommen ein paar Fische.",
  ["Find {n:0::Nat Pagle} and accept the quest {q:6607::Nat Pagle, Angler Extreme}. It requires {b}level 35{/b} and {b}Fishing 225{/b}, and you need it to learn Artisan Fishing."] = "Such {n:0::Nat Pagle} und nimm die Quest {q:6607::Nat Pagle, Angler Extreme} an. Sie erfordert {b}Stufe 35{/b} und {b}Angeln 225{/b}, und du brauchst sie, um Angeln (Fachmann) zu erlernen.",
  ["Tidefury Cove, Dustwallow Marsh"] = "Tidefury Cove, Düstermarschen",
  ["To complete the quest you have to catch 4 quest fish in four different zones:"] = "Um die Quest abzuschließen, musst du 4 Questfische in vier verschiedenen Gebieten fangen:",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas (attach the {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you kept, or {i:6532:inv_misc_gem_variety_02:Bright Baubles} from {n:0::Sheendra Tallgrass} / {n:0::Vivianna} in Feralas, otherwise most of them get away)"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas (bring den {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} an, den du aufgehoben hast, oder {i:6532:inv_misc_gem_variety_02:Bright Baubles} von {n:0::Sheendra Tallgrass} / {n:0::Vivianna} in Feralas, sonst entkommen die meisten)",
  ["{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - Swamp of Sorrows"] = "{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - Sümpfe des Elends",
  ["{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - Stranglethorn Vale"] = "{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - Schlingendorntal",
  ["Nat Pagle, Angler Extreme Quest Fishes"] = "Questfische für Nat Pagle, Angler Extreme",
  ["Where to catch the four Nat Pagle quest fish"] = "Wo du die vier Questfische für Nat Pagle fängst",
  ["Leveling Fishing to 255 and Cooking to 225"] = "Angeln auf 255 und Kochkunst auf 225 leveln",
  ["After you completed the quest, {b}keep fishing in the swamp in Dustwallow Marsh until your Fishing skill reaches 255.{/b} {b}Don't fish in the ocean{/b}, because there you catch Raw Rockscale Cod instead of the Raw Mithril Head Trout you cook next."] = "Wenn du die Quest abgeschlossen hast, {b}angle weiter im Sumpf der Düstermarschen, bis deine Angelfertigkeit 255 erreicht.{/b} {b}Angle nicht im Meer{/b}, denn dort fängst du rohen Felsschuppenkabeljau statt der rohen Mithrilkopfforelle, die du als Nächstes kochst.",
  ["Go back to Brackenwall Village (Horde) / Theramore Isle (Alliance) to cook your fish, or put down a campfire if you have one."] = "Geh zurück ins Dorf Brackenwall (Horde) / zur Insel Theramore (Allianz), um deine Fische zu kochen, oder stell ein Lagerfeuer auf, wenn du eins hast.",
  ["Cook your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish} if your Cooking skill is still below 175."] = "Koch deine {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} zu {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, wenn deine Kochkunst noch unter 175 ist.",
  ["Learn {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} and cook your {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 225. Keep the rest, you cook them after the Artisan Cooking quest."] = "Lern {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} und koch deine {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} bis 225 zu {s:20916:inv_misc_fish_02:Mithril Headed Trout}. Behalte den Rest, du kochst ihn nach der Quest für Kochkunst (Fachmann).",
  ["Artisan Cooking Quest"] = "Quest für Kochkunst (Fachmann)",
  ["Fly to Gadgetzan in Tanaris and pick up the quest {q:6610::Clamlette Surprise} from {n:0::Dirge Quikcleave}. The reward is Artisan Cooking. The quest requires {b}level 35{/b} and {b}Cooking 225{/b}. You will need these to complete the quest:"] = "Flieg nach Gadgetzan in Tanaris und nimm die Quest {q:6610::Clamlette Surprise} bei {n:0::Dirge Quikcleave} an. Die Belohnung ist Kochkunst (Fachmann). Die Quest erfordert {b}Stufe 35{/b} und {b}Kochkunst 225{/b}. Für die Quest brauchst du:",
  ["12x {i:12207:inv_egg_03:Giant Egg} - dropped by the {n:5428::Rocs}, {n:5429::Fire Rocs} and {n:5430::Searing Rocs} in Tanaris."] = "12x {i:12207:inv_egg_03:Giant Egg} - fallen gelassen von den {n:5428::Rocs}, {n:5429::Fire Rocs} und {n:5430::Searing Rocs} in Tanaris.",
  ["10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - from Big-mouth Clams, dropped by {n:14123::Steeljaw Snappers} and {n:5431::Surf Gliders} in Tanaris."] = "10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - aus großmäuligen Muscheln, die von {n:14123::Steeljaw Snappers} und {n:5431::Surf Gliders} in Tanaris fallen gelassen werden.",
  ["20x {i:8932:inv_misc_food_37:Alterac Swiss} - you bought these earlier."] = "20x {i:8932:inv_misc_food_37:Alterac Swiss} - die hast du vorhin gekauft.",
  ["Find {n:0::Gikkix} at Steamwheedle Port in Tanaris and buy {i:13945:inv_scroll_03:Recipe: Nightfin Soup}."] = "Such {n:0::Gikkix} am Dampfdruckpier in Tanaris und kauf {i:13945:inv_scroll_03:Recipe: Nightfin Soup}.",
  ["Fishing to 300 in Feralas"] = "Angeln auf 300 in Feralas",
  ["Fly to Camp Mojache (Horde) / Feathermoon Stronghold (Alliance) in Feralas."] = "Flieg zum Camp Mojache (Horde) / zur Mondfederfeste (Allianz) in Feralas.",
  ["Buy 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}."] = "Kauf 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} bei {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the marked lake until you reach Fishing 300, use a new one every 10 minutes. Any other lake or river in Feralas works too, {b}except Jademir Lake{/b}."] = "Bring einen {i:6530:inv_misc_monstertail_03:Nightcrawler} an und angle im markierten See, bis du Angeln 300 erreichst, nimm alle 10 Minuten einen neuen. Jeder andere See oder Fluss in Feralas geht auch, {b}außer dem Jademirsee{/b}.",
  ["Where to fish in Feralas from 255 to 300"] = "Wo du in Feralas von 255 bis 300 angelst",
  ["Leveling Cooking to 300"] = "Kochkunst auf 300 leveln",
  ["Cook your remaining {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 250."] = "Koch deine restlichen {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} bis 250 zu {s:20916:inv_misc_fish_02:Mithril Headed Trout}.",
  ["Learn {i:13941:inv_scroll_03:Recipe: Filet of Redgill} and cook your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} until 285."] = "Lern {i:13941:inv_scroll_03:Recipe: Filet of Redgill} und koch deine {i:13758:inv_misc_fish_06:Raw Redgill} bis 285 zu {s:18241:inv_misc_fish_06:Filet of Redgill}.",
  ["Learn {i:13945:inv_scroll_03:Recipe: Nightfin Soup} and cook all your {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} into {s:18243:inv_drink_17:Nightfin Soup}. You also need a {i:159:inv_drink_07:Refreshing Spring Water} for each soup, buy 20 from the innkeeper."] = "Lern {i:13945:inv_scroll_03:Recipe: Nightfin Soup} und koch alle deine {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} zu {s:18243:inv_drink_17:Nightfin Soup}. Für jede Suppe brauchst du außerdem ein {i:159:inv_drink_07:Refreshing Spring Water}, kauf 20 beim Gastwirt.",
  ["{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} don't bite in the afternoon (12:00-18:00 game time). If you fished in the afternoon, you will probably not have enough, so cook the rest of your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} too, you might reach 300 with them."] = "{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} beißen nachmittags nicht an (12:00-18:00 Spielzeit). Wenn du nachmittags geangelt hast, hast du wahrscheinlich nicht genug, koch also auch den Rest deiner {i:13758:inv_misc_fish_06:Raw Redgill} zu {s:18241:inv_misc_fish_06:Filet of Redgill}, damit erreichst du vielleicht 300.",
  ["If you still don't reach 300, fish a bit more outside the afternoon, or buy a few {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} on the Auction House."] = "Wenn du 300 immer noch nicht erreichst, angle außerhalb des Nachmittags noch etwas weiter oder kauf ein paar {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} im Auktionshaus.",
  ["This WoW Forever Cooking leveling guide will show you the fastest way to level your Cooking skill from 1 to 300 as cheaply as possible. You will also find every trainer location, how the campfire works in Forever and where to train Cooking past 150 and 225."] = "Dieser WoW-Forever-Leitfaden für Kochkunst zeigt dir den schnellsten Weg, deine Kochkunst so günstig wie möglich von 1 auf 300 zu leveln. Außerdem findest du alle Lehrer, erfährst, wie das Lagerfeuer in Forever funktioniert und wo du Kochkunst über 150 und 225 hinaus erlernen kannst.",
  ["Cooking doesn't take up one of your two profession slots, so every character can learn it. Most of the recipes below only need the meat or fish that drops while you level, so the guide lists a few recipes for every skill range and you can make the one you have the ingredients for. If you also want to level Fishing but haven't leveled it yet, use my Fishing and Cooking leveling guide instead:"] = "Kochkunst belegt keinen deiner zwei Berufsplätze, daher kann jeder Charakter sie erlernen. Die meisten Rezepte unten brauchen nur das Fleisch oder den Fisch, die du beim Leveln findest, daher nennt der Leitfaden für jeden Fertigkeitsbereich ein paar Rezepte und du kannst das herstellen, für das du die Zutaten hast. Wenn du auch Angeln leveln willst, es aber noch nicht gelevelt hast, nimm stattdessen meinen Leitfaden für Angeln und Kochkunst:",
  ["You need level 35 to go past 225, so I split the list in two. Buy this part first."] = "Um über 225 hinauszukommen, brauchst du Stufe 35, deshalb habe ich die Liste in zwei Teile geteilt. Kauf zuerst diesen Teil.",
  ["The Giant Eggs and the Zesty Clam Meat are for the Artisan Cooking quest."] = "Die riesigen Eier und das würzige Muschelfleisch sind für die Quest für Kochkunst (Fachmann).",
  ["Cooking Trainer Locations"] = "Standorte der Kochkunstlehrer",
  ["Apprentice Cooking has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman Cooking, so you don't have to find a different trainer at 50."] = "Kochkunst (Lehrling) hat keine Stufenvoraussetzung, du kannst es also schon mit einem neuen Charakter erlernen. Jeder Lehrer bringt dir auch Kochkunst (Geselle) bei, du musst bei 50 also keinen anderen Lehrer suchen.",
  ["Undercity: {n:0:horde:Eunice Burch}"] = "Unterstadt: {n:0:horde:Eunice Burch}",
  ["Thunder Bluff: {n:0:horde:Aska Mistrunner}"] = "Donnerfels: {n:0:horde:Aska Mistrunner}",
  ["Every starting zone has a Cooking trainer, most of them are inside the inn."] = "Jedes Startgebiet hat einen Kochkunstlehrer, die meisten sind im Gasthaus.",
  ["{n:0:horde:Cook Torka} in Razor Hill"] = "{n:0:horde:Cook Torka} in Klingenhügel",
  ["{n:0:horde:Pyall Silentstride} inside the big tent in Bloodhoof Village"] = "{n:0:horde:Pyall Silentstride} im großen Zelt im Dorf der Bluthufe",
  ["{n:0:horde:William Pickman} inside the inn in Brill"] = "{n:0:horde:William Pickman} im Gasthaus in Brill",
  ["Stormwind City: {n:0:alliance:Stephen Ryback}"] = "Sturmwind: {n:0:alliance:Stephen Ryback}",
  ["Ironforge: {n:0:alliance:Daryl Riknussun}"] = "Eisenschmiede: {n:0:alliance:Daryl Riknussun}",
  ["{n:0:alliance:Tomas} in the kitchen of the inn in Goldshire"] = "{n:0:alliance:Tomas} in der Küche des Gasthauses in Goldhain",
  ["{n:0:alliance:Gremlock Pilsnor} in the Thunderbrew Distillery in Kharanos"] = "{n:0:alliance:Gremlock Pilsnor} in der Donnerbräu-Brauerei in Kharanos",
  ["You can find every Cooking trainer for Horde and Alliance on my WoW Forever Cooking Trainers page."] = "Alle Kochkunstlehrer für Horde und Allianz findest du auf meiner Seite zu den WoW-Forever-Kochkunstlehrern.",
  ["Campfire"] = "Lagerfeuer",
  ["You need a campfire to cook. There is often one burning next to the Cooking trainer, so look around before you make your own."] = "Zum Kochen brauchst du ein Lagerfeuer. Neben dem Kochkunstlehrer brennt oft eins, schau dich also um, bevor du dein eigenes machst.",
  ["In Forever the campfire is an item. You learn the {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} together with Cooking and place the fire from your bags, so you can make a stack of kits in advance. Other players can add their own camp items to your fire, you can read about the whole camping system in my WoW Forever Camping Guide."] = "In Forever ist das Lagerfeuer ein Gegenstand. Du lernst das {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} zusammen mit Kochkunst und stellst das Feuer aus deinen Taschen auf, du kannst also vorab einen Stapel Sets herstellen. Andere Spieler können ihre eigenen Lagergegenstände an dein Feuer stellen, alles über das Lagersystem kannst du in meinem WoW-Forever-Lagerleitfaden nachlesen.",
  ["To craft the kits you need {i:4470:inv_tradeskillitem_01:Simple Wood} and a {i:4471:inv_stone_11:Flint and Tinder}. The Flint and Tinder is only for crafting the kits, you don't need it to place the fire. Open your faction below to see who sells them near your trainer:"] = "Für die Sets brauchst du {i:4470:inv_tradeskillitem_01:Simple Wood} und {i:4471:inv_stone_11:Flint and Tinder}. Feuerstein und Zunder brauchst du nur zum Herstellen der Sets, nicht zum Aufstellen des Feuers. Öffne unten deine Fraktion, um zu sehen, wer sie in der Nähe deines Lehrers verkauft:",
  ["{n:0:horde:Xen'to}, next to the trainer"] = "{n:0:horde:Xen'to}, neben dem Lehrer",
  ["{n:0:horde:Ronald Burch}, next to the trainer"] = "{n:0:horde:Ronald Burch}, neben dem Lehrer",
  ["{n:0:horde:Naal Mistrunner}, next to the trainer"] = "{n:0:horde:Naal Mistrunner}, neben dem Lehrer",
  ["{n:0:horde:Jark} in the Razor Hill barracks"] = "{n:0:horde:Jark} in der Kaserne von Klingenhügel",
  ["{n:0:horde:Moorat Longstride} in Bloodhoof Village"] = "{n:0:horde:Moorat Longstride} im Dorf der Bluthufe",
  ["{n:0::Antelariaa Cloudgaze} in Valanaar {n:0::Zerril Softbreeze}, the Cooking trainer in Shen'dar Village"] = "{n:0::Antelariaa Cloudgaze} in Valanaar {n:0::Zerril Softbreeze}, der Kochkunstlehrer in Shen'dar Village",
  ["{n:0:alliance:Erika Tate}, next to the trainer"] = "{n:0:alliance:Erika Tate}, neben dem Lehrer",
  ["{n:0:alliance:Emrul Riknussun}, next to the trainer"] = "{n:0:alliance:Emrul Riknussun}, neben dem Lehrer",
  ["{n:0:alliance:Fyldan}, next to the trainer"] = "{n:0:alliance:Fyldan}, neben dem Lehrer",
  ["{n:0:alliance:Brog Hamfist} in Goldshire"] = "{n:0:alliance:Brog Hamfist} in Goldhain",
  ["{n:0:alliance:Kreg Bilmn} in the Thunderbrew Distillery"] = "{n:0:alliance:Kreg Bilmn} in der Donnerbräu-Brauerei",
  ["Apprentice Cooking (1-50)"] = "Kochkunst (Lehrling) (1-50)",
  ["{b}These are sold by Cooking Supply vendors near your trainer, don't buy them from the Auction House:{/b}"] = "{b}Diese werden von Händlern für Kochbedarf in der Nähe deines Lehrers verkauft, kauf sie nicht im Auktionshaus:{/b}",
  ["Make around 55 from one of these recipes. The two fish are usually the cheapest."] = "Stell etwa 55 von einem dieser Rezepte her. Die beiden Fische sind meist am günstigsten.",
  ["Food"] = "Essen",
  ["Ingredients"] = "Zutaten",
  ["Recipe Source"] = "Rezeptquelle",
  ["Mulgore: {n:0:horde:Harn Longcast} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Tirisfal Glades: {n:0:horde:Martine Tramblay} Undercity: {n:0:horde:Lizbeth Cromwell} Dun Morogh: {n:0:alliance:Gretta Ganter} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Loch Modan: {n:0:alliance:Khara Deepwater} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nyoma}"] = "Mulgore: {n:0:horde:Harn Longcast} Donnerfels: {n:0:horde:Sewa Mistrunner} Tirisfal: {n:0:horde:Martine Tramblay} Unterstadt: {n:0:horde:Lizbeth Cromwell} Dun Morogh: {n:0:alliance:Gretta Ganter} Wald von Elwynn: {n:0:alliance:Tharynn Bouden} Loch Modan: {n:0:alliance:Khara Deepwater} Sturmwind: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Tirisfal Glades: {n:0:horde:Martine Tramblay} Ironforge: {n:0:alliance:Tansy Puddlefizz} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone}"] = "Durotar: {n:0:horde:Zansoa} Tirisfal: {n:0:horde:Martine Tramblay} Eisenschmiede: {n:0:alliance:Tansy Puddlefizz} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone}",
  ["Trainer"] = "Lehrer",
  ["(Horde only) Make {s:15935:inv_misc_food_46:Crispy Bat Wing} if you have some {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}. The recipe is sold by {n:0:horde:Abigail Shiel} in Tirisfal Glades."] = "(Nur Horde) Stell {s:15935:inv_misc_food_46:Crispy Bat Wing} her, wenn du ein paar {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing} hast. Das Rezept wird von {n:0:horde:Abigail Shiel} in Tirisfal verkauft.",
  ["(Horde only) Make {s:6413:inv_misc_food_10:Scorpid Surprise} if you have some {i:5466:spell_nature_nullifypoison:Scorpid Stinger}. The recipe is sold by {n:0:horde:Grimtak} in Durotar."] = "(Nur Horde) Stell {s:6413:inv_misc_food_10:Scorpid Surprise} her, wenn du ein paar {i:5466:spell_nature_nullifypoison:Scorpid Stinger} hast. Das Rezept wird von {n:0:horde:Grimtak} in Durotar verkauft.",
  ["(Alliance only) Make {s:6412:inv_misc_food_68:Kaldorei Spider Kabob} if you have some {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}. The recipe is a reward from {q:4161::Recipe of the Kaldorei}. You can get the quest from {n:0:alliance:Zarrin} in Teldrassil."] = "(Nur Allianz) Stell {s:6412:inv_misc_food_68:Kaldorei Spider Kabob} her, wenn du ein paar {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg} hast. Das Rezept ist eine Belohnung aus {q:4161::Recipe of the Kaldorei}. Die Quest bekommst du bei {n:0:alliance:Zarrin} in Teldrassil.",
  ["Journeyman Cooking (50-150)"] = "Kochkunst (Geselle) (50-150)",
  ["{b}Visit your trainer again and learn Journeyman Cooking{/b}, it requires Cooking 50."] = "{b}Besuche deinen Lehrer erneut und erlerne Kochkunst (Geselle){/b}, es erfordert Kochkunst 50.",
  ["{b}Make sure to learn Journeyman Cooking before you start the next part{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 75 and keep cooking for nothing."] = "{b}Erlerne unbedingt Kochkunst (Geselle), bevor du mit dem nächsten Teil anfängst{/b}, vor allem wenn du beim Kochen AFK gehst. Ohne es bekommst du ab 75 keine Fertigkeitspunkte mehr und kochst umsonst weiter.",
  ["Make around 55 from any of the recipes below. The two fish are usually the cheapest. {s:8607:inv_misc_food_13:Smoked Bear Meat} turns yellow sooner than the rest, so make more of it, or cook it first if you have more than one type of meat."] = "Stell etwa 55 von einem beliebigen Rezept unten her. Die beiden Fische sind meist am günstigsten. {s:8607:inv_misc_food_13:Smoked Bear Meat} wird früher gelb als die anderen, stell also mehr davon her oder koch es zuerst, wenn du mehr als eine Fleischsorte hast.",
  ["Mulgore: {n:0:horde:Harn Longcast} Silverpine Forest: {n:0:horde:Killian Sanatha} Thunder Bluff: {n:0:horde:Naal Mistrunner} Undercity: {n:0:horde:Lizbeth Cromwell} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Ironforge: {n:0:alliance:Tansy Puddlefizz} Loch Modan: {n:0:alliance:Khara Deepwater} Teldrassil: {n:0:alliance:Nyoma}"] = "Mulgore: {n:0:horde:Harn Longcast} Silberwald: {n:0:horde:Killian Sanatha} Donnerfels: {n:0:horde:Naal Mistrunner} Unterstadt: {n:0:horde:Lizbeth Cromwell} Wald von Elwynn: {n:0:alliance:Tharynn Bouden} Eisenschmiede: {n:0:alliance:Tansy Puddlefizz} Loch Modan: {n:0:alliance:Khara Deepwater} Teldrassil: {n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Orgrimmar: {n:0:horde:Shankys} Silverpine Forest: {n:0:horde:Killian Sanatha} Undercity: {n:0:horde:Ronald Burch} Darkshore: {n:0:alliance:Heldan Galesong} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone} Wetlands: {n:0:alliance:Stuart Fleming} The Barrens: {n:0::Kilxx}"] = "Durotar: {n:0:horde:Zansoa} Orgrimmar: {n:0:horde:Shankys} Silberwald: {n:0:horde:Killian Sanatha} Unterstadt: {n:0:horde:Ronald Burch} Dunkelküste: {n:0:alliance:Heldan Galesong} Sturmwind: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone} Sumpfland: {n:0:alliance:Stuart Fleming} Brachland: {n:0::Kilxx}",
  ["Silverpine Forest: {n:0:horde:Andrew Hilbert} Loch Modan: {n:0:alliance:Drac Roughcut}"] = "Silberwald: {n:0:horde:Andrew Hilbert} Loch Modan: {n:0:alliance:Drac Roughcut}",
  ["55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (Vendor)"] = "55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (Händler)",
  ["The Barrens: {n:0:horde:Tari'qa} (Horde only) Reward from {q:2178::Easy Strider Living} (Alliance only)"] = "Brachland: {n:0:horde:Tari'qa} (nur Horde) Belohnung aus {q:2178::Easy Strider Living} (nur Allianz)",
  ["Make around 30-35 from one of these two."] = "Stell etwa 30-35 von einem dieser beiden her.",
  ["30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (buy around 55, you will need 25 more at 130-150)"] = "30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (kauf etwa 55, du brauchst bei 130-150 noch 25 weitere)",
  ["Hillsbrad Foothills: {n:0:horde:Derak Nightfall} Thunder Bluff: {n:0:horde:Naal Mistrunner} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Undercity: {n:0:horde:Ronald Burch} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne} Stormwind City: {n:0:alliance:Catherine Leland} The Barrens: {n:0::Kilxx}"] = "Vorgebirge des Hügellands: {n:0:horde:Derak Nightfall} Donnerfels: {n:0:horde:Naal Mistrunner} Donnerfels: {n:0:horde:Sewa Mistrunner} Unterstadt: {n:0:horde:Ronald Burch} Vorgebirge des Hügellands: {n:0:alliance:Lindea Rabonne} Sturmwind: {n:0:alliance:Catherine Leland} Brachland: {n:0::Kilxx}",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance only)"] = "Sturmwind: {n:0:alliance:Kendor Kabonka} (nur Allianz)",
  ["Make around 20-25 from any of the recipes below."] = "Stell etwa 20-25 von einem beliebigen Rezept unten her.",
  ["See above"] = "Siehe oben",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance) Arathi Highlands: {n:0:horde:Keena} (Horde)"] = "Sturmwind: {n:0:alliance:Kendor Kabonka} (Allianz) Arathihochland: {n:0:horde:Keena} (Horde)",
  ["The Barrens: {n:0:horde:Zargh} (Horde only)"] = "Brachland: {n:0:horde:Zargh} (nur Horde)",
  ["Expert Cooking (150-225)"] = "Kochkunst (Experte) (150-225)",
  ["To learn Expert Cooking you need to reach Cooking 125, then buy the {i:16072:inv_misc_book_08:Expert Cookbook} from {n:0:horde:Wulan} (Horde) in Desolace at Shadowprey Village or from {n:0:alliance:Shandrina} (Alliance) in Ashenvale at Mystral Lake."] = "Um Kochkunst (Experte) zu erlernen, musst du Kochkunst 125 erreichen und dann das {i:16072:inv_misc_book_08:Expert Cookbook} bei {n:0:horde:Wulan} (Horde) in Schattenflucht in Desolace oder bei {n:0:alliance:Shandrina} (Allianz) am Mystralsee im Eschental kaufen.",
  ["Make around 25-30 from one of these three."] = "Stell etwa 25-30 von einem dieser drei her.",
  ["You can also keep making {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, but it's green from 160, so you need around 90 of them for these 25 points."] = "Du kannst auch weiter {s:7755:inv_misc_fish_30:Bristle Whisker Catfish} herstellen, aber ab 160 ist es grün, du brauchst also etwa 90 davon für diese 25 Punkte.",
  ["Make around 55 from one of these. The Roast Raptor is usually the cheapest."] = "Stell etwa 55 von einem dieser her. Der Raptorbraten ist meist am günstigsten.",
  ["Arathi Highlands: {n:0:alliance:Hammon Karwn} Arathi Highlands: {n:0:horde:Keena} Dustwallow Marsh: {n:0:horde:Ogg'marr}"] = "Arathihochland: {n:0:alliance:Hammon Karwn} Arathihochland: {n:0:horde:Keena} Düstermarschen: {n:0:horde:Ogg'marr}",
  ["Ashenvale: {n:0:horde:Wik'Tar} Orgrimmar: {n:0:horde:Shankys} Stranglethorn Vale: {n:0::Kelsey Yance} Undercity: {n:0:horde:Lizbeth Cromwell} Ironforge: {n:0:alliance:Tansy Puddlefizz} Wetlands: {n:0:alliance:Stuart Fleming} Desolace: {n:0:horde:Wulan} Darkshore: {n:0:alliance:Heldan Galesong} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne}"] = "Eschental: {n:0:horde:Wik'Tar} Orgrimmar: {n:0:horde:Shankys} Schlingendorntal: {n:0::Kelsey Yance} Unterstadt: {n:0:horde:Lizbeth Cromwell} Eisenschmiede: {n:0:alliance:Tansy Puddlefizz} Sumpfland: {n:0:alliance:Stuart Fleming} Desolace: {n:0:horde:Wulan} Dunkelküste: {n:0:alliance:Heldan Galesong} Vorgebirge des Hügellands: {n:0:alliance:Lindea Rabonne}",
  ["Reward from a quest in Hillsbrad Foothills NPC: {n:0:horde:Christoph Jeffcoat}, quest: {q:7321::Soothing Turtle Bisque} NPC: {n:0:alliance:Chef Jessen}, quest: {q:555::Soothing Turtle Bisque}"] = "Belohnung aus einer Quest im Vorgebirge des Hügellands NPC: {n:0:horde:Christoph Jeffcoat}, Quest: {q:7321::Soothing Turtle Bisque} NPC: {n:0:alliance:Chef Jessen}, Quest: {q:555::Soothing Turtle Bisque}",
  ["Artisan Cooking (225-300)"] = "Kochkunst (Fachmann) (225-300)",
  ["Artisan Cooking is the reward of the {q:6610::Clamlette Surprise} quest. You need {b}level 35{/b} and {b}Cooking 225{/b} for it."] = "Kochkunst (Fachmann) ist die Belohnung der Quest {q:6610::Clamlette Surprise}. Dafür brauchst du {b}Stufe 35{/b} und {b}Kochkunst 225{/b}.",
  ["Pick up the quest that sends you to Gadgetzan: Horde players take {q:6611::To Gadgetzan You Go!} from {n:0:horde:Zamja} in Orgrimmar, Alliance players take {q:6612::I Know A Guy...} from {n:0:alliance:Daryl Riknussun} in Ironforge."] = "Nimm die Quest an, die dich nach Gadgetzan schickt: Spieler der Horde nehmen {q:6611::To Gadgetzan You Go!} bei {n:0:horde:Zamja} in Orgrimmar an, Spieler der Allianz nehmen {q:6612::I Know A Guy...} bei {n:0:alliance:Daryl Riknussun} in Eisenschmiede an.",
  ["Collect 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} and 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}Don't go to Gadgetzan before you have all of them{/b}, otherwise you make the trip twice."] = "Sammle 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} und 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}Geh erst nach Gadgetzan, wenn du alles hast{/b}, sonst machst du die Reise zweimal.",
  ["Find {n:0::Dirge Quikcleave} in Gadgetzan, take Clamlette Surprise from him and hand in the three items. He teaches you Artisan Cooking on the spot. While you are in Tanaris, go to Steamwheedle Port and {b}buy {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} from {n:0::Gikkix}{/b}, you need it in the next step."] = "Such {n:0::Dirge Quikcleave} in Gadgetzan, nimm bei ihm Clamlette Surprise an und gib die drei Gegenstände ab. Er bringt dir Kochkunst (Fachmann) sofort bei. Während du in Tanaris bist, geh zum Dampfdruckpier und {b}kauf {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} bei {n:0::Gikkix}{/b}, du brauchst es im nächsten Schritt.",
  ["Make around 140 from one of these two, buy the fish that is cheaper."] = "Stell etwa 140 von einem dieser beiden her, kauf den Fisch, der günstiger ist.",
  ["Stranglethorn Vale: {n:0::Kelsey Yance}"] = "Schlingendorntal: {n:0::Kelsey Yance}",
  ["This WoW Forever First Aid leveling guide will show you the fastest way to level your First Aid skill from 1 to 300. You will also find every trainer location and where to train First Aid past 150 and 225."] = "Dieser WoW-Forever-Leitfaden für Erste Hilfe zeigt dir den schnellsten Weg, deine Erste-Hilfe-Fertigkeit von 1 auf 300 zu leveln. Außerdem findest du alle Lehrer und erfährst, wo du Erste Hilfe über 150 und 225 hinaus erlernen kannst.",
  ["First Aid does not take up one of your two profession slots, so every character can learn it. Bandages heal you between fights, and in Forever First Aid also makes the healing potions that used to be Alchemy recipes, so it's worth leveling on every character. Below you will find the shopping list, the First Aid trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "Erste Hilfe belegt keinen deiner zwei Berufsplätze, daher kann jeder Charakter sie erlernen. Verbände heilen dich zwischen den Kämpfen, und in Forever stellt Erste Hilfe auch die Heiltränke her, die früher Alchimierezepte waren. Es lohnt sich also, sie auf jedem Charakter zu leveln. Unten findest du die Einkaufsliste, die Erste-Hilfe-Lehrer nach Startgebiet und Hauptstadt sowie die günstigsten Rezepte für jeden Fertigkeitsbereich.",
  ["First Aid Trainer Locations"] = "Standorte der Erste-Hilfe-Lehrer",
  ["Apprentice First Aid has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman First Aid, so you don't have to find a different trainer at 50."] = "Erste Hilfe (Lehrling) hat keine Stufenvoraussetzung, du kannst es also schon mit einem neuen Charakter erlernen. Jeder Lehrer bringt dir auch Erste Hilfe (Geselle) bei, du musst bei 50 also keinen anderen Lehrer suchen.",
  ["Undercity: {n:0:horde:Mary Edras}"] = "Unterstadt: {n:0:horde:Mary Edras}",
  ["Thunder Bluff: {n:0:horde:Pand Stonebinder}"] = "Donnerfels: {n:0:horde:Pand Stonebinder}",
  ["Every starting zone has a First Aid trainer, most of them are inside the inn."] = "Jedes Startgebiet hat einen Erste-Hilfe-Lehrer, die meisten sind im Gasthaus.",
  ["{n:0:horde:Rawrk} in the barracks in Razor Hill"] = "{n:0:horde:Rawrk} in der Kaserne in Klingenhügel",
  ["{n:0:horde:Vira Younghoof} inside the inn in Bloodhoof Village"] = "{n:0:horde:Vira Younghoof} im Gasthaus im Dorf der Bluthufe",
  ["{n:0:horde:Nurse Neela} inside the inn in Brill"] = "{n:0:horde:Nurse Neela} im Gasthaus in Brill",
  ["Stormwind City: {n:0:alliance:Shaina Fuller}"] = "Sturmwind: {n:0:alliance:Shaina Fuller}",
  ["Ironforge: {n:0:alliance:Nissa Firestone}"] = "Eisenschmiede: {n:0:alliance:Nissa Firestone}",
  ["{n:0:alliance:Michelle Belle} upstairs in the inn in Goldshire"] = "{n:0:alliance:Michelle Belle} im Obergeschoss des Gasthauses in Goldhain",
  ["{n:0:alliance:Thamner Pol} in the Thunderbrew Distillery in Kharanos"] = "{n:0:alliance:Thamner Pol} in der Donnerbräu-Brauerei in Kharanos",
  ["{n:0:alliance:Byancie} in Dolanaar, in the building north of the inn"] = "{n:0:alliance:Byancie} in Dolanaar, im Gebäude nördlich des Gasthauses",
  ["You can find every First Aid trainer for Horde and Alliance on my WoW Forever First Aid Trainers page."] = "Alle Erste-Hilfe-Lehrer für Horde und Allianz findest du auf meiner Seite zu den WoW-Forever-Erste-Hilfe-Lehrern.",
  ["Apprentice First Aid (1-75)"] = "Erste Hilfe (Lehrling) (1-75)",
  ["If you have Linen Cloth or bought some, pick the {b}Bandages{/b} tab. If you bought herbs, pick the {b}Healing Potions{/b} tab."] = "Wenn du Leinenstoff hast oder welchen gekauft hast, wähl den Reiter {b}Verbände{/b}. Wenn du Kräuter gekauft hast, wähl den Reiter {b}Heiltränke{/b}.",
  ["Bandages"] = "Verbände",
  ["Healing Potions"] = "Heiltränke",
  ["86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Peacebloom, 86 Mild Spices, 86 Empty Vial"] = "86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Friedensblume, 86 Milde Gewürze, 86 Leere Phiole",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} are sold by Cooking supply vendors, {i:3371:inv_potion_84:Empty Vial} by Alchemy supply vendors. Open your faction below to see who sells them near your trainer:"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices} werden von Händlern für Kochbedarf verkauft, {i:3371:inv_potion_84:Empty Vial} von Händlern für Alchimiebedarf. Öffne unten deine Fraktion, um zu sehen, wer sie in der Nähe deines Lehrers verkauft:",
  ["spices: {n:0:horde:Xen'to} vials: {n:0:horde:Kor'geld}"] = "Gewürze: {n:0:horde:Xen'to} Phiolen: {n:0:horde:Kor'geld}",
  ["{n:0:horde:Felicia Doan} in the Trade Quarter"] = "{n:0:horde:Felicia Doan} im Händlerviertel",
  ["spices: {n:0:horde:Naal Mistrunner} vials: {n:0:horde:Mani Winterhoof}"] = "Gewürze: {n:0:horde:Naal Mistrunner} Phiolen: {n:0:horde:Mani Winterhoof}",
  ["{n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "{n:0:horde:Wunna Darkmane} im Dorf der Bluthufe",
  ["{n:0:alliance:Edna Mullby} in the Trade District"] = "{n:0:alliance:Edna Mullby} im Handelsdistrikt",
  ["spices: {n:0:alliance:Emrul Riknussun} vials: {n:0:alliance:Gwina Stonebranch}, right next to the trainer"] = "Gewürze: {n:0:alliance:Emrul Riknussun} Phiolen: {n:0:alliance:Gwina Stonebranch}, direkt neben dem Lehrer",
  ["50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Linen Cloth"] = "50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Leinenstoff",
  ["49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Linen Cloth"] = "49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Leinenstoff",
  ["Journeyman First Aid (75-150)"] = "Erste Hilfe (Geselle) (75-150)",
  ["To train past 75, visit your trainer and learn Journeyman First Aid, it requires First Aid 50."] = "Um über 75 hinauszukommen, besuche deinen Lehrer und erlerne Erste Hilfe (Geselle), es erfordert Erste Hilfe 50.",
  ["16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Linen Cloth"] = "16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Leinenstoff",
  ["12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Wool Cloth"] = "12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Wollstoff",
  ["If you have Wool Cloth, pick the {b}Bandages{/b} tab. If you have to buy everything, the {b}Healing Potions{/b} tab is cheaper."] = "Wenn du Wollstoff hast, wähl den Reiter {b}Verbände{/b}. Wenn du alles kaufen musst, ist der Reiter {b}Heiltränke{/b} günstiger.",
  ["43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Wool Cloth"] = "43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Wollstoff",
  ["54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Wool Cloth"] = "54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Wollstoff",
  ["For this tab you need 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} and 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Spices are sold by Cooking supply vendors, vials by Alchemy supply vendors and the bottles by barkeeps. The starting zone vendors don't sell Hot Spices or Leaded Vials, so buy them in a capital city. Open your faction below to see who sells them:"] = "Für diesen Reiter brauchst du 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} und 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Gewürze werden von Händlern für Kochbedarf verkauft, Phiolen von Händlern für Alchimiebedarf und die Flaschen von Barkeepern. Die Händler in den Startgebieten verkaufen keine scharfen Gewürze oder Bleiphiolen, kauf sie also in einer Hauptstadt. Öffne unten deine Fraktion, um zu sehen, wer sie verkauft:",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} and {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices} und {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}",
  ["Orgrimmar: {n:0:horde:Xen'to} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Naal Mistrunner}"] = "Orgrimmar: {n:0:horde:Xen'to} Unterstadt: {n:0:horde:Felicia Doan} Donnerfels: {n:0:horde:Naal Mistrunner}",
  ["Orgrimmar: {n:0:horde:Kor'geld} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Mani Winterhoof}"] = "Orgrimmar: {n:0:horde:Kor'geld} Unterstadt: {n:0:horde:Felicia Doan} Donnerfels: {n:0:horde:Mani Winterhoof}",
  ["Orgrimmar: {n:5611::Barkeep Morag} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "Orgrimmar: {n:5611::Barkeep Morag} Beutebucht: {n:2832::Nixxrax Fillamug}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Emrul Riknussun} Darnassus: {n:0:alliance:Mythrin'dir}"] = "Sturmwind: {n:0:alliance:Edna Mullby} Eisenschmiede: {n:0:alliance:Emrul Riknussun} Darnassus: {n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Gwina Stonebranch} Darnassus: {n:0:alliance:Mythrin'dir}"] = "Sturmwind: {n:0:alliance:Edna Mullby} Eisenschmiede: {n:0:alliance:Gwina Stonebranch} Darnassus: {n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:277::Roberto Pupellyverbos} and {n:1328::Elly Langston} Ironforge: {n:5570::Bruuk Barleybeard} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "Sturmwind: {n:277::Roberto Pupellyverbos} und {n:1328::Elly Langston} Eisenschmiede: {n:5570::Bruuk Barleybeard} Beutebucht: {n:2832::Nixxrax Fillamug}",
  ["54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Spider Ichor, 54 Mild Spices, 54 Bottle of Dalaran Noir"] = "54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Spider Ichor, 54 Milde Gewürze, 54 Bottle of Dalaran Noir",
  ["31x {s:1244433:inv_potion_51:Healing Potion} - 31 Bruiseweed, 31 Hot Spices, 31 Leaded Vial"] = "31x {s:1244433:inv_potion_51:Healing Potion} - 31 Beulengras, 31 Scharfe Gewürze, 31 Bleiphiole",
  ["Expert First Aid (150-225)"] = "Erste Hilfe (Experte) (150-225)",
  ["{b}Learn {s:7928:inv_misc_bandage_01:Silk Bandage} from your trainer before you leave{/b}, it's the last recipe the trainers teach."] = "{b}Lern {s:7928:inv_misc_bandage_01:Silk Bandage} bei deinem Lehrer, bevor du gehst{/b}, es ist das letzte Rezept, das die Lehrer beibringen.",
  ["How to learn Expert First Aid"] = "So erlernst du Erste Hilfe (Experte)",
  ["To train past 150, buy the {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} book from {n:0:alliance:Deneb Walker} (Alliance) in Arathi Highlands or {n:0:horde:Balai Lok'Wein} (Horde) in Dustwallow Marsh. The book has {b}no level requirement{/b}, you only need First Aid 125."] = "Um über 150 hinauszukommen, kauf das Buch {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} bei {n:0:alliance:Deneb Walker} (Allianz) im Arathihochland oder {n:0:horde:Balai Lok'Wein} (Horde) in den Düstermarschen. Das Buch hat {b}keine Stufenvoraussetzung{/b}, du brauchst nur Erste Hilfe 125.",
  ["They also sell the next two manuals, so {b}buy all three{/b} while you are there, or get them from the Auction House if you are low level:"] = "Sie verkaufen auch die nächsten beiden Handbücher, {b}kauf also alle drei{/b}, wenn du schon dort bist, oder hol sie dir im Auktionshaus, wenn du niedrigstufig bist:",
  ["47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Silk Cloth"] = "47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Seidenstoff",
  ["47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Silk Cloth"] = "47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Seidenstoff",
  ["Use the Manual: Heavy Silk Bandage first to learn the recipe."] = "Benutze zuerst das Handbuch: Schwerer Seidenverband, um das Rezept zu lernen.",
  ["19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Mageweave Cloth"] = "19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Magiestoff",
  ["Use the Manual: Mageweave Bandage first to learn the recipe."] = "Benutze zuerst das Handbuch: Magiestoffverband, um das Rezept zu lernen.",
  ["Artisan First Aid (225-300)"] = "Erste Hilfe (Fachmann) (225-300)",
  ["You can train First Aid past 225 by completing the Triage quest. It requires {b}First Aid 225{/b} and {b}level 35{/b}, even though the quest itself is level 45."] = "Du kannst Erste Hilfe über 225 hinaus erlernen, indem du die Quest Triage abschließt. Sie erfordert {b}Erste Hilfe 225{/b} und {b}Stufe 35{/b}, obwohl die Quest selbst Stufe 45 ist.",
  ["{b}Bring everything you need in order to skill up to 275{/b}, as you will learn the next two bandages from the same doctor, so bring around 90 Mageweave Cloth and 20 Runecloth with you."] = "{b}Bring alles mit, was du brauchst, um auf 275 zu kommen{/b}, denn die nächsten beiden Verbände lernst du beim selben Doktor. Bring also etwa 90 Magiestoff und 20 Runenstoff mit.",
  ["The {q:6622::Triage} quest is given by {n:0:horde:Doctor Gregory Victor} in Arathi Highlands at Hammerfall."] = "Die Quest {q:6622::Triage} gibt {n:0:horde:Doctor Gregory Victor} in Hammerfall im Arathihochland.",
  ["Hammerfall, Arathi Highlands"] = "Hammerfall, Arathihochland",
  ["The {q:6624::Triage} quest is given by {n:0:alliance:Doctor Gustaf VanHowzen} in Dustwallow Marsh at Theramore."] = "Die Quest {q:6624::Triage} gibt {n:0:alliance:Doctor Gustaf VanHowzen} in Theramore in den Düstermarschen.",
  ["Foothold Citadel, Dustwallow Marsh"] = "Foothold Citadel, Düstermarschen",
  ["You get a stack of triage bandages and have to save 15 patients, heal the critically injured ones first."] = "Du bekommst einen Stapel Triageverbände und musst 15 Patienten retten, heile zuerst die kritisch Verletzten.",
  ["How to complete the Triage quest"] = "So schließt du die Quest Triage ab",
  ["Make sure you have about 10 minutes of spare time to do this with no interruptions."] = "Sorg dafür, dass du etwa 10 Minuten Zeit hast, um das ohne Unterbrechungen zu machen.",
  ["Press CTRL + V to show the health bars over the patients, or turn on \"Show NPC names\" in the interface options."] = "Drück STRG + V, um die Lebensbalken über den Patienten anzuzeigen, oder aktiviere \"NPC-Namen anzeigen\" in den Interfaceoptionen.",
  ["Zoom the camera out to third person, so you see as much of the room as you can."] = "Zoom die Kamera in die Third-Person-Ansicht heraus, damit du so viel vom Raum siehst wie möglich.",
  ["Put the Triage Bandages the doctor gave you on your action bar and use those, not your own bandages."] = "Leg die Triageverbände, die dir der Doktor gegeben hat, auf deine Aktionsleiste und benutze diese, nicht deine eigenen Verbände.",
  ["Stand in the middle of the room."] = "Stell dich in die Mitte des Raums.",
  ["When you see another patient, left-click on them to pre-select them, and as soon as your current heal has finished click the bandages in your action bar and the pre-selected one will begin to heal. Saves valuable seconds this way."] = "Wenn du einen weiteren Patienten siehst, klick ihn mit links an, um ihn vorab auszuwählen, und sobald deine aktuelle Heilung fertig ist, klick auf die Verbände in deiner Aktionsleiste, dann beginnt die Heilung des vorab ausgewählten. So sparst du wertvolle Sekunden.",
  ["When you have saved 15 patients, {b}turn in the quest immediately{/b}. I failed it on my druid because I waited, six patients died in the meantime and the quest went from completed to failed."] = "Wenn du 15 Patienten gerettet hast, {b}gib die Quest sofort ab{/b}. Mit meinem Druiden ist sie mir misslungen, weil ich gewartet habe. In der Zwischenzeit sind sechs Patienten gestorben und die Quest ging von abgeschlossen auf fehlgeschlagen.",
  ["29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Mageweave Cloth"] = "29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Magiestoff",
  ["30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Mageweave Cloth"] = "30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Magiestoff",
  ["The doctor teaches it at 240."] = "Der Doktor lehrt es bei 240.",
  ["20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Runecloth"] = "20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Runenstoff",
  ["The doctor teaches it at 260."] = "Der Doktor lehrt es bei 260.",
  ["30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Golden Sansam, 90 Soothing Spices, 30 Crystal Vial"] = "30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Goldener Sansam, 90 Beruhigende Gewürze, 30 Kristallphiole",
  ["The recipe is {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Check the Auction House first, and buy it there if it costs less than 8g."] = "Das Rezept ist {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Schau zuerst im Auktionshaus nach und kauf es dort, wenn es weniger als 8g kostet.",
  ["If it costs more, you can buy it from {n:0::Pexmit} in Mount Hyjal for 8g, but he can be tricky to find."] = "Wenn es mehr kostet, kannst du es bei {n:0::Pexmit} am Hyjal für 8g kaufen, er kann aber schwer zu finden sein.",
  ["Horde players can also get it from Ortak Lomgok in Elderwild, Mount Hyjal, as the reward for {q:96622::A Rest Without Pain}. You have to complete his {q:96616::Herbs for the Bruised and Weary} quest first."] = "Spieler der Horde können es auch bei Ortak Lomgok in Elderwild am Hyjal als Belohnung für {q:96622::A Rest Without Pain} bekommen. Du musst zuerst seine Quest {q:96616::Herbs for the Bruised and Weary} abschließen.",
  ["This WoW Forever Fishing leveling guide will show you the fastest way to level Fishing from 1 to 300. Fishing takes a lot of patience, you will have to catch a lot of fish to get from start to finish, but you don't need any materials, only a Fishing Pole and a few lures."] = "Dieser WoW-Forever-Leitfaden für Angeln zeigt dir den schnellsten Weg, Angeln von 1 auf 300 zu leveln. Angeln erfordert viel Geduld, du musst von Anfang bis Ende viele Fische fangen, aber du brauchst keine Materialien, nur eine Angel und ein paar Köder.",
  ["Below you will find every Fishing trainer by starting zone and capital city, where to fish for each skill range, and how to learn Expert and Artisan Fishing. If you haven't leveled Cooking yet, use my Fishing and Cooking leveling guide instead, because the fish you catch will level your Cooking at the same time:"] = "Unten findest du alle Angellehrer nach Startgebiet und Hauptstadt, wo du für jeden Fertigkeitsbereich angelst und wie du Angeln (Experte) und (Fachmann) erlernst. Wenn du Kochkunst noch nicht gelevelt hast, nimm stattdessen meinen Leitfaden für Angeln und Kochkunst, denn die gefangenen Fische leveln gleichzeitig deine Kochkunst:",
  ["Fishing Trainer Locations"] = "Standorte der Angellehrer",
  ["Apprentice Fishing has no level requirement in Forever, so you can learn it on a fresh character. Every trainer also teaches Journeyman Fishing, so you don't have to find a different trainer at 50."] = "Angeln (Lehrling) hat in Forever keine Stufenvoraussetzung, du kannst es also schon mit einem neuen Charakter erlernen. Jeder Lehrer bringt dir auch Angeln (Geselle) bei, du musst bei 50 also keinen anderen Lehrer suchen.",
  ["Undercity: {n:0:horde:Armand Cromwell}"] = "Unterstadt: {n:0:horde:Armand Cromwell}",
  ["Thunder Bluff: {n:0:horde:Kah Mistrunner}"] = "Donnerfels: {n:0:horde:Kah Mistrunner}",
  ["Every starting zone has a Fishing trainer, and they all stand next to water, so you can start fishing right away."] = "Jedes Startgebiet hat einen Angellehrer, und alle stehen am Wasser, du kannst also sofort mit dem Angeln anfangen.",
  ["{n:0:horde:Lau'Tiki} on the coast at Sen'jin Village"] = "{n:0:horde:Lau'Tiki} an der Küste beim Dorf Sen'jin",
  ["{n:0:horde:Uthan Stillwater} at Stonebull Lake, next to Bloodhoof Village"] = "{n:0:horde:Uthan Stillwater} am Steinbullensee, neben dem Dorf der Bluthufe",
  ["{n:0:horde:Clyde Kellen} at Brightwater Lake, east of Brill"] = "{n:0:horde:Clyde Kellen} am Brightwater Lake, östlich von Brill",
  ["Stormwind City: {n:0:alliance:Arnold Leland}"] = "Sturmwind: {n:0:alliance:Arnold Leland}",
  ["Ironforge: {n:0:alliance:Grimnur Stonebrand}"] = "Eisenschmiede: {n:0:alliance:Grimnur Stonebrand}",
  ["{n:0:alliance:Lee Brown} at Crystal Lake, east of Goldshire"] = "{n:0:alliance:Lee Brown} am Kristallsee, östlich von Goldhain",
  ["{n:0:alliance:Paxton Ganter} at Iceflow Lake, on the way to Gnomeregan"] = "{n:0:alliance:Paxton Ganter} am Iceflow Lake, auf dem Weg nach Gnomeregan",
  ["{n:0:alliance:Androl Oakhand} in Rut'theran Village, on the shore next to the dock"] = "{n:0:alliance:Androl Oakhand} in Rut'theran, am Ufer neben dem Steg",
  ["You can find every Fishing trainer for Horde and Alliance on my WoW Forever Fishing Trainers page."] = "Alle Angellehrer für Horde und Allianz findest du auf meiner Seite zu den WoW-Forever-Angellehrern.",
  ["How to Fish in WoW Forever (1-75)"] = "So angelst du in WoW Forever (1-75)",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a few {i:6529:inv_misc_orb_03:Shiny Bauble} from a Fishing Supply or Trade Supply vendor. In the capital cities they stand next to the trainer, for every other zone open your faction below:"] = "Kauf eine {i:6256:inv_fishingpole_02:Fishing Pole} und ein paar {i:6529:inv_misc_orb_03:Shiny Bauble} bei einem Händler für Angelbedarf oder Handwerkswaren. In den Hauptstädten stehen sie neben dem Lehrer, für alle anderen Gebiete öffne unten deine Fraktion:",
  ["{n:0:horde:Zansoa} in Sen'jin Village"] = "{n:0:horde:Zansoa} im Dorf Sen'jin",
  ["{n:0:horde:Martine Tramblay} at the Death's Watch Waystation, south-east of Brill"] = "{n:0:horde:Martine Tramblay} an der Death's Watch Waystation, südöstlich von Brill",
  ["{n:0:horde:Shankys}, next to the Fishing trainer"] = "{n:0:horde:Shankys}, neben dem Angellehrer",
  ["{n:0:horde:Lizbeth Cromwell}, next to the Fishing trainer"] = "{n:0:horde:Lizbeth Cromwell}, neben dem Angellehrer",
  ["{n:0:horde:Sewa Mistrunner}, next to the Fishing trainer"] = "{n:0:horde:Sewa Mistrunner}, neben dem Angellehrer",
  ["{n:0:horde:Wik'Tar} in Zoram'gar Outpost"] = "{n:0:horde:Wik'Tar} im Außenposten Zoram'gar",
  ["{n:0:horde:Katoom the Angler}, the Fishing trainer in Revantusk Village"] = "{n:0:horde:Katoom the Angler}, der Angellehrer in Revantusk Village",
  ["{n:0:alliance:Gretta Ganter} at Iceflow Lake"] = "{n:0:alliance:Gretta Ganter} am Iceflow Lake",
  ["{n:0:alliance:Nessa Shadowsong} in Rut'theran Village"] = "{n:0:alliance:Nessa Shadowsong} in Rut'theran",
  ["{n:0:alliance:Catherine Leland}, next to the Fishing trainer"] = "{n:0:alliance:Catherine Leland}, neben dem Angellehrer",
  ["{n:0:alliance:Tansy Puddlefizz}, next to the Fishing trainer"] = "{n:0:alliance:Tansy Puddlefizz}, neben dem Angellehrer",
  ["{n:0:alliance:Voloren}, next to the Fishing trainer"] = "{n:0:alliance:Voloren}, neben dem Angellehrer",
  ["{n:0:alliance:Khara Deepwater} at the Loch"] = "{n:0:alliance:Khara Deepwater} am Loch",
  ["{n:0:alliance:Stuart Fleming} in Menethil Harbor"] = "{n:0:alliance:Stuart Fleming} im Hafen von Menethil",
  ["Redridge Mountains"] = "Rotkammgebirge",
  ["{n:0:alliance:Vernon Hale} at Lake Everstill"] = "{n:0:alliance:Vernon Hale} am Lake Everstill",
  ["{n:0:alliance:Lindea Rabonne} in Southshore"] = "{n:0:alliance:Lindea Rabonne} in Süderstade",
  ["Open the Professions window."] = "Öffne das Berufefenster.",
  ["Click on the {b}hammer button{/b} in the row of buttons on the right side of your screen, {b}NOT the Fishing tab{/b}."] = "Klick auf den {b}Hammer-Button{/b} in der Button-Reihe rechts auf deinem Bildschirm, {b}NICHT auf den Angeln-Reiter{/b}.",
  ["Drag the {s:7731:trade_fishing:Fishing} button from the Fishing box to your action bar."] = "Zieh den Button {s:7731:trade_fishing:Fishing} aus dem Angeln-Bereich auf deine Aktionsleiste.",
  ["Equip your Fishing Pole and apply the {i:6529:inv_misc_orb_03:Shiny Bauble} lure."] = "Leg deine Angel an und bring den Köder {i:6529:inv_misc_orb_03:Shiny Bauble} an.",
  ["Go to any starting zone and look for a lake, pond or river. Stand in front of the water and press the fishing button."] = "Geh in ein beliebiges Startgebiet und such einen See, Teich oder Fluss. Stell dich vor das Wasser und drück den Angeln-Button.",
  ["Mouse over the bobber in the water, and when it splashes, right-click on it."] = "Fahr mit der Maus über den Schwimmer im Wasser, und wenn er platscht, klick ihn mit rechts an.",
  ["Fish until you reach Fishing 75."] = "Angle, bis du Angeln 75 erreichst.",
  ["{b}Starting zones:{/b} Dun Morogh, Durotar, Elwynn Forest, Mulgore, Teldrassil, Tirisfal Glades, Zephras Isle"] = "{b}Startgebiete:{/b} Dun Morogh, Durotar, Wald von Elwynn, Mulgore, Teldrassil, Tirisfal, Zephras Isle",
  ["{b}Remember, starting zones do not include capital cities!{/b}"] = "{b}Denk daran, Hauptstädte zählen nicht zu den Startgebieten!{/b}",
  ["If you can't find the Fishing button, I show it with pictures in my how to fish in WoW Forever guide."] = "Wenn du den Angeln-Button nicht findest, zeige ich ihn mit Bildern in meinem Leitfaden zum Angeln in WoW Forever.",
  ["Go back to your trainer and learn Journeyman Fishing. It requires {b}Fishing 50{/b} and {b}level 10{/b}."] = "Geh zurück zu deinem Lehrer und erlerne Angeln (Geselle). Es erfordert {b}Angeln 50{/b} und {b}Stufe 10{/b}.",
  ["Fish until 150 in one of the capital cities:"] = "Angle bis 150 in einer der Hauptstädte:",
  ["You can fish in any of these zones too: The Barrens, Darkshore, Ironforge, Loch Modan, Silverpine Forest, Westfall."] = "Du kannst auch in diesen Gebieten angeln: Brachland, Dunkelküste, Eisenschmiede, Loch Modan, Silberwald, Westfall.",
  ["If the fish keep getting away, buy {i:6530:inv_misc_monstertail_03:Nightcrawlers} from a Fishing Supply vendor. They need Fishing 50."] = "Wenn dir die Fische ständig entkommen, kauf {i:6530:inv_misc_monstertail_03:Nightcrawlers} bei einem Händler für Angelbedarf. Sie erfordern Angeln 50.",
  ["You can learn Expert Fishing from the {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} book (requires {b}level 20{/b} and {b}Fishing 125{/b}) sold by {n:0::Old Man Heming} at Booty Bay in Stranglethorn Vale. He is in the middle of Booty Bay at the very bottom, near the fishing sign. You can also buy the book from the Auction House."] = "Angeln (Experte) kannst du mit dem Buch {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} erlernen (erfordert {b}Stufe 20{/b} und {b}Angeln 125{/b}), das von {n:0::Old Man Heming} in Beutebucht im Schlingendorntal verkauft wird. Er ist in der Mitte von Beutebucht ganz unten, in der Nähe des Angelschilds. Du kannst das Buch auch im Auktionshaus kaufen.",
  ["Buy a bunch of {i:6532:inv_misc_gem_variety_02:Bright Baubles} from Old Man Heming before you leave."] = "Kauf bei Old Man Heming einen Haufen {i:6532:inv_misc_gem_variety_02:Bright Baubles}, bevor du gehst.",
  ["Go to {b}Dustwallow Marsh{/b}, apply {i:6532:inv_misc_gem_variety_02:Bright Baubles} to your Fishing Pole and fish until 225."] = "Geh in die {b}Düstermarschen{/b}, bring {i:6532:inv_misc_gem_variety_02:Bright Baubles} an deiner Angel an und angle bis 225.",
  ["I recommend fishing in Dustwallow because the Artisan Fishing quest starts there, but you can fish in these zones too: Alterac Mountains, Arathi Highlands, Desolace, Stranglethorn Vale, Swamp of Sorrows, and Thousand Needles."] = "Ich empfehle, in den Düstermarschen zu angeln, weil die Quest für Angeln (Fachmann) dort beginnt, aber du kannst auch in diesen Gebieten angeln: Alteracgebirge, Arathihochland, Desolace, Schlingendorntal, Sümpfe des Elends und Tausend Nadeln.",
  ["Learning Artisan Fishing"] = "Angeln (Fachmann) erlernen",
  ["To train Fishing past 225, you must complete the quest {q:6607::Nat Pagle, Angler Extreme} from {n:0::Nat Pagle} in Dustwallow Marsh."] = "Um Angeln über 225 hinaus zu erlernen, musst du die Quest {q:6607::Nat Pagle, Angler Extreme} von {n:0::Nat Pagle} in den Düstermarschen abschließen.",
  ["It requires {b}level 35{/b} and {b}Fishing 225{/b}."] = "Sie erfordert {b}Stufe 35{/b} und {b}Angeln 225{/b}.",
  ["To complete the quest, you have to catch 4 quest fish in four different zones:"] = "Um die Quest abzuschließen, musst du 4 Questfische in vier verschiedenen Gebieten fangen:",
  ["Use {i:6532:inv_misc_gem_variety_02:Bright Baubles} when you are fishing in {b}Feralas{/b} to stop the fish from getting away. You don't need any lures in the other zones because your Fishing skill is high enough by then."] = "Benutze {i:6532:inv_misc_gem_variety_02:Bright Baubles}, wenn du in {b}Feralas{/b} angelst, damit dir die Fische nicht entkommen. In den anderen Gebieten brauchst du keine Köder, weil deine Angelfertigkeit dann hoch genug ist.",
  ["Nat Pagle, Angler Extreme quest"] = "Quest Nat Pagle, Angler Extreme",
  ["After you completed the quest, fish in any of these zones:"] = "Wenn du die Quest abgeschlossen hast, angle in einem dieser Gebiete:",
  ["Western Plaguelands"] = "Westliche Pestländer",
  ["You will have to use {i:6532:inv_misc_gem_variety_02:Bright Baubles} in these zones to stop the fish from getting away!"] = "In diesen Gebieten musst du {i:6532:inv_misc_gem_variety_02:Bright Baubles} benutzen, damit dir die Fische nicht entkommen!",
  ["This WoW Forever Lockpicking leveling guide will show you the fastest way to level Lockpicking from 1 to 300, with the best place to pick locks for each skill range."] = "Dieser WoW-Forever-Leitfaden für Schlossknacken zeigt dir den schnellsten Weg, Schlossknacken von 1 auf 300 zu leveln, mit dem besten Ort zum Schlossknacken für jeden Fertigkeitsbereich.",
  ["Max Lockpicking Skill by Level"] = "Maximale Schlossknackfertigkeit nach Stufe",
  ["{b}Your Lockpicking skill can't go higher than 5 times your level{/b}, so you have to level your character to level Lockpicking. This is the level you need for each part of the guide:"] = "{b}Deine Schlossknackfertigkeit kann nicht höher sein als das 5-Fache deiner Stufe{/b}, du musst also deinen Charakter leveln, um Schlossknacken zu leveln. Das ist die Stufe, die du für jeden Teil des Leitfadens brauchst:",
  ["Your level"] = "Deine Stufe",
  ["Max Lockpicking skill"] = "Maximale Schlossknackfertigkeit",
  ["I originally made this guide with my rogue in Classic. In WoW Forever I'm leveling a hunter, so a friend of mine checks the spots on his rogue, and he confirmed the Horde 1-100 part. Readers told me where they leveled from 150 to 300. I'm assuming the rest is the same as in Classic, but I will confirm it later. If something looks off, send me feedback."] = "Ursprünglich habe ich diesen Leitfaden mit meinem Schurken in Classic erstellt. In WoW Forever levele ich einen Jäger, daher prüft ein Freund die Orte mit seinem Schurken, und er hat den Horde-Teil 1-100 bestätigt. Leser haben mir erzählt, wo sie von 150 bis 300 gelevelt haben. Ich gehe davon aus, dass der Rest wie in Classic ist, werde es aber später bestätigen. Wenn dir etwas falsch vorkommt, schick mir Feedback.",
  ["Go to the ship near Ratchet in The Barrens. The Buccaneer's Strongboxes there respawn after a few seconds, so even two rogues can skill up there at the same time. {b}They are inside the ship{/b}, at the spot marked on the map below."] = "Geh zum Schiff bei Ratschet im Brachland. Die Buccaneer's Strongboxes dort respawnen nach ein paar Sekunden, sodass sogar zwei Schurken gleichzeitig dort skillen können. {b}Sie sind im Schiff{/b}, an der auf der Karte unten markierten Stelle.",
  ["There is another chest at the bottom of the ship called The Jewel of the Southsea. Don't open it if you are low level, because it spawns a mob that will kill you."] = "Unten im Schiff gibt es noch eine Truhe namens The Jewel of the Southsea. Öffne sie nicht, wenn du niedrigstufig bist, denn sie lässt einen Gegner erscheinen, der dich tötet.",
  ["There are a bunch of Practice Lockboxes in Redridge Mountains, north of Lake Everstill. They respawn really fast, so you can get to 100 there easily."] = "Nördlich des Lake Everstill im Rotkammgebirge gibt es einen Haufen Übungsschließkassetten. Sie respawnen sehr schnell, du kommst dort also leicht auf 100.",
  ["Go to Zoram Strand in Ashenvale and look for Waterlogged Footlockers along the shore, on land."] = "Geh zum Strand von Zoram im Eschental und such entlang des Ufers an Land nach Waterlogged Footlockers.",
  ["Go to Angor Fortress in Badlands. There are two kinds of footlockers there, the Battered Footlockers upstairs need 150, and the Dented Footlockers downstairs need {b}175{/b}."] = "Geh zur Festung Angor im Ödland. Dort gibt es zwei Arten von Schließkisten, die Battered Footlockers oben erfordern 150 und die Dented Footlockers unten {b}175{/b}.",
  ["The footlockers downstairs give a skill point every time until 215, so you can stay here until 225."] = "Die Schließkisten unten geben bis 215 jedes Mal einen Fertigkeitspunkt, du kannst also bis 225 hierbleiben.",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give any skill."] = "Spar dir das Taschendiebstahl bei den Gegnern dort, denn ihre Kassetten sind zu niedrigstufig, um Fertigkeit zu geben.",
  ["Go to The Slag Pit, the cave in the middle of Searing Gorge, and pick the footlockers there. The ones on the upper part give skill points all the way to 300. They stay yellow until 290 and turn green after that, so the last 10 points take longer."] = "Geh zur Schlackengrube, der Höhle in der Mitte der Sengenden Schlucht, und knack dort die Schließkisten. Die im oberen Teil geben bis 300 Fertigkeitspunkte. Sie bleiben bis 290 gelb und werden danach grün, die letzten 10 Punkte dauern also länger.",
  ["{b}There are two kinds of Dented Footlockers in the Slag Pit{/b}, with the same name. The ones on the lower part need 200 and the ones on the upper part need 225. Pick both until the lower ones stop giving skill points, then stay on the upper part."] = "{b}In der Schlackengrube gibt es zwei Arten von Dented Footlockers{/b} mit demselben Namen. Die im unteren Teil erfordern 200 und die im oberen Teil 225. Knack beide, bis die unteren keine Fertigkeitspunkte mehr geben, dann bleib im oberen Teil.",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give much skill."] = "Spar dir das Taschendiebstahl bei den Gegnern dort, denn ihre Kassetten sind zu niedrigstufig, um viel Fertigkeit zu geben.",
  ["This WoW Forever camping guide will show you how camping works, how to make a campfire and every camp item and buff of every profession."] = "Dieser WoW-Forever-Lagerleitfaden zeigt dir, wie das Lagern funktioniert, wie du ein Lagerfeuer machst und alle Lagergegenstände und Buffs jedes Berufs.",
  ["Three night elves sitting at a campfire in Dolanaar, Teldrassil, in WoW Forever"] = "Drei Nachtelfen sitzen an einem Lagerfeuer in Dolanaar, Teldrassil, in WoW Forever",
  ["How Camping Works"] = "So funktioniert das Lagern",
  ["Someone puts down a campfire, and everyone around it can place a camp item of their own profession. {b}Sit (/sit) next to the fire for a minute{/b}, you will see a buff start counting down. Then you get Camp Benefits, one buff with everything the camp items give, for an hour."] = "Jemand stellt ein Lagerfeuer auf, und alle drumherum können einen Lagergegenstand ihres eigenen Berufs platzieren. {b}Setz dich (/sit) eine Minute ans Feuer{/b}, dann siehst du einen Buff, der herunterzählt. Danach bekommst du Camp Benefits, einen Buff mit allem, was die Lagergegenstände geben, für eine Stunde.",
  ["{b}Each player can place one camp item{/b}, and it puts all your camp items on a 1 hour cooldown. A campfire holds 3, 5 or 10 camp items, depending on how big it is (see How to Make a Campfire below). The buffs are weaker class buffs and don't stack with them."] = "{b}Jeder Spieler kann einen Lagergegenstand platzieren{/b}, und das setzt alle deine Lagergegenstände auf 1 Stunde Abklingzeit. Ein Lagerfeuer fasst 3, 5 oder 10 Lagergegenstände, je nach Größe (siehe So machst du ein Lagerfeuer unten). Die Buffs sind schwächere Klassenbuffs und stapeln sich nicht mit diesen.",
  ["The intro quests in the starting zones, The Great Outdoors and Camping 101, are optional, the buffs work without them. The quest givers' fires always give the Camp Tent's rested experience."] = "Die Einführungsquests in den Startgebieten, The Great Outdoors und Camping 101, sind optional, die Buffs funktionieren auch ohne sie. Die Feuer der Questgeber geben immer die Erholungserfahrung des Camp Tent.",
  ["How to Make a Campfire"] = "So machst du ein Lagerfeuer",
  ["Learn Cooking from any Cooking trainer, the Basic Campfire Kit comes with it at skill 1. {i:4470:inv_tradeskillitem_01:Simple Wood} is sold by the trade and general goods vendors in most towns. Open your Professions window (the hammer and pick button in the menu bar), craft the kit from 1 Simple Wood under Cooking, then use it from your bags to place the campfire."] = "Erlerne Kochkunst bei einem beliebigen Kochkunstlehrer, das Basic Campfire Kit bekommst du damit bei Fertigkeit 1. {i:4470:inv_tradeskillitem_01:Simple Wood} wird in den meisten Orten von Handwerkswaren- und Gemischtwarenhändlern verkauft. Öffne dein Berufefenster (der Hammer-und-Spitzhacke-Button in der Menüleiste), stell das Set unter Kochkunst aus 1 einfachem Holz her und benutze es dann aus deinen Taschen, um das Lagerfeuer aufzustellen.",
  ["{b}Tip:{/b} you don't have to carry Flint and Tinder and wood around any more, craft a stack of Basic Campfire Kits at home and carry only those, they take one bag slot. You can also hand them to others."] = "{b}Tipp:{/b} Du musst Feuerstein und Zunder und Holz nicht mehr mit dir herumtragen. Stell zu Hause einen Stapel Basic Campfire Kits her und trag nur diese mit, sie belegen einen Taschenplatz. Du kannst sie auch anderen geben.",
  ["The bigger campfires hold more camp items, but they need a Blueprint."] = "Die größeren Lagerfeuer fassen mehr Lagergegenstände, brauchen aber eine Blaupause.",
  ["The Expert Campfire Kit needs more Cooking to use than to learn (220 against 200). It's usually the other way around, so maybe it's a bug."] = "Das Expert Campfire Kit erfordert zum Benutzen mehr Kochkunst als zum Erlernen (220 statt 200). Normalerweise ist es umgekehrt, vielleicht ist es also ein Bug.",
  ["Learn at"] = "Erlernen bei",
  ["Use at"] = "Benutzen bei",
  ["Camp items"] = "Lagergegenstände",
  ["Made from"] = "Hergestellt aus",
  ["Comes with Cooking"] = "Kommt mit Kochkunst",
  ["{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Dropped by: {n:3673::Lord Serpentis} in Wailing Caverns"] = "{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Gedroppt von: {n:3673::Lord Serpentis} in den Höhlen des Wehklagens",
  ["{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} I don't know yet where it drops"] = "{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} Ich weiß noch nicht, wo sie droppt",
  ["Camp Items"] = "Lagergegenstände",
  ["Every profession has three camp items, at skill 20, 140 and 300 (Cooking has two), and each one replaces the one before. The tier 1 item comes from your profession trainer, {b}tier 2 and 3 need a Blueprint{/b}, a recipe item. The tier 2 and 3 blueprints drop from bosses, most of them in dungeons, the tabs show which one. Only the Herbalism one at 300 is not known yet."] = "Jeder Beruf hat drei Lagergegenstände, bei Fertigkeit 20, 140 und 300 (Kochkunst hat zwei), und jeder ersetzt den vorherigen. Der Gegenstand der Stufe 1 kommt von deinem Berufslehrer, {b}Stufe 2 und 3 brauchen eine Blaupause{/b}, einen Rezeptgegenstand. Die Blaupausen der Stufe 2 und 3 droppen von Bossen, die meisten in Dungeons, die Reiter zeigen welcher. Nur die für Kräuterkunde bei 300 ist noch unbekannt.",
  ["{b}Every item also gives the buff of the tier 1 item of its profession{/b}, so you never have to choose between a buff and a crafting station. A Master Forge still gives the Strength buff of the Sharpening Wheel. Whether a tier 3 item also gives what the tier 2 item gives (an anvil from a Master Forge) is not confirmed yet. The tabs only list what each tier adds."] = "{b}Jeder Gegenstand gibt auch den Buff des Gegenstands der Stufe 1 seines Berufs{/b}, du musst also nie zwischen einem Buff und einer Handwerksstation wählen. Eine Master Forge gibt weiterhin den Stärkebuff des Sharpening Wheel. Ob ein Gegenstand der Stufe 3 auch gibt, was der Gegenstand der Stufe 2 gibt (einen Amboss bei einer Master Forge), ist noch nicht bestätigt. Die Reiter listen nur auf, was jede Stufe hinzufügt.",
  ["Alchemy"] = "Alchimie",
  ["Blacksmithing"] = "Schmiedekunst",
  ["Enchanting"] = "Verzauberkunst",
  ["Engineering"] = "Ingenieurskunst",
  ["Leatherworking"] = "Lederverarbeitung",
  ["Tailoring"] = "Schneiderei",
  ["Skinning"] = "Kürschnerei",
  ["First Aid"] = "Erste Hilfe",
  ["Camp Item"] = "Lagergegenstand",
  ["What It Does"] = "Was er bewirkt",
  ["Mana regeneration buff, doesn't stack with Blessing of Wisdom"] = "Buff für Manaregeneration, stapelt sich nicht mit Segen der Weisheit",
  ["Trainer or the Camping 101 quest"] = "Lehrer oder die Quest Camping 101",
  ["A Fermenter, needed for a few Alchemy recipes"] = "Ein Fermenter, nötig für ein paar Alchimierezepte",
  ["{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Gedroppt von: {n:250657::Rath'mael} in den Ruinen von Lordaeron",
  ["An Alchemy Lab, needed for some Alchemy recipes"] = "Ein Alchimielabor, nötig für einige Alchimierezepte",
  ["{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} Gedroppt von: {n:10508::Ras Frostwhisper} in Scholomance",
  ["Strength buff, doesn't stack with Strength of Earth Totem"] = "Stärkebuff, stapelt sich nicht mit Totem der Erdstärke",
  ["An anvil"] = "Ein Amboss",
  ["{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} Dropped by: {n:1763::Gilnid} in The Deadmines"] = "{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} Gedroppt von: {n:1763::Gilnid} in den Todesminen",
  ["A Master Forge, needed for many Blacksmithing recipes"] = "Eine Master Forge, nötig für viele Schmiedekunstrezepte",
  ["{i:273113:inv_garrison_blueprints3:Blueprint: Master Forge} Dropped by: {n:8983::Golem Lord Argelmach} in Blackrock Depths"] = "{i:273113:inv_garrison_blueprints3:Blueprint: Master Forge} Gedroppt von: {n:8983::Golem Lord Argelmach} in den Schwarzfelstiefen",
  ["Armor, all stats and resistances buff, doesn't stack with Mark of the Wild"] = "Buff für Rüstung, alle Werte und Widerstände, stapelt sich nicht mit Mal der Wildnis",
  ["Better disenchanting"] = "Besseres Entzaubern",
  ["{i:273103:inv_garrison_blueprints3:Blueprint: Arcane Salvager} Dropped by: {n:246020::Shade of the Archmage} in the City of Dalaran"] = "{i:273103:inv_garrison_blueprints3:Blueprint: Arcane Salvager} Gedroppt von: {n:246020::Shade of the Archmage} in der Stadt Dalaran",
  ["An Arcane Forge, needed for some Enchanting recipes"] = "Eine Arkane Schmiede, nötig für einige Verzauberkunstrezepte",
  ["{i:273116:inv_garrison_blueprints3:Blueprint: Arcane Forge} Dropped by: {n:261809::Nanaya} in Kalimdor"] = "{i:273116:inv_garrison_blueprints3:Blueprint: Arcane Forge} Gedroppt von: {n:261809::Nanaya} in Kalimdor",
  ["Summons the {n:242498::Reagent Bot}, a vendor with class reagents and profession supplies for everyone at the camp"] = "Beschwört den {n:242498::Reagent Bot}, einen Händler mit Klassenreagenzien und Berufsbedarf für alle im Lager",
  ["Repairs for everyone at the camp"] = "Reparaturen für alle im Lager",
  ["{i:273092:inv_garrison_blueprints3:Blueprint: Repair Bot} Dropped by: {n:643::Sneed} in The Deadmines"] = "{i:273092:inv_garrison_blueprints3:Blueprint: Repair Bot} Gedroppt von: {n:643::Sneed} in den Todesminen",
  ["An Anarchist's Workbench, needed for some Engineering recipes"] = "Eine Anarchist's Workbench, nötig für einige Ingenieursrezepte",
  ["{i:273117:inv_garrison_blueprints3:Blueprint: Anarchist's Workbench} Dropped by: {n:11058::Ezra Grimm} in Stratholme"] = "{i:273117:inv_garrison_blueprints3:Blueprint: Anarchist's Workbench} Gedroppt von: {n:11058::Ezra Grimm} in Stratholme",
  ["Rested experience up to 5% of a level, once an hour (a debuff blocks it until then)"] = "Erholungserfahrung bis zu 5 % einer Stufe, einmal pro Stunde (bis dahin blockiert ein Debuff sie)",
  ["A Tanning Rack, needed for many Leatherworking recipes"] = "Ein Gerbgestell, nötig für viele Lederverarbeitungsrezepte",
  ["{i:273096:inv_garrison_blueprints3:Blueprint: Tanning Rack} Dropped by: {n:3886::Razorclaw the Butcher} in Shadowfang Keep"] = "{i:273096:inv_garrison_blueprints3:Blueprint: Tanning Rack} Gedroppt von: {n:3886::Razorclaw the Butcher} in Burg Schattenfang",
  ["A Sewing Machine, needed for many Leatherworking recipes"] = "Eine Nähmaschine, nötig für viele Lederverarbeitungsrezepte",
  ["{i:273121:inv_garrison_blueprints3:Blueprint: Sewing Machine} Dropped by: {n:10432::Vectus} in Scholomance"] = "{i:273121:inv_garrison_blueprints3:Blueprint: Sewing Machine} Gedroppt von: {n:10432::Vectus} in Scholomance",
  ["Spirit buff for players of your faction, doesn't stack with Divine Spirit. Horde and Alliance each have their own banner"] = "Willenskraftbuff für Spieler deiner Fraktion, stapelt sich nicht mit Göttlicher Willen. Horde und Allianz haben jeweils ihr eigenes Banner",
  ["A Spinning Wheel, needed for many Tailoring recipes"] = "Ein Spinnrad, nötig für viele Schneidereirezepte",
  ["{i:273099:inv_garrison_blueprints3:Blueprint: Spinning Wheel} Dropped by: {n:246017::Unstable Sentinel} in the City of Dalaran"] = "{i:273099:inv_garrison_blueprints3:Blueprint: Spinning Wheel} Gedroppt von: {n:246017::Unstable Sentinel} in der Stadt Dalaran",
  ["A Loom, needed for many Tailoring recipes"] = "Ein Webstuhl, nötig für viele Schneidereirezepte",
  ["{i:273124:inv_garrison_blueprints3:Blueprint: Loom} Dropped by: {n:10436::Baroness Anastari} in Stratholme"] = "{i:273124:inv_garrison_blueprints3:Blueprint: Loom} Gedroppt von: {n:10436::Baroness Anastari} in Stratholme",
  ["Intellect buff, doesn't stack with Arcane Intellect"] = "Intelligenzbuff, stapelt sich nicht mit Arkane Intelligenz",
  ["A Greenhouse that grows herbs from seeds you plant"] = "Ein Gewächshaus, in dem aus gepflanzten Samen Kräuter wachsen",
  ["{i:273106:inv_garrison_blueprints3:Blueprint: Greenhouse} Dropped by: {n:260325::Shadetooth} in Excavation Site: Wetlands"] = "{i:273106:inv_garrison_blueprints3:Blueprint: Greenhouse} Gedroppt von: {n:260325::Shadetooth} in Excavation Site: Wetlands",
  ["A Seed Hybridizer that multiplies seeds or combines them into rarer ones"] = "Ein Seed Hybridizer, der Samen vermehrt oder zu selteneren kombiniert",
  ["Melee Attack Power buff, doesn't stack with Blessing of Might"] = "Buff für Nahkampfangriffskraft, stapelt sich nicht mit Segen der Macht",
  ["Spawns a common mining node over time, and gives the Lodestone buff too"] = "Lässt mit der Zeit ein gewöhnliches Erzvorkommen erscheinen und gibt außerdem den Lodestone-Buff",
  ["{i:273097:inv_garrison_blueprints3:Blueprint: Rock Garden} Dropped by: {n:260326::Relic Guardian} in Excavation Site: Wetlands"] = "{i:273097:inv_garrison_blueprints3:Blueprint: Rock Garden} Gedroppt von: {n:260326::Relic Guardian} in Excavation Site: Wetlands",
  ["A Molten Foundry, needed for Smelt Heavy Thorium"] = "Eine Molten Foundry, nötig für Smelt Heavy Thorium",
  ["{i:273122:inv_garrison_blueprints3:Blueprint: Molten Foundry} Dropped by: {n:9156::Ambassador Flamelash} in Blackrock Depths"] = "{i:273122:inv_garrison_blueprints3:Blueprint: Molten Foundry} Gedroppt von: {n:9156::Ambassador Flamelash} in den Schwarzfelstiefen",
  ["+2% crit chance, doesn't stack with Moonkin Aura"] = "+2 % kritische Trefferchance, stapelt sich nicht mit Mondkin-Aura",
  ["A book anyone can read to learn Track Beasts"] = "Ein Buch, das jeder lesen kann, um Wildtiere aufspüren zu lernen",
  ["{i:273098:inv_garrison_blueprints3:Blueprint: Field Guide} Dropped by: {n:3671::Lady Anacondra} in Wailing Caverns"] = "{i:273098:inv_garrison_blueprints3:Blueprint: Field Guide} Gedroppt von: {n:3671::Lady Anacondra} in den Höhlen des Wehklagens",
  ["A workbench with 1 trap"] = "Eine Werkbank mit 1 Falle",
  ["{i:273109:inv_garrison_blueprints3:Blueprint: Trapper's Workbench} Dropped by: {n:10430::The Beast} in Upper Blackrock Spire and {n:3974::Houndmaster Loksey} in Scarlet Monastery"] = "{i:273109:inv_garrison_blueprints3:Blueprint: Trapper's Workbench} Gedroppt von: {n:10430::The Beast} in der Oberen Schwarzfelsspitze und {n:3974::Houndmaster Loksey} im Scharlachroten Kloster",
  ["Cooking has no tier 1 camp item, its first one is the campfire (see How to Make a Campfire above)."] = "Kochkunst hat keinen Lagergegenstand der Stufe 1, der erste ist das Lagerfeuer (siehe So machst du ein Lagerfeuer oben).",
  ["Stamina food for everyone at the camp"] = "Ausdauer-Essen für alle im Lager",
  ["{i:273102:inv_garrison_blueprints3:Blueprint: Cookie's Feast} Dropped by: {n:645::Cookie} in The Deadmines"] = "{i:273102:inv_garrison_blueprints3:Blueprint: Cookie's Feast} Gedroppt von: {n:645::Cookie} in den Todesminen",
  ["An Iron Oven, needed for the most advanced Cooking recipes"] = "Ein Eisenofen, nötig für die fortgeschrittensten Kochrezepte",
  ["{i:273115:inv_garrison_blueprints3:Blueprint: Iron Oven} Dropped by: {n:9736::Quartermaster Zigris} in Lower Blackrock Spire"] = "{i:273115:inv_garrison_blueprints3:Blueprint: Iron Oven} Gedroppt von: {n:9736::Quartermaster Zigris} in der Unteren Schwarzfelsspitze",
  ["Stamina buff, doesn't stack with Power Word: Fortitude"] = "Ausdauerbuff, stapelt sich nicht mit Machtwort: Seelenstärke",
  ["Healing potions and anti-venom"] = "Heiltränke und Gegengift",
  ["{i:273105:inv_garrison_blueprints3:Blueprint: Toxin Study} Dropped by: {n:4278::Commander Springvale} in Shadowfang Keep"] = "{i:273105:inv_garrison_blueprints3:Blueprint: Toxin Study} Gedroppt von: {n:4278::Commander Springvale} in Burg Schattenfang",
  ["Healing potions and poultices"] = "Heiltränke und Umschläge",
  ["{i:273118:inv_garrison_blueprints3:Blueprint: Plague Doctor's Laboratory} Dropped by: {n:11261::Doctor Theolen Krastinov} in Scholomance"] = "{i:273118:inv_garrison_blueprints3:Blueprint: Plague Doctor's Laboratory} Gedroppt von: {n:11261::Doctor Theolen Krastinov} in Scholomance",
  ["+8% all stats, doesn't stack with Blessing of Kings"] = "+8 % alle Werte, stapelt sich nicht mit Segen der Könige",
  ["Uncommon fish for 1 hour and Fishing lures"] = "Ungewöhnliche Fische für 1 Stunde und Angelköder",
  ["{i:273141:inv_garrison_blueprints3:Blueprint: Fishing Rack} Dropped by: {n:6243::Gelihast} in Blackfathom Deeps"] = "{i:273141:inv_garrison_blueprints3:Blueprint: Fishing Rack} Gedroppt von: {n:6243::Gelihast} in der Tiefschwarzen Grotte",
  ["Rare fish for 1 hour and Fishing lures"] = "Seltene Fische für 1 Stunde und Angelköder",
  ["{i:273119:inv_garrison_blueprints3:Blueprint: Fishing Hut} Dropped by: {n:5710::Jammal'an the Prophet} in the Sunken Temple"] = "{i:273119:inv_garrison_blueprints3:Blueprint: Fishing Hut} Gedroppt von: {n:5710::Jammal'an the Prophet} im Versunkenen Tempel",
  ["Crafting Stations: Tanning Rack, Loom and More"] = "Handwerksstationen: Gerbgestell, Webstuhl und mehr",
  ["A lot of recipes in WoW Forever need a crafting station nearby, like a Tanning Rack, a Spinning Wheel or a Loom. {b}I haven't found any of them out in the world{/b}, they only come from camps, so for a lot of higher level crafting you need a camp. The easiest way is a camp that already has the station, anyone at the fire can use it."] = "Viele Rezepte in WoW Forever brauchen eine Handwerksstation in der Nähe, wie ein Gerbgestell, ein Spinnrad oder einen Webstuhl. {b}Ich habe keine davon draußen in der Welt gefunden{/b}, sie stammen nur aus Lagern, daher brauchst du für viele höherstufige Herstellungen ein Lager. Am einfachsten ist ein Lager, das die Station schon hat, jeder am Feuer kann sie benutzen.",
  ["To place one yourself:"] = "So platzierst du selbst eine:",
  ["Get your profession to the skill in the table below."] = "Bring deinen Beruf auf die Fertigkeit in der Tabelle unten.",
  ["Get the station's Blueprint and learn it. The table shows where it drops, if we know it."] = "Besorg dir die Blaupause der Station und lern sie. Die Tabelle zeigt, wo sie droppt, falls bekannt.",
  ["Craft the station, put down a campfire and use the station from your bags next to it."] = "Stell die Station her, stell ein Lagerfeuer auf und benutze die Station daneben aus deinen Taschen.",
  ["Profession"] = "Beruf",
  ["Blueprint"] = "Blaupause",
  ["Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "Gedroppt von: {n:250657::Rath'mael} in den Ruinen von Lordaeron",
  ["Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "Gedroppt von: {n:10508::Ras Frostwhisper} in Scholomance",
  ["Dropped by: {n:8983::Golem Lord Argelmach} in Blackrock Depths"] = "Gedroppt von: {n:8983::Golem Lord Argelmach} in den Schwarzfelstiefen",
  ["Dropped by: {n:261809::Nanaya} in Kalimdor"] = "Gedroppt von: {n:261809::Nanaya} in Kalimdor",
  ["Dropped by: {n:11058::Ezra Grimm} in Stratholme"] = "Gedroppt von: {n:11058::Ezra Grimm} in Stratholme",
  ["Dropped by: {n:3886::Razorclaw the Butcher} in Shadowfang Keep"] = "Gedroppt von: {n:3886::Razorclaw the Butcher} in Burg Schattenfang",
  ["Dropped by: {n:10432::Vectus} in Scholomance"] = "Gedroppt von: {n:10432::Vectus} in Scholomance",
  ["Dropped by: {n:246017::Unstable Sentinel} in the City of Dalaran"] = "Gedroppt von: {n:246017::Unstable Sentinel} in der Stadt Dalaran",
  ["Dropped by: {n:10436::Baroness Anastari} in Stratholme"] = "Gedroppt von: {n:10436::Baroness Anastari} in Stratholme",
  ["Dropped by: {n:9156::Ambassador Flamelash} in Blackrock Depths"] = "Gedroppt von: {n:9156::Ambassador Flamelash} in den Schwarzfelstiefen",
  ["Dropped by: {n:9736::Quartermaster Zigris} in Lower Blackrock Spire"] = "Gedroppt von: {n:9736::Quartermaster Zigris} in der Unteren Schwarzfelsspitze",
  ["Merchant's Favor is a new currency in WoW Forever. You get it by filling Waylaid Crates with materials and handing them in at your faction's camp, Durotar Supply and Logistics for Horde and the Azeroth Commerce Authority for Alliance, and you spend it on the recipes, mount, pet, tabard and titles the camp vendors sell. Many recipes and the mount, pet and tabard also need reputation with the camp, which you get from Craftsman's Writs. This WoW Forever Merchant's Favor guide will show you where the camps are, how to earn Merchant's Favor and reputation, and every recipe the vendors sell."] = "Merchant's Favor ist eine neue Währung in WoW Forever. Du bekommst sie, indem du Waylaid Crates mit Materialien füllst und im Lager deiner Fraktion abgibst, bei Durotar Supply and Logistics für die Horde und bei der Azeroth Commerce Authority für die Allianz. Du gibst sie für die Rezepte, das Reittier, das Haustier, den Wappenrock und die Titel aus, die die Händler im Lager verkaufen. Viele Rezepte sowie Reittier, Haustier und Wappenrock erfordern außerdem Ruf beim Lager, den du über Craftsman's Writs bekommst. Dieser WoW-Forever-Leitfaden zu Merchant's Favor zeigt dir, wo die Lager sind, wie du Merchant's Favor und Ruf verdienst und jedes Rezept, das die Händler verkaufen.",
  ["How It Works"] = "So funktioniert es",
  ["Waylaid Crates drop randomly in the open world and in dungeons, and you can also buy them on the Auction House. You fill a crate with the materials it asks for and hand it in at your camp. For that you get Merchant's Favor, the currency you buy the recipes with."] = "Waylaid Crates droppen zufällig in der offenen Welt und in Dungeons, und du kannst sie auch im Auktionshaus kaufen. Du füllst eine Kiste mit den verlangten Materialien und gibst sie in deinem Lager ab. Dafür bekommst du Merchant's Favor, die Währung, mit der du die Rezepte kaufst.",
  ["Many recipes also need reputation with the camp. You earn reputation by doing Craftsman's Writs. You get a writ, craft the item it asks for and bring it to the customer."] = "Viele Rezepte erfordern auch Ruf beim Lager. Ruf verdienst du mit Craftsman's Writs. Du bekommst einen Auftrag, stellst den verlangten Gegenstand her und bringst ihn zum Kunden.",
  ["Where the Camps Are"] = "Wo die Lager sind",
  ["The Horde camp belongs to Durotar Supply and Logistics, and the Alliance camp belongs to the Azeroth Commerce Authority. Each camp has a recipe vendor for every crafting profession and Cooking, and both camps sell the same recipes (see Recipes by Profession below)."] = "Das Lager der Horde gehört zu Durotar Supply and Logistics, das Lager der Allianz zur Azeroth Commerce Authority. Jedes Lager hat einen Rezepthändler für jeden Herstellungsberuf und Kochkunst, und beide Lager verkaufen dieselben Rezepte (siehe Rezepte nach Beruf unten).",
  ["Three Corners, Redridge Mountains"] = "Three Corners, Rotkammgebirge",
  ["How to Earn Merchant's Favor"] = "So verdienst du Merchant's Favor",
  ["You earn Merchant's Favor by filling Waylaid Crates with materials and bringing them to your camp."] = "Merchant's Favor verdienst du, indem du Waylaid Crates mit Materialien füllst und zu deinem Lager bringst.",
  ["Merchant's Favor is per character, so every character has to earn its own."] = "Merchant's Favor gilt pro Charakter, jeder Charakter muss sich seinen also selbst verdienen.",
  ["Filling a Waylaid Crate"] = "Eine Waylaid Crate füllen",
  ["{b}Find a Waylaid Crate.{/b} They drop randomly in the open world and in dungeons, and {b}you can also buy them on the Auction House{/b}. Each one asks for one kind of material, for example {i:248684:inv_crate_07:Waylaid Crate: Apprentice Textiles}."] = "{b}Finde eine Waylaid Crate.{/b} Sie droppen zufällig in der offenen Welt und in Dungeons, und {b}du kannst sie auch im Auktionshaus kaufen{/b}. Jede verlangt eine Art von Material, zum Beispiel {i:248684:inv_crate_07:Waylaid Crate: Apprentice Textiles}.",
  ["Right-click it and fill it with one of the bundles it lists, for example 40 Linen Cloth or 20 Light Leather (see Waylaid Crates and Rewards below). You get a Sealed crate, and that one binds to you."] = "Klick sie mit rechts an und füll sie mit einem der aufgelisteten Bündel, zum Beispiel 40 Leinenstoff oder 20 leichtes Leder (siehe Waylaid Crates und Belohnungen unten). Du bekommst eine versiegelte Kiste, und die wird an dich gebunden.",
  ["Bring the Sealed crate to {n:0::Dokimi} at the Horde camp or {n:0::Marcy Baker} at the Alliance camp. You get Merchant's Favor and some silver for it."] = "Bring die versiegelte Kiste zu {n:0::Dokimi} im Lager der Horde oder {n:0::Marcy Baker} im Lager der Allianz. Dafür bekommst du Merchant's Favor und etwas Silber.",
  ["Waylaid Crates and Rewards"] = "Waylaid Crates und Belohnungen",
  ["When you fill a Waylaid Crate, it turns into a Sealed crate of the same rank and color. You hand that one in at your camp for the Merchant's Favor in the last column. There are also blue Sealed crates and a Sealed Elite Crate, but I don't know yet what they give."] = "Wenn du eine Waylaid Crate füllst, wird sie zu einer versiegelten Kiste desselben Rangs und derselben Farbe. Die gibst du in deinem Lager für das Merchant's Favor in der letzten Spalte ab. Es gibt auch blaue versiegelte Kisten und eine Sealed Elite Crate, aber ich weiß noch nicht, was sie geben.",
  ["The Textiles, Ore, Herbs and Curiosities crates take raw materials, and the Fabrics, Ingots and Parts crates take crafted ones."] = "Die Kisten Textiles, Ore, Herbs und Curiosities nehmen Rohmaterialien, die Kisten Fabrics, Ingots und Parts hergestellte.",
  ["{b}A crate needs only one of the bundles in its row, not all of them.{/b}"] = "{b}Eine Kiste braucht nur eines der Bündel in ihrer Zeile, nicht alle.{/b}",
  ["Apprentice"] = "Lehrling",
  ["Journeyman"] = "Geselle",
  ["Expert"] = "Experte",
  ["Artisan"] = "Fachmann",
  ["You need level 10 to open these."] = "Um diese zu öffnen, brauchst du Stufe 10.",
  ["You also get {m:2:s:} {m:50:c:} for a white crate and {m:5:s:} for a green one."] = "Du bekommst außerdem {m:2:s:} {m:50:c:} für eine weiße Kiste und {m:5:s:} für eine grüne.",
  ["Crate"] = "Kiste",
  ["Fill it with one of these"] = "Füll sie mit einem davon",
  ["Reward"] = "Belohnung",
  ["You also get {m:5:s:} for a white crate and {m:10:s:} for a green one."] = "Du bekommst außerdem {m:5:s:} für eine weiße Kiste und {m:10:s:} für eine grüne.",
  ["You need level 20 to open these."] = "Um diese zu öffnen, brauchst du Stufe 20.",
  ["You also get {m:7:s:} {m:50:c:} for a white crate and {m:15:s:} for a green one."] = "Du bekommst außerdem {m:7:s:} {m:50:c:} für eine weiße Kiste und {m:15:s:} für eine grüne.",
  ["You need level 35 to open these."] = "Um diese zu öffnen, brauchst du Stufe 35.",
  ["Not known yet"] = "Noch nicht bekannt",
  ["How to Earn Durotar Supply and Azeroth Commerce Authority Reputation"] = "So verdienst du Ruf bei Durotar Supply und der Azeroth Commerce Authority",
  ["{b}Handing in Sealed crates doesn't give reputation.{/b} Reputation with Durotar Supply and Logistics or the Azeroth Commerce Authority comes from Craftsman's Writs, crafting orders that you deliver to a customer somewhere in the world. After reaching Friendly, empty Waylaid Crates give reputation too (see Crate Returns after Friendly below)."] = "{b}Das Abgeben versiegelter Kisten gibt keinen Ruf.{/b} Ruf bei Durotar Supply and Logistics oder der Azeroth Commerce Authority kommt von Craftsman's Writs, Herstellungsaufträgen, die du einem Kunden irgendwo in der Welt lieferst. Ab Freundlich geben auch leere Waylaid Crates Ruf (siehe Kistenrückgabe ab Freundlich unten).",
  ["The first time you fill a crate or start a writ, you also get a {i:280180:inv_misc_note_03:Shipping Label}. It starts a quest to your camp, which gives 2,000 reputation and 50 Merchant's Favor."] = "Wenn du zum ersten Mal eine Kiste füllst oder einen Auftrag beginnst, bekommst du außerdem ein {i:280180:inv_misc_note_03:Shipping Label}. Es startet eine Quest zu deinem Lager, die 2.000 Ruf und 50 Merchant's Favor gibt.",
  ["A Journeyman writ gives 75 reputation, an Expert writ 125 and an Artisan writ 200. {b}You can do each writ once a day{/b}, and as many different writs a day as you want."] = "Ein Gesellenauftrag gibt 75 Ruf, ein Expertenauftrag 125 und ein Fachmannauftrag 200. {b}Jeden Auftrag kannst du einmal am Tag machen{/b}, und so viele verschiedene Aufträge am Tag, wie du willst.",
  ["{b}Get a Craftsman's Writ.{/b} In the open world and in dungeons they drop as a {i:262888:inv_misc_note_02:Sealed Journeyman's Writ}, {i:262889:inv_misc_note_02:Sealed Expert's Writ} or {i:262890:inv_misc_note_02:Sealed Artisan's Writ}, an envelope with a random writ of that rank inside. {b}You can also buy writs on the Auction House.{/b}"] = "{b}Besorg dir einen Craftsman's Writ.{/b} In der offenen Welt und in Dungeons droppen sie als {i:262888:inv_misc_note_02:Sealed Journeyman's Writ}, {i:262889:inv_misc_note_02:Sealed Expert's Writ} oder {i:262890:inv_misc_note_02:Sealed Artisan's Writ}, ein Umschlag mit einem zufälligen Auftrag dieses Rangs darin. {b}Du kannst Aufträge auch im Auktionshaus kaufen.{/b}",
  ["Right-click the writ to start its quest, for example {i:264047:inv_misc_note_01:Craftsman's Writ: Lesser Wizard's Robe}."] = "Klick den Auftrag mit rechts an, um seine Quest zu starten, zum Beispiel {i:264047:inv_misc_note_01:Craftsman's Writ: Lesser Wizard's Robe}.",
  ["Make the item it asks for or buy it on the Auction House. You don't need the profession yourself."] = "Stell den verlangten Gegenstand her oder kauf ihn im Auktionshaus. Du brauchst den Beruf nicht selbst.",
  ["Bring the item to the customer, your map shows where. The customer takes the item and the writ, and you get the reputation and a Coin Pouch with some silver. Writs don't give Merchant's Favor. {b}On the beta, the customer had no question mark over their head.{/b} I think it was a bug, so if you don't see one, right-click them anyway and the window to hand in the writ opens."] = "Bring den Gegenstand zum Kunden, deine Karte zeigt, wo. Der Kunde nimmt den Gegenstand und den Auftrag, und du bekommst den Ruf und einen Münzbeutel mit etwas Silber. Aufträge geben kein Merchant's Favor. {b}In der Beta hatte der Kunde kein Fragezeichen über dem Kopf.{/b} Ich halte das für einen Bug, wenn du also keins siehst, klick ihn trotzdem mit rechts an, dann öffnet sich das Fenster zum Abgeben des Auftrags.",
  ["Crate Returns after Friendly"] = "Kistenrückgabe ab Freundlich",
  ["At Friendly, you unlock the Uncertified Scribe in your camp, {n:0:horde:Kurvelk Shadowhoof} at the Horde camp and {n:0:alliance:Dianne Softstep} at the Alliance camp. Both sell the same two items:"] = "Bei Freundlich schaltest du den Uncertified Scribe in deinem Lager frei, {n:0:horde:Kurvelk Shadowhoof} im Lager der Horde und {n:0:alliance:Dianne Softstep} im Lager der Allianz. Beide verkaufen dieselben zwei Gegenstände:",
  ["Reputation"] = "Ruf",
  ["What it does"] = "Was er bewirkt",
  ["Friendly"] = "Freundlich",
  ["Turns an empty Waylaid Crate into 50 reputation, see the steps below."] = "Verwandelt eine leere Waylaid Crate in 50 Ruf, siehe die Schritte unten.",
  ["Honored"] = "Wohlwollend",
  ["Turns a Craftsman's Writ into a random writ of the same rank."] = "Verwandelt einen Craftsman's Writ in einen zufälligen Auftrag desselben Rangs.",
  ["{b}Buy a {i:262902:inv_10_inscription2_repcontracts_scroll_02_uprez_color5:Forged Delivery Receipt}{/b} from the Uncertified Scribe."] = "{b}Kauf eine {i:262902:inv_10_inscription2_repcontracts_scroll_02_uprez_color5:Forged Delivery Receipt}{/b} beim Uncertified Scribe.",
  ["Buy a Waylaid Crate on the Auction House. The receipt seems to work on any of them, so buy the cheapest one."] = "Kauf eine Waylaid Crate im Auktionshaus. Die Quittung scheint bei jeder zu funktionieren, kauf also die günstigste.",
  ["Use the receipt on the crate. You get a {i:262917:inv_crate_01:Notarized Shipping Container}."] = "Benutze die Quittung an der Kiste. Du bekommst einen {i:262917:inv_crate_01:Notarized Shipping Container}.",
  ["Hand the container to the same NPC who takes your Sealed crates. You get the reputation and 1 silver."] = "Gib den Container beim selben NPC ab, der deine versiegelten Kisten annimmt. Du bekommst den Ruf und 1 Silber.",
  ["Recipes by Profession"] = "Rezepte nach Beruf",
  ["Both camps, Durotar Supply and Logistics (Horde) and the Azeroth Commerce Authority (Alliance), sell the same recipes for Merchant's Favor. This is what each profession gets:"] = "Beide Lager, Durotar Supply and Logistics (Horde) und die Azeroth Commerce Authority (Allianz), verkaufen dieselben Rezepte für Merchant's Favor. Das bekommt jeder Beruf:",
  ["{b}Alchemy:{/b} potions and elixirs."] = "{b}Alchimie:{/b} Tränke und Elixiere.",
  ["{b}Blacksmithing:{/b} mail and plate sets for tanks, melee, healers and paladins, and three weapons."] = "{b}Schmiedekunst:{/b} Sets aus Schwerer Rüstung und Platte für Tanks, Nahkämpfer, Heiler und Paladine sowie drei Waffen.",
  ["{b}Cooking:{/b} six smoothies that give Spirit."] = "{b}Kochkunst:{/b} sechs Smoothies, die Willenskraft geben.",
  ["{b}Enchanting:{/b} necklace, weapon and armor enchants, relics (idols, totems and librams) and caster weapons (staves, off-hands and wands)."] = "{b}Verzauberkunst:{/b} Verzauberungen für Halsketten, Waffen und Rüstung, Reliquien (Götzen, Totems und Buchbände) und Zaubererwaffen (Stäbe, Schildhandgegenstände und Zauberstäbe).",
  ["{b}Engineering:{/b} bombs, thrown weapons, goggles, belts, trinkets and gadgets."] = "{b}Ingenieurskunst:{/b} Bomben, Wurfwaffen, Schutzbrillen, Gürtel, Schmuckstücke und Spielereien.",
  ["{b}Leatherworking:{/b} leather and mail sets for every role, and two armor kits."] = "{b}Lederverarbeitung:{/b} Leder- und Schwere-Rüstung-Sets für jede Rolle sowie zwei Rüstungssets.",
  ["{b}Tailoring:{/b} cloth sets for every spell school and for healers, and two reagent bags."] = "{b}Schneiderei:{/b} Stoffsets für jede Zauberschule und für Heiler sowie zwei Reagenzientaschen.",
  ["{b}The armor and weapons you craft from these recipes bind on pickup{/b}, so you can only make them for yourself."] = "{b}Die Rüstungen und Waffen, die du mit diesen Rezepten herstellst, werden beim Aufheben gebunden{/b}, du kannst sie also nur für dich selbst herstellen.",
  ["{n:0:horde:Apothecary Durelle} at the Horde camp and {n:0:alliance:Nina Surefire} at the Alliance camp sell 28 Alchemy recipes."] = "{n:0:horde:Apothecary Durelle} im Lager der Horde und {n:0:alliance:Nina Surefire} im Lager der Allianz verkaufen 28 Alchimierezepte.",
  ["Potions"] = "Tränke",
  ["Elixirs"] = "Elixiere",
  ["Req. Level"] = "Benötigte Stufe",
  ["Effect"] = "Effekt",
  ["Prof. Skill"] = "Berufsfertigkeit",
  ["+31 healing for 30 sec"] = "+31 Heilung für 30 Sek.",
  ["+16 spell damage for 30 sec"] = "+16 Zauberschaden für 30 Sek.",
  ["+28 attack power for 30 sec"] = "+28 Angriffskraft für 30 Sek.",
  ["282 Fire damage in a cone in front of you, then 35 every 2 sec for 8 sec"] = "282 Feuerschaden in einem Kegel vor dir, dann 8 Sek. lang alle 2 Sek. 35",
  ["Thrown, a cloud for 12 sec that deals 31-36 Nature damage every second to enemies in it"] = "Geworfen, eine Wolke für 12 Sek., die Gegnern darin jede Sekunde 31-36 Naturschaden zufügt",
  ["10 doses for 20 sec. When you take Bleed damage, a dose moves to a nearby enemy and deals 325 Nature damage when it ends"] = "10 Dosen für 20 Sek. Wenn du Blutungsschaden erleidest, springt eine Dose auf einen Gegner in der Nähe über und fügt ihm an ihrem Ende 325 Naturschaden zu",
  ["+88 healing for 30 sec"] = "+88 Heilung für 30 Sek.",
  ["+105 spell damage against Elementals for 5 min"] = "+105 Zauberschaden gegen Elementare für 5 Min.",
  ["+47 spell damage for 30 sec"] = "+47 Zauberschaden für 30 Sek.",
  ["+80 attack power for 30 sec"] = "+80 Angriffskraft für 30 Sek.",
  ["+6 Spirit for 30 min"] = "+6 Willenskraft für 30 Min.",
  ["6 mana every 5 sec for 30 min"] = "6 Mana alle 5 Sek. für 30 Min.",
  ["+6 Intellect for 30 min"] = "+6 Intelligenz für 30 Min.",
  ["+20 healing for 30 min"] = "+20 Heilung für 30 Min.",
  ["+15 spell damage for 30 min"] = "+15 Zauberschaden für 30 Min.",
  ["+18 Spirit for 30 min"] = "+18 Willenskraft für 30 Min.",
  ["20 mana every 5 sec for 30 min"] = "20 Mana alle 5 Sek. für 30 Min.",
  ["+40 healing for 30 min"] = "+40 Heilung für 30 Min.",
  ["+400 health for 30 min"] = "+400 Gesundheit für 30 Min.",
  ["+400 health and +500 armor for 30 min"] = "+400 Gesundheit und +500 Rüstung für 30 Min.",
  ["+25 Agility and Intellect for 30 min"] = "+25 Beweglichkeit und Intelligenz für 30 Min.",
  ["+18 Strength and Agility for 30 min"] = "+18 Stärke und Beweglichkeit für 30 Min.",
  ["+25 Spirit and 2% crit for 30 min"] = "+25 Willenskraft und 2 % krit. für 30 Min.",
  ["+25 Intellect and 2% crit for 30 min"] = "+25 Intelligenz und 2 % krit. für 30 Min.",
  ["+40 Nature spell damage for 30 min"] = "+40 Naturzauberschaden für 30 Min.",
  ["9 health and 10 mana every 5 sec for 30 min"] = "9 Gesundheit und 10 Mana alle 5 Sek. für 30 Min.",
  ["+25 Strength and 2% crit for 30 min"] = "+25 Stärke und 2 % krit. für 30 Min.",
  ["{n:0:horde:Gor'mak} at the Horde camp and {n:0:alliance:Stondry Darkhammer} at the Alliance camp sell 61 Blacksmithing recipes."] = "{n:0:horde:Gor'mak} im Lager der Horde und {n:0:alliance:Stondry Darkhammer} im Lager der Allianz verkaufen 61 Schmiedekunstrezepte.",
  ["Melee DPS"] = "Nahkampf-DPS",
  ["Healer"] = "Heiler",
  ["Paladin Tank"] = "Paladin-Tank",
  ["Retribution"] = "Vergeltung",
  ["Slot"] = "Platz",
  ["Waist"] = "Taille",
  ["Hands"] = "Hände",
  ["Feet"] = "Füße",
  ["Head"] = "Kopf",
  ["Chest"] = "Brust",
  ["Legs"] = "Beine",
  ["Shoulder"] = "Schulter",
  ["Wrist"] = "Handgelenke",
  ["One-Hand Fist Weapon"] = "Einhand-Faustwaffe",
  ["Two-Hand Polearm"] = "Zweihand-Stangenwaffe",
  ["Two-Hand Mace"] = "Zweihandstreitkolben",
  ["{n:0:horde:Aza'bek} at the Horde camp and {n:0:alliance:Kalsey Sanden} at the Alliance camp sell 6 Cooking recipes (all of them mana drinks)."] = "{n:0:horde:Aza'bek} im Lager der Horde und {n:0:alliance:Kalsey Sanden} im Lager der Allianz verkaufen 6 Kochrezepte (alles Managetränke).",
  ["+1 Spirit for 15 min"] = "+1 Willenskraft für 15 Min.",
